import React, { useState, useEffect } from 'react';
import { View, ActivityIndicator, Text, TouchableOpacity, StyleSheet, Platform, TouchableWithoutFeedback, ScrollView } from 'react-native';
import { Slot, usePathname, useRouter } from 'expo-router';
import { Colors, Spacing, BorderRadius } from '@/constants/theme';
import { useColorScheme } from '@/hooks/use-color-scheme';
import { useAuth } from '@/context/AuthContext';
import { Ionicons } from '@expo/vector-icons';
import { SafeAreaView } from 'react-native-safe-area-context';
import DevToolsFAB from '@/components/DevToolsFAB';

export default function AdminLayout() {
  const { user } = useAuth();
  const scheme = useColorScheme();
  const themeColors = Colors[scheme === 'dark' ? 'dark' : 'light'];
  const pathname = usePathname();
  const router = useRouter();

  const [isHoveringHeader, setIsHoveringHeader] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  useEffect(() => {
    setIsHoveringHeader(false);
  }, [pathname]);

  if (!user || (user.rol !== 'ADMIN' && user.rol !== 'DEV')) {
    return (
      <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', backgroundColor: themeColors.background }}>
        <ActivityIndicator size="large" color={themeColors.accent} />
      </View>
    );
  }

  const isDashboard = pathname === '/dashboard' || pathname === '/(admin)/dashboard' || pathname === '/perfil' || pathname === '/(admin)/perfil';

  // Odoo style top header
  const getModuleName = () => {
    const parts = pathname.split('/');
    let lastPart = parts[parts.length - 1];
    
    // Si el último segmento es un UUID (detalle), usar el segmento anterior
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (uuidRegex.test(lastPart) && parts.length > 1) {
      lastPart = parts[parts.length - 2];
    }

    if (!lastPart || lastPart === 'dashboard') return 'Inicio';
    return lastPart.charAt(0).toUpperCase() + lastPart.slice(1).replace(/-/g, ' ');
  };

  const quickLinks = [
    { route: '/(admin)/ventas', icon: 'cart-outline', color: '#ff6b6b', name: 'Ventas' },
    { route: '/(admin)/facturacion', icon: 'receipt-outline', color: '#0984e3', name: 'Facturación CFDI' },
    { route: '/(admin)/gastos', icon: 'cash-outline', color: '#feca57', name: 'Gastos' },
    { route: '/(admin)/facturas-recibidas', icon: 'receipt-outline', color: '#2e86de', name: 'Facturas Recibidas' },
    { route: '/(admin)/cotizaciones', icon: 'document-text-outline', color: '#54a0ff', name: 'Cotizaciones' },
    { route: '/(admin)/tareas', icon: 'checkbox-outline', color: '#f39c12', name: 'Tareas' },
    { route: '/(admin)/inventario', icon: 'cube-outline', color: '#48dbfb', name: 'Inventario' },
    { route: '/(admin)/empleados', icon: 'people-outline', color: '#1dd1a1', name: 'Empleados' },
    { route: '/(admin)/vehiculos', icon: 'car-outline', color: '#ff9ff3', name: 'Flota' },
    { route: '/(admin)/evidencias', icon: 'briefcase-outline', color: '#ff5252', name: 'Evidencias' },
    { route: '/(admin)/reportes', icon: 'document-text-outline', color: '#10ac84', name: 'Reportes' },
    { route: '/(admin)/catalogos', icon: 'list-outline', color: '#5f27cd', name: 'Catálogos' },
    { route: '/(admin)/auditoria-tarjeta', icon: 'shield-checkmark-outline', color: '#ff9f43', name: 'Auditoría' },
    { route: '/(admin)/documentos', icon: 'create-outline', color: '#0284c7', name: 'Documentos' },
    { route: '/(admin)/chat-ia', icon: 'sparkles-outline', color: '#2e86de', name: 'Chat IA' },
  ];

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: themeColors.background }} edges={['top', 'bottom', 'left', 'right']}>
      {/* Header estilo Odoo (Solo fuera del inicio) */}
      {!isDashboard && (
        <View style={[styles.header, { borderBottomColor: themeColors.border }]}>
          <TouchableOpacity
            style={styles.headerTitleContainer}
            onPress={() => {
              setIsMenuOpen(false);
              if (pathname.includes('editar-gasto') || pathname.includes('formulario') || pathname.includes('nueva-cotizacion')) {
                router.back();
              } else {
                router.replace('/(admin)/dashboard');
              }
            }}
            // @ts-ignore
            onMouseEnter={() => setIsHoveringHeader(true)}
            // @ts-ignore
            onMouseLeave={() => setIsHoveringHeader(false)}
            activeOpacity={0.7}
          >
            {isHoveringHeader || Platform.OS !== 'web' ? (
              <Ionicons name="arrow-back" size={24} color={themeColors.text} style={{ marginRight: 8 }} />
            ) : null}
            <Text style={[styles.headerTitle, { color: themeColors.text }]}>
              {isHoveringHeader && Platform.OS === 'web' ? 'Volver al Inicio' : getModuleName()}
            </Text>
          </TouchableOpacity>

          <View style={{ flex: 1 }} />

          {/* Botón de Formulario (Solo en Gastos) */}
          {(pathname === '/gastos' || pathname === '/(admin)/gastos') && (
            <TouchableOpacity 
              style={[styles.menuButton, { marginRight: 4 }]} 
              onPress={() => {
                setIsMenuOpen(false);
                router.push('/(admin)/formulario');
              }}
              activeOpacity={0.7}
            >
              <Ionicons name="ticket-outline" size={26} color={themeColors.text} />
            </TouchableOpacity>
          )}

          {/* Botón de Menú Desplegable */}
          <TouchableOpacity 
            style={styles.menuButton} 
            onPress={() => setIsMenuOpen(!isMenuOpen)}
            activeOpacity={0.7}
          >
            <Ionicons name="menu" size={28} color={themeColors.text} />
          </TouchableOpacity>
        </View>
      )}

      {/* Contenido Principal */}
      <View style={{ flex: 1, backgroundColor: themeColors.background, zIndex: 1 }}>
        <Slot />
      </View>

      {/* Dropdown Menu Overlay */}
      {!isDashboard && isMenuOpen && (
        <>
          <TouchableWithoutFeedback onPress={() => setIsMenuOpen(false)}>
            <View style={styles.dropdownOverlay} />
          </TouchableWithoutFeedback>
          <View style={[styles.dropdownMenu, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border }]}>
            <ScrollView style={{ maxHeight: 620 }} bounces={false}>
              {quickLinks.map((link, index) => (
                <TouchableOpacity
                  key={index}
                  style={[styles.dropdownItem, { borderBottomColor: themeColors.border, borderBottomWidth: index === quickLinks.length - 1 ? 0 : 1 }]}
                  onPress={() => {
                    setIsMenuOpen(false);
                    router.replace(link.route as any);
                  }}
                >
                  <View style={[styles.dropdownIconContainer, { backgroundColor: link.color + '15' }]}>
                    <Ionicons name={link.icon as any} size={20} color={link.color} />
                  </View>
                  <Text style={[styles.dropdownText, { color: themeColors.text }]}>{link.name}</Text>
                </TouchableOpacity>
              ))}
            </ScrollView>
          </View>
        </>
      )}

      <DevToolsFAB />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  header: {
    height: 56,
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: Spacing.three,
    borderBottomWidth: 1,
    zIndex: 10,
  },
  headerTitleContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 8,
    paddingRight: 16,
  },
  headerTitle: {
    fontSize: 20,
    fontWeight: '700',
  },
  menuButton: {
    padding: 8,
  },
  dropdownOverlay: {
    ...(StyleSheet.absoluteFill as any),
    zIndex: 5,
  },
  dropdownMenu: {
    position: 'absolute',
    top: 56,
    right: 16,
    width: 220,
    borderRadius: BorderRadius.medium,
    borderWidth: 1,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.15,
    shadowRadius: 12,
    elevation: 8,
    zIndex: 10,
    overflow: 'hidden',
  },
  dropdownItem: {
    flexDirection: 'row',
    alignItems: 'center',
    padding: Spacing.three,
  },
  dropdownIconContainer: {
    width: 36,
    height: 36,
    borderRadius: 18,
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: Spacing.three,
  },
  dropdownText: {
    fontSize: 15,
    fontWeight: '500',
  }
});

import React, { useState, useMemo, useCallback } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  ActivityIndicator,
  Alert,
  Platform,
  TextInput,
  FlatList,
  Modal,
  Image,
  useWindowDimensions,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useRouter } from 'expo-router';
import { Ionicons } from '@expo/vector-icons';
import * as DocumentPicker from 'expo-document-picker';
import * as Print from 'expo-print';
import * as Sharing from 'expo-sharing';

import { useColorScheme } from '@/hooks/use-color-scheme';
import { Colors, Spacing, BorderRadius } from '@/constants/theme';
import { supabase, Gasto, GastoHelper, AuditoriaService, AuditoriaTarjeta } from '@/services/supabase';
import { getApiHeaders, getApiUrl } from '@/services/apiHelper';
import { GeminiService, CardTransaction, CardStatementResult } from '@/services/gemini';
import ImageViewerModal from '@/components/ImageViewerModal';
import { useAuth } from '@/context/AuthContext';

// ─── Constants ────────────────────────────────────────────────────────────────

const TARJETAS = [
  { key: 'BBVA',    label: 'BBVA',     color: '#004A97' },
  { key: 'AMEX',    label: 'AMEX',     color: '#016FD0' },
  { key: 'MARRIOT', label: 'Marriott', color: '#B5121B' },
  { key: 'BANORTE', label: 'Banorte',  color: '#C8102E' },
  { key: 'INVEX',   label: 'Invex',    color: '#F48220' },
];

const TIPOS_PAGO = [
  { key: 'tarjeta_credito', label: 'Crédito',    icon: 'card-outline' as const },
  { key: 'tarjeta_debito',  label: 'Débito',     icon: 'wallet-outline' as const },
  { key: 'tarjeta',         label: 'Cualquiera', icon: 'apps-outline' as const },
];

// ─── Helpers ─────────────────────────────────────────────────────────────────

const showAlert = (title: string, message: string) => {
  if (Platform.OS === 'web') {
    window.alert(`${title}\n\n${message}`);
  } else {
    Alert.alert(title, message);
  }
};

const formatCurrency = (val: number) =>
  '$' + val.toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const toMs = (dateStr: string | null): number | null => {
  if (!dateStr) return null;
  const d = new Date(dateStr + 'T00:00:00Z');
  return isNaN(d.getTime()) ? null : d.getTime();
};

const DAY_MS = 86_400_000;
const MATCH_TOLERANCE_DAYS = 3;
const AMOUNT_TOLERANCE = 0.05;

// ─── Types ────────────────────────────────────────────────────────────────────

type TarjetaKey = 'BBVA' | 'AMEX' | 'MARRIOT' | 'BANORTE' | 'INVEX';
type MetodoPagoKey = 'tarjeta_credito' | 'tarjeta_debito' | 'tarjeta';

interface MatchedTransaction {
  transaction: CardTransaction;
  matchedGastos: Gasto[];
}

// ─── Screen ──────────────────────────────────────────────────────────────────

export default function AuditoriaTarjetaScreen() {
  const router = useRouter();
  const { width: windowWidth } = useWindowDimensions();
  const scheme = useColorScheme();
  const themeColors = Colors[scheme === 'dark' ? 'dark' : 'light'];
  const isMobile = windowWidth < 600;
  const { company, user } = useAuth();
  const companyName = company === 'daravisa' ? 'Daravisa' : 'Inttec';

  // Tab selector
  const [activeTab, setActiveTab] = useState<'nueva' | 'historial'>('nueva');

  // Card selector
  const [selectedTarjeta, setSelectedTarjeta] = useState<TarjetaKey | null>(null);
  const [selectedMetodoPago, setSelectedMetodoPago] = useState<MetodoPagoKey>('tarjeta_credito');

  // File
  const [fileBase64, setFileBase64] = useState<string | null>(null);
  const [fileMimeType, setFileMimeType] = useState<string>('application/pdf');
  const [fileName, setFileName] = useState<string | null>(null);

  // Analysis
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isGeneratingPDF, setIsGeneratingPDF] = useState(false);
  const [statementResult, setStatementResult] = useState<CardStatementResult | null>(null);
  const [matchedList, setMatchedList] = useState<MatchedTransaction[]>([]);
  const [appGastos, setAppGastos] = useState<Gasto[]>([]);

  // History states
  const [isLoadingHistorial, setIsLoadingHistorial] = useState(false);
  const [auditoriasHistorial, setAuditoriasHistorial] = useState<AuditoriaTarjeta[]>([]);
  const [historialTarjetaFilter, setHistorialTarjetaFilter] = useState<'TODAS' | TarjetaKey>('TODAS');
  const [selectedSavedAudit, setSelectedSavedAudit] = useState<AuditoriaTarjeta | null>(null);
  const [isSavingAuditoria, setIsSavingAuditoria] = useState(false);

  // UI
  const [searchQuery, setSearchQuery] = useState('');
  const [filterTab, setFilterTab] = useState<'todos' | 'reportados' | 'no_reportados'>('todos');
  const [selectedMatch, setSelectedMatch] = useState<MatchedTransaction | null>(null);
  const [selectedGastosToLink, setSelectedGastosToLink] = useState<Set<string>>(new Set());
  const [photoViewerUrl, setPhotoViewerUrl] = useState<string | null>(null);

  const selectedTarjetaInfo = TARJETAS.find(t => t.key === selectedTarjeta);
  const selectedMetodoPagoInfo = TIPOS_PAGO.find(m => m.key === selectedMetodoPago);
  const canUpload = !!selectedTarjeta;

  // ─────────────────────────────────────────────────────────────────────────────
  // File selection
  // ─────────────────────────────────────────────────────────────────────────────

  const handleSelectFile = async () => {
    if (!selectedTarjeta) {
      showAlert('Selecciona una tarjeta', 'Primero elige la tarjeta corporativa del estado de cuenta.');
      return;
    }
    try {
      const result = await DocumentPicker.getDocumentAsync({
        type: ['application/pdf', 'image/*'],
        copyToCacheDirectory: true,
      });

      if (result.canceled || !result.assets?.[0]) return;

      const asset = result.assets[0];
      const uri = asset.uri;
      const mime = asset.mimeType || (uri.endsWith('.pdf') ? 'application/pdf' : 'image/jpeg');
      const isPdf = mime.includes('pdf') || uri.endsWith('.pdf') || asset.name?.endsWith('.pdf');
      const isImage = mime.startsWith('image/') || /\.(jpg|jpeg|png|webp)$/i.test(uri);

      if (!isPdf && !isImage) {
        showAlert('Formato no soportado', 'Selecciona un PDF o imagen (JPG, PNG, WEBP).');
        return;
      }

      setFileName(asset.name || 'estado_de_cuenta');
      setFileMimeType(mime);
      setStatementResult(null);
      setMatchedList([]);

      try {
        if (Platform.OS !== 'web') {
          // eslint-disable-next-line @typescript-eslint/no-require-imports
          const FileSys = require('expo-file-system/legacy');
          const b64 = await new Promise<string>((resolve, reject) => {
            const xhr = new XMLHttpRequest();
            xhr.onload = () => {
              try {
                // Buffer is available globally in React Native / Expo
                const base64Str = Buffer.from(xhr.response).toString('base64');
                resolve(base64Str);
              } catch (e) {
                reject(e);
              }
            };
            xhr.onerror = reject;
            xhr.responseType = 'arraybuffer';
            xhr.open('GET', uri, true);
            xhr.send(null);
          });
          setFileBase64(b64);
        } else {
          const response = await fetch(uri);
          const blob = await response.blob();
          const reader = new FileReader();
          reader.onload = () => {
            const dataUrl = reader.result as string;
            setFileBase64(dataUrl.split(',')[1] || '');
          };
          reader.readAsDataURL(blob);
        }
      } catch (readErr: any) {
        showAlert('Error', 'No se pudo leer el archivo. Intenta de nuevo.');
        console.error('Read error:', readErr);
      }
    } catch (err) {
      console.error('Document picker error:', err);
      showAlert('Error', 'No se pudo seleccionar el archivo.');
    }
  };

  // ─────────────────────────────────────────────────────────────────────────────
  // Analysis + cross-reference
  // ─────────────────────────────────────────────────────────────────────────────

  const handleAnalyze = async () => {
    if (!selectedTarjeta) {
      showAlert('Sin tarjeta', 'Selecciona la tarjeta corporativa primero.');
      return;
    }
    if (!fileBase64) {
      showAlert('Sin archivo', 'Primero selecciona el estado de cuenta.');
      return;
    }

    setIsAnalyzing(true);
    try {
      // 1. Extract transactions via Gemini
      const result = await GeminiService.analyzeCardStatement(fileBase64, fileMimeType);
      setStatementResult(result);

      const cargos = result.transacciones.filter(t => t.tipo !== 'abono');
      if (cargos.length === 0) {
        showAlert('Sin cargos', 'No se encontraron cargos en el estado de cuenta.');
        setIsAnalyzing(false);
        return;
      }

      // 2. Date range
      const fechaMs = cargos.map(t => toMs(t.fecha)).filter(Boolean) as number[];
      const minDate = fechaMs.length > 0
        ? new Date(Math.min(...fechaMs) - DAY_MS * MATCH_TOLERANCE_DAYS).toISOString().split('T')[0]
        : result.periodo_inicio || '2000-01-01';
      const maxDate = fechaMs.length > 0
        ? new Date(Math.max(...fechaMs) + DAY_MS * MATCH_TOLERANCE_DAYS).toISOString().split('T')[0]
        : result.periodo_fin || new Date().toISOString().split('T')[0];

      // 3. Fetch gastos filtered by SPECIFIC card AND payment method via API
      const headers = await getApiHeaders();
      const queryParams = new URLSearchParams({
        tarjeta: selectedTarjeta,
        minDate,
        maxDate,
        metodoPago: selectedMetodoPago
      });
      const res = await fetch(`${getApiUrl()}/api/auditoria/gastos?${queryParams.toString()}`, { headers });
      if (!res.ok) throw new Error('Error al obtener gastos');
      const data = await res.json();
      const gastos: Gasto[] = data.gastos || [];

      // 4. Cross-reference each cargo with a reported expense
      const usedGastoIds = new Set<string>();
      const matched: MatchedTransaction[] = cargos.map(cargo => {
        const cargoMs = toMs(cargo.fecha);
        const cargoMonto = Number(cargo.monto) || 0;

        const candidate = gastos.find(g => {
          if (usedGastoIds.has(g.id)) return false;
          const gastoMs = toMs(g.fecha_comprobante ?? null);
          const montoMatch = Math.abs((Number(g.monto) || 0) - cargoMonto) <= AMOUNT_TOLERANCE;
          const dateMatch = cargoMs !== null && gastoMs !== null
            ? Math.abs(cargoMs - gastoMs) <= MATCH_TOLERANCE_DAYS * DAY_MS
            : false;
          return montoMatch && dateMatch;
        });

        if (candidate) usedGastoIds.add(candidate.id);
        return { transaction: cargo, matchedGastos: candidate ? [candidate] : [] };
      });

      setAppGastos(gastos);
      setMatchedList(matched);
    } catch (err: any) {
      console.error('Analysis error:', err);
      showAlert('Error de análisis', err.message || 'No se pudo analizar el estado de cuenta.');
    } finally {
      setIsAnalyzing(false);
    }
  };

  // ─────────────────────────────────────────────────────────────────────────────
  // Derived state
  // ─────────────────────────────────────────────────────────────────────────────

  const stats = useMemo(() => {
    const reportados = matchedList.filter(m => m.matchedGastos.length > 0);
    const noReportados = matchedList.filter(m => m.matchedGastos.length === 0);
    const totalCargos = matchedList.reduce((s, m) => s + (m.transaction.monto ?? 0), 0);
    const totalNoReportado = noReportados.reduce((s, m) => s + (m.transaction.monto ?? 0), 0);
    return { reportados, noReportados, totalCargos, totalNoReportado };
  }, [matchedList]);

  const filteredList = useMemo(() => {
    let list = matchedList;
    if (filterTab === 'reportados') list = list.filter(m => m.matchedGastos.length > 0);
    if (filterTab === 'no_reportados') list = list.filter(m => m.matchedGastos.length === 0);
    const q = searchQuery.trim().toLowerCase();
    if (q) {
      list = list.filter(m =>
        m.transaction.descripcion?.toLowerCase().includes(q) ||
        m.transaction.fecha?.includes(q) ||
        String(m.transaction.monto).includes(q) ||
        m.matchedGastos.some(g =>
          g.justificacion?.toLowerCase().includes(q) ||
          GastoHelper.getProveedor(g)?.toLowerCase().includes(q) ||
          g.empleado_nombre?.toLowerCase().includes(q)
        )
      );
    }
    return list;
  }, [matchedList, filterTab, searchQuery]);

  const availableGastos = useMemo(() => {
    const usedIds = new Set<string>();
    matchedList.forEach(m => {
      if (m !== selectedMatch) {
        m.matchedGastos.forEach(g => usedIds.add(g.id));
      }
    });
    return appGastos.filter(g => !usedIds.has(g.id));
  }, [appGastos, matchedList, selectedMatch]);

  const handleLinkSelectedGastos = () => {
    if (!selectedMatch || selectedGastosToLink.size === 0) return;
    const gastosToLink = availableGastos.filter(g => selectedGastosToLink.has(g.id));
    
    // Update matchedList in memory
    setMatchedList(prev => prev.map(m => {
      if (m === selectedMatch) {
        return { ...m, matchedGastos: gastosToLink };
      }
      return m;
    }));
    
    // Reset and close
    setSelectedMatch(null);
    setSelectedGastosToLink(new Set());
  };

  // ─────────────────────────────────────────────────────────────────────────────
  // Persisted History Operations
  // ─────────────────────────────────────────────────────────────────────────────

  const loadHistorialAuditorias = async () => {
    setIsLoadingHistorial(true);
    try {
      const data = await AuditoriaService.obtenerAuditorias();
      setAuditoriasHistorial(data);
    } catch (err: any) {
      console.error('Error loading card audit history:', err);
      showAlert('Error', 'No se pudo cargar el historial de auditorías.');
    } finally {
      setIsLoadingHistorial(false);
    }
  };

  const handleSaveAuditoria = async () => {
    if (!selectedTarjeta) return;
    if (matchedList.length === 0) {
      showAlert('Sin datos', 'No hay un resultado de análisis para guardar.');
      return;
    }

    setIsSavingAuditoria(true);
    try {
      const totalConciliado = stats.reportados.reduce((s, m) => s + (m.transaction.monto || 0), 0);
      await AuditoriaService.guardarAuditoria({
        tarjeta: selectedTarjeta,
        metodo_pago: selectedMetodoPago,
        titular: statementResult?.titular || 'Desconocido',
        periodo_inicio: statementResult?.periodo_inicio || null,
        periodo_fin: statementResult?.periodo_fin || null,
        total_cargos: stats.totalCargos,
        total_conciliado: totalConciliado,
        total_faltante: stats.totalNoReportado,
        resultado_json: {
