    fontWeight: '700',
  },
  modalFieldList: {
    gap: 0,
  },
  modalPhoto: {
    width: '100%',
    height: 180,
    borderRadius: BorderRadius.medium,
    marginBottom: Spacing.one,
  },
  photoTapHint: {
    position: 'absolute',
    bottom: Spacing.one,
    left: 0,
    right: 0,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 6,
    paddingVertical: 6,
    borderBottomLeftRadius: BorderRadius.medium,
    borderBottomRightRadius: BorderRadius.medium,
  },
  photoTapHintText: {
    color: '#fff',
    fontSize: 11,
    fontWeight: '700',
  },
  modalPhotoPlaceholder: {
    width: '100%',
    height: 80,
    borderRadius: BorderRadius.medium,
    alignItems: 'center',
    justifyContent: 'center',
    gap: 6,
    marginBottom: Spacing.one,
  },
  modalPhotoPlaceholderText: {
    fontSize: 11,
    fontWeight: '600',
  },
  matchConnector: {
