                              flex: 1,
                              minWidth: '45%',
                              alignItems: 'center',
                              paddingVertical: Spacing.one,
                            },
                          ]}
                        >
                          <Text style={[styles.paymentOptionText, { color: tipoTarjeta === card ? '#ffffff' : themeColors.text, fontSize: 11 }]}>
                            {card}
                          </Text>
                        </TouchableOpacity>
                      ))}
                    </View>
                  </View>
                </View>
              )}

