                </View>
              </View>

              {/* Tarjeta 2: Reporte de Asistencia */}
              <View style={[styles.configCard, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border, flexDirection: 'column', alignItems: 'stretch', gap: Spacing.one }]}>
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: Spacing.two }}>
                  <Ionicons name="time-outline" size={28} color={themeColors.accent} />
                  <View style={{ flex: 1 }}>
                    <Text style={[styles.configCardTitle, { color: themeColors.text }]}>Reporte de Asistencia</Text>
                    <Text style={{ color: themeColors.textSecondary, fontSize: 11 }}>
                      Entradas, salidas y ubicaciones de checado del personal.
                    </Text>
                  </View>
                </View>
                <View style={{ flexDirection: 'row', gap: Spacing.two, marginTop: 4 }}>
                  <CustomButton title="PDF" onPress={handleExportAsistenciasPDF} style={{ flex: 1, height: 36 }} loading={isFetchingAsistencias} />
                  <CustomButton title="Excel (CSV)" onPress={handleExportAsistenciasCSV} variant="success" style={{ flex: 1, height: 36 }} loading={isFetchingAsistencias} />
                </View>
              </View>

              {/* Tarjeta 3: Reporte de Inventario */}
              <View style={[styles.configCard, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border, flexDirection: 'column', alignItems: 'stretch', gap: Spacing.one }]}>
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: Spacing.two }}>
                  <Ionicons name="cube-outline" size={28} color={themeColors.accent} />
                  <View style={{ flex: 1 }}>
                    <Text style={[styles.configCardTitle, { color: themeColors.text }]}>Reporte de Inventario</Text>
                    <Text style={{ color: themeColors.textSecondary, fontSize: 11 }}>
                      Catálogo de productos, categorías y existencias en stock.
                    </Text>
                  </View>
                </View>
                <View style={{ flexDirection: 'row', gap: Spacing.two, marginTop: 4 }}>
                  <CustomButton title="PDF" onPress={handleExportInventarioPDF} style={{ flex: 1, height: 36 }} loading={isFetchingInventario} />
                  <CustomButton title="Excel (CSV)" onPress={handleExportInventarioCSV} variant="success" style={{ flex: 1, height: 36 }} loading={isFetchingInventario} />
                </View>
              </View>

              {/* Tarjeta 4: Reporte de Consumos */}
              <View style={[styles.configCard, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border, flexDirection: 'column', alignItems: 'stretch', gap: Spacing.one, marginTop: Spacing.two }]}>
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: Spacing.two }}>
                  <Ionicons name="receipt-outline" size={28} color={themeColors.accent} />
                  <View style={{ flex: 1 }}>
                    <Text style={[styles.configCardTitle, { color: themeColors.text }]}>Reporte de Consumos</Text>
                    <Text style={{ color: themeColors.textSecondary, fontSize: 11 }}>
                      Historial detallado de salidas y consumos de materiales.
                    </Text>
                  </View>
                </View>
                <View style={{ flexDirection: 'row', gap: Spacing.two, marginTop: 4 }}>
                  <CustomButton title="PDF" onPress={handleExportConsumosPDF} style={{ flex: 1, height: 36 }} loading={isFetchingConsumos} />
                  <CustomButton title="Excel (CSV)" onPress={handleExportConsumosCSV} variant="success" style={{ flex: 1, height: 36 }} loading={isFetchingConsumos} />
                </View>
              </View>

              {/* Tarjeta 5: Reporte de Ventas */}
              <View style={[styles.configCard, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border, flexDirection: 'column', alignItems: 'stretch', gap: Spacing.one, marginTop: Spacing.two }]}>
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: Spacing.two }}>
                  <Ionicons name="bar-chart-outline" size={28} color={themeColors.success} />
                  <View style={{ flex: 1 }}>
                    <Text style={[styles.configCardTitle, { color: themeColors.text }]}>Reporte de Ventas</Text>
                    <Text style={{ color: themeColors.textSecondary, fontSize: 11 }}>
                      Resumen financiero de facturación, costos, utilidades y márgenes.
                    </Text>
                  </View>
                </View>
                <View style={{ flexDirection: 'row', gap: Spacing.two, marginTop: 4 }}>
                  <CustomButton title="PDF" onPress={handleExportVentasPDF} style={{ flex: 1, height: 36 }} loading={isFetchingVentas} />
                  <CustomButton title="Excel (CSV)" onPress={handleExportVentasCSV} variant="success" style={{ flex: 1, height: 36 }} loading={isFetchingVentas} />
                </View>
              </View>
            </ScrollView>
          </View>
        </View>
      </Modal>

      {/* Modal de Detalle/Revisión de Gasto */}
      <Modal statusBarTranslucent={true}
        animationType="slide"
        transparent={true}
        visible={reviewModalVisible}
        onRequestClose={() => {
          setReviewModalVisible(false);
          setSelectedGasto(null);
          setRejectionFeedback('');
          setShowFeedbackInput(false);
        }}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, { backgroundColor: themeColors.background }]}>
            <View style={styles.modalHeader}>
              <Text style={[styles.modalTitle, { color: themeColors.text }]}>Revisión de Gasto</Text>
              <TouchableOpacity
                onPress={() => {
                  setReviewModalVisible(false);
                  setSelectedGasto(null);
                  setRejectionFeedback('');
                  setShowFeedbackInput(false);
                }}
              >
                <Ionicons name="close" size={24} color={themeColors.text} />
              </TouchableOpacity>
            </View>

            {selectedGasto && (
              <ScrollView contentContainerStyle={styles.modalScroll}>
                {selectedGasto.foto_url ? (
                  <TouchableOpacity
                    activeOpacity={0.9}
                    onPress={() => {
                      setActivePreviewUrl(selectedGasto.foto_url!);
                      setViewerVisible(true);
                    }}
                    style={styles.modalImageContainer}
                  >
                    <Image source={{ uri: selectedGasto.foto_url }} style={styles.modalImage} resizeMode="contain" />
                  </TouchableOpacity>
                ) : (
                  <View style={[styles.modalNoImage, { backgroundColor: themeColors.backgroundElement }]}>
                    <Ionicons name="image-outline" size={48} color={themeColors.textSecondary} />
                    <Text style={{ color: themeColors.textSecondary }}>Sin fotografía de ticket</Text>
                  </View>
                )}

                <View style={styles.modalDetails}>
                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Monto</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text, fontSize: 22, fontWeight: '800' }]}>
                      {formatCurrency(selectedGasto.monto)}
                    </Text>
                  </View>

                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Empleado</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text, fontWeight: '700' }]}>
                      {selectedGasto.empleado_nombre || 'N/D'}
                    </Text>
                  </View>

                  {(selectedGasto.tipo_servicio_proyecto || selectedGasto.detalle_servicio_proyecto) && (
                    <View style={styles.detailItem}>
                      <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Servicio / Proyecto</Text>
                      <Text style={[styles.detailValue, { color: themeColors.text }]}>
                        {selectedGasto.tipo_servicio_proyecto ? `Tipo: ${selectedGasto.tipo_servicio_proyecto}` : ''}
                        {selectedGasto.detalle_servicio_proyecto ? `\nDetalle: ${selectedGasto.detalle_servicio_proyecto}` : ''}
                      </Text>
                    </View>
                  )}

                  <View style={[styles.detailItem, { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }]}>
                    <View style={{ flex: 1, marginRight: Spacing.two }}>
                      <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Proveedor</Text>
                      <Text style={[styles.detailValue, { color: GastoHelper.getProveedor(selectedGasto) ? themeColors.text : themeColors.danger, fontWeight: '700', fontSize: 15 }]}>
                        {GastoHelper.getProveedor(selectedGasto) || '⚠️ En blanco (Sin asignar)'}
                      </Text>
                    </View>
                    <TouchableOpacity
                      onPress={() => handleOpenQuickEditProveedor(selectedGasto)}
                      style={{
                        flexDirection: 'row',
                        alignItems: 'center',
                        gap: 6,
                        paddingVertical: 7,
                        paddingHorizontal: 12,
                        borderRadius: BorderRadius.medium,
                        backgroundColor: themeColors.accent + '20',
                        borderWidth: 1,
                        borderColor: themeColors.accent,
                      }}
                    >
                      <Ionicons name="pencil" size={15} color={themeColors.accent} />
                      <Text style={{ color: themeColors.accent, fontWeight: '700', fontSize: 13 }}>
                        {GastoHelper.getProveedor(selectedGasto) ? 'Cambiar' : 'Asignar'}
                      </Text>
                    </TouchableOpacity>
                  </View>

                  {(!GastoHelper.getProveedor(selectedGasto) || !GastoHelper.getProveedor(selectedGasto).trim()) && (
                    <View style={[styles.alertBanner, { backgroundColor: themeColors.warning + '18', borderColor: themeColors.warning, marginVertical: Spacing.half, padding: Spacing.two, borderRadius: BorderRadius.medium, borderWidth: 1, flexDirection: 'row', gap: Spacing.one }]}>
                      <Ionicons name="alert-circle-outline" size={22} color={themeColors.warning} style={{ marginTop: 2 }} />
                      <View style={{ flex: 1 }}>
                        <Text style={[styles.alertTitle, { color: themeColors.warning, fontSize: 14, fontWeight: '700', marginBottom: 2 }]}>Proveedor Pendiente de Asignar</Text>
                        <Text style={[styles.alertText, { color: themeColors.text, fontSize: 13 }]}>
                          El empleado dejó el proveedor en blanco. Puedes asignarlo rápidamente aquí para poder aprobar el gasto.
                        </Text>
                        {(() => {
                          const parsed = parseJustificacion(selectedGasto.justificacion);
                          if (parsed.proveedorSugerido) {
                            return (
                              <View style={{ marginTop: 8, padding: 8, backgroundColor: themeColors.backgroundElement, borderRadius: BorderRadius.small, borderWidth: 1, borderColor: themeColors.border }}>
                                <Text style={{ fontSize: 12, fontWeight: '600', color: themeColors.text }}>
                                  📝 Proveedor a agregar indicado por el empleado:
                                </Text>
                                <Text style={{ fontSize: 13, fontWeight: '700', color: themeColors.primary, marginTop: 2, marginBottom: 6 }}>
                                  {parsed.proveedorSugerido}
                                </Text>
                                <TouchableOpacity
                                  onPress={() => handleQuickCreateProveedorAndAssign(parsed.proveedorSugerido!)}
                                  disabled={isSavingQuickProv}
                                  style={{
                                    flexDirection: 'row',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    gap: 6,
                                    backgroundColor: themeColors.primary,
                                    paddingVertical: 8,
                                    paddingHorizontal: 12,
                                    borderRadius: BorderRadius.small,
                                    marginTop: 4,
                                  }}
                                >
                                  {isSavingQuickProv ? (
                                    <ActivityIndicator size="small" color="#fff" />
                                  ) : (
                                    <>
                                      <Ionicons name="flash-outline" size={16} color="#fff" />
                                      <Text style={{ color: '#fff', fontWeight: '700', fontSize: 12 }}>
                                        ⚡ Asignar &quot;{parsed.proveedorSugerido}&quot;
                                      </Text>
                                    </>
                                  )}
                                </TouchableOpacity>
                              </View>
                            );
                          }
                          return (
                            <TouchableOpacity
                              onPress={() => handleOpenQuickEditProveedor(selectedGasto)}
                              style={{
                                flexDirection: 'row',
                                alignItems: 'center',
                                justifyContent: 'center',
                                gap: 6,
                                backgroundColor: themeColors.warning,
                                paddingVertical: 8,
                                paddingHorizontal: 12,
                                borderRadius: BorderRadius.small,
                                marginTop: 8,
                              }}
                            >
                              <Ionicons name="business-outline" size={16} color="#fff" />
                              <Text style={{ color: '#fff', fontWeight: '700', fontSize: 12 }}>
                                Asignar Proveedor Ahora
                              </Text>
                            </TouchableOpacity>
                          );
                        })()}
                      </View>
                    </View>
                  )}

                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Cliente / Sucursal</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text }]}>
                      {GastoHelper.getCliente(selectedGasto) || 'No especificado'} {GastoHelper.getSucursal(selectedGasto) ? `- Sucursal: ${GastoHelper.getSucursal(selectedGasto)}` : ''}
                    </Text>
                  </View>

                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Fecha de Gasto</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text }]}>
                      {formatFriendlyDate(selectedGasto.fecha_comprobante || selectedGasto.created_at?.split('T')[0])}
                    </Text>
                  </View>

                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Categoría / Subcategoría</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text }]}>
                      {GastoHelper.getCategoria(selectedGasto) || 'Sin Categoría'} {GastoHelper.getSubcategoria(selectedGasto) ? `> ${GastoHelper.getSubcategoria(selectedGasto)}` : ''}
                    </Text>
                  </View>

                  {/* Parsear justificación para ver si hay alerta de IA */}
                  {(() => {
                    const parsed = parseJustificacion(selectedGasto.justificacion);
                    return (
                      <>
                        {parsed.alerta && (
                          <View style={[styles.alertBanner, { backgroundColor: themeColors.danger + '15', borderColor: themeColors.danger, marginBottom: Spacing.two }]}>
                            <Ionicons name="warning-outline" size={22} color={themeColors.danger} style={{ marginTop: 2 }} />
                            <View style={{ flex: 1 }}>
                              <Text style={[styles.alertTitle, { color: themeColors.danger }]}>Alerta de Políticas de Gasto</Text>
                              <Text style={[styles.alertText, { color: themeColors.text }]}>{parsed.alerta}</Text>
                            </View>
                          </View>
                        )}
                        <View style={styles.detailItem}>
                          <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Pago / Comentarios</Text>
                          <Text style={[styles.detailValue, { color: themeColors.text }]}>
                            Método: {selectedGasto.metodo_pago} {selectedGasto.tipo_tarjeta ? `(${selectedGasto.tipo_tarjeta})` : ''}
                            {'\n'}Comentarios: {parsed.justificacion || 'No especificados'}
                          </Text>
                        </View>

                        {(!selectedGasto.facturado || selectedGasto.motivo_sin_factura) && (
                          <View style={[styles.detailItem, { backgroundColor: themeColors.warning + '15', padding: Spacing.two, borderRadius: BorderRadius.medium, borderLeftWidth: 4, borderLeftColor: themeColors.warning, marginVertical: Spacing.one }]}>
                            <Text style={[styles.detailLabel, { color: themeColors.warning, fontWeight: '700' }]}>
                              {selectedGasto.motivo_sin_factura?.startsWith('PENDIENTE') ? '⏳ Factura Pendiente de Entregar' : '⚠️ Motivo de Falta de Factura'}
                            </Text>
                            <Text style={[styles.detailValue, { color: themeColors.text, fontWeight: '600', marginTop: 2 }]}>
                              {selectedGasto.motivo_sin_factura
                                ? (selectedGasto.motivo_sin_factura.includes('PENDIENTE_ENTREGA:')
                                    ? selectedGasto.motivo_sin_factura.replace('PENDIENTE_ENTREGA:', 'Comentario:')
                                    : (selectedGasto.motivo_sin_factura === 'PENDIENTE_ENTREGA' ? 'Sin comentarios adicionales.' : selectedGasto.motivo_sin_factura))
                                : localMotivo || 'No especificado por el empleado'}
                            </Text>
                          </View>
                        )}

                        <View style={[styles.detailItem, { marginTop: Spacing.one, borderTopWidth: 1, borderTopColor: themeColors.border, paddingTop: Spacing.two }]}>
                          <Text style={[styles.detailLabel, { color: themeColors.textSecondary, fontWeight: '700', marginBottom: Spacing.one }]}>GESTIÓN DE FACTURACIÓN (ADMIN)</Text>
                          
                          {/* Selector de 3 Opciones: Sí Facturado / Pendiente de Factura / No Facturable */}
                          <View style={{ flexDirection: 'row', gap: Spacing.one, marginBottom: Spacing.two }}>
                            <TouchableOpacity
                              onPress={() => handleToggleAdminFacturado(true)}
                              style={{
                                flex: 1,
                                height: 38,
                                borderRadius: BorderRadius.small,
                                borderWidth: 1,
                                borderColor: selectedGasto.facturado ? 'transparent' : themeColors.border,
                                backgroundColor: selectedGasto.facturado ? themeColors.success : themeColors.backgroundElement,
                                justifyContent: 'center',
                                alignItems: 'center',
                                paddingHorizontal: 4
                              }}
                            >
                              <Text style={{ color: selectedGasto.facturado ? '#ffffff' : themeColors.text, fontWeight: '700', fontSize: 11, textAlign: 'center' }}>
                                ✓ Facturado
                              </Text>
                            </TouchableOpacity>

                            <TouchableOpacity
                              onPress={async () => {
                                try {
                                  const updateObj = { facturado: false, motivo_sin_factura: 'PENDIENTE_ENTREGA', factura_url: null };
                                  const { error: dbError } = await supabase.from('gastos').update(updateObj).eq('id', selectedGasto.id);
                                  if (dbError) throw dbError;
                                  const updated = { ...selectedGasto, ...updateObj };
                                  setSelectedGasto(updated);
                                  setGastos(prev => prev.map(g => g.id === selectedGasto.id ? updated : g));
                                  setLocalMotivo('PENDIENTE_ENTREGA');
                                } catch (err: any) {
                                  showAlert('Error', err.message);
                                }
                              }}
                              style={{
                                flex: 1.2,
                                height: 38,
                                borderRadius: BorderRadius.small,
                                borderWidth: 1,
                                borderColor: (!selectedGasto.facturado && selectedGasto.motivo_sin_factura?.includes('PENDIENTE')) ? 'transparent' : themeColors.border,
                                backgroundColor: (!selectedGasto.facturado && selectedGasto.motivo_sin_factura?.includes('PENDIENTE')) ? themeColors.warning : themeColors.backgroundElement,
                                justifyContent: 'center',
                                alignItems: 'center',
                                paddingHorizontal: 4
                              }}
                            >
                              <Text style={{ color: (!selectedGasto.facturado && selectedGasto.motivo_sin_factura?.includes('PENDIENTE')) ? '#ffffff' : themeColors.text, fontWeight: '700', fontSize: 11, textAlign: 'center' }}>
                                ⏳ Pend. Factura
                              </Text>
                            </TouchableOpacity>

                            <TouchableOpacity
                              onPress={() => handleToggleAdminFacturado(false)}
                              style={{
                                flex: 1,
                                height: 38,
                                borderRadius: BorderRadius.small,
                                borderWidth: 1,
                                borderColor: (!selectedGasto.facturado && !selectedGasto.motivo_sin_factura?.includes('PENDIENTE')) ? 'transparent' : themeColors.border,
                                backgroundColor: (!selectedGasto.facturado && !selectedGasto.motivo_sin_factura?.includes('PENDIENTE')) ? themeColors.accent : themeColors.backgroundElement,
                                justifyContent: 'center',
                                alignItems: 'center',
                                paddingHorizontal: 4
                              }}
                            >
                              <Text style={{ color: (!selectedGasto.facturado && !selectedGasto.motivo_sin_factura?.includes('PENDIENTE')) ? '#ffffff' : themeColors.text, fontWeight: '700', fontSize: 11, textAlign: 'center' }}>
                                ❌ No Facturado
                              </Text>
                            </TouchableOpacity>
                          </View>

                          {/* Secciones según el toggle */}
                          {selectedGasto.facturado ? (
                            <View style={{ gap: Spacing.one }}>
                              <Text style={{ color: themeColors.textSecondary, fontSize: 12, marginBottom: 2 }}>Archivo de Factura:</Text>
                              {selectedGasto.factura_url ? (
                                <View style={{ flexDirection: 'row', alignItems: 'center', gap: Spacing.two }}>
                                  <TouchableOpacity
                                    style={[styles.invoiceLinkBtn, { backgroundColor: themeColors.accent + '15', flex: 1, height: 40, justifyContent: 'center', borderRadius: BorderRadius.small }]}
                                    onPress={() => {
                                      const url = selectedGasto.factura_url!;
                                      if (url.toLowerCase().includes('.pdf')) {
                                        Linking.openURL(url).catch(() => {
                                          Alert.alert('Error', 'No se pudo abrir el archivo PDF.');
                                        });
                                      } else {
                                        setActivePreviewUrl(url);
                                        setViewerVisible(true);
                                      }
                                    }}
                                  >
                                    <Ionicons name="image-outline" size={18} color={themeColors.accent} />
                                    <Text style={[styles.invoiceLinkText, { color: themeColors.accent }]}>
                                      Ver Factura Adjunta
                                    </Text>
                                  </TouchableOpacity>
                                  
                                  <TouchableOpacity
                                    style={{
                                      backgroundColor: themeColors.danger + '15',
                                      padding: Spacing.one,
                                      borderRadius: BorderRadius.small,
                                      borderWidth: 1,
                                      borderColor: themeColors.danger + '40',
                                      height: 40,
                                      justifyContent: 'center',
                                      alignItems: 'center',
                                      aspectRatio: 1
                                    }}
                                    onPress={handleDeleteAdminInvoice}
                                    disabled={isUploadingInvoice}
                                  >
                                    <Ionicons name="trash-outline" size={18} color={themeColors.danger} />
                                  </TouchableOpacity>
                                </View>
                              ) : (
                                <View style={{ gap: Spacing.one }}>
                                  <Text style={{ color: themeColors.danger, fontSize: 12, fontStyle: 'italic', marginBottom: 4 }}>⚠️ Falta factura correspondiente</Text>
                                  {isUploadingInvoice ? (
                                    <View style={{ flexDirection: 'row', alignItems: 'center', gap: Spacing.one, padding: Spacing.one }}>
                                      <ActivityIndicator size="small" color={themeColors.accent} />
                                      <Text style={{ color: themeColors.text, fontSize: 12 }}>Subiendo archivo a Supabase...</Text>
                                    </View>
                                  ) : (
                                    <View style={{ flexDirection: 'row', gap: Spacing.one }}>
                                      <TouchableOpacity
                                        onPress={handleCaptureAdminInvoice}
                                        style={{ flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 4, height: 38, borderRadius: BorderRadius.small, borderWidth: 1, borderColor: themeColors.border, backgroundColor: themeColors.backgroundElement }}
                                      >
                                        <Ionicons name="camera-sharp" size={16} color={themeColors.text} />
                                        <Text style={{ color: themeColors.text, fontSize: 12, fontWeight: '600' }}>Cámara</Text>
                                      </TouchableOpacity>
                                      <TouchableOpacity
                                        onPress={handleSelectAdminInvoiceGallery}
                                        style={{ flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 4, height: 38, borderRadius: BorderRadius.small, borderWidth: 1, borderColor: themeColors.border, backgroundColor: themeColors.backgroundElement }}
                                      >
                                        <Ionicons name="images-sharp" size={16} color={themeColors.text} />
                                        <Text style={{ color: themeColors.text, fontSize: 12, fontWeight: '600' }}>Galería</Text>
                                      </TouchableOpacity>
                                      <TouchableOpacity
                                        onPress={handleSelectAdminInvoiceDocument}
                                        style={{ flex: 1, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 4, height: 38, borderRadius: BorderRadius.small, borderWidth: 1, borderColor: themeColors.border, backgroundColor: themeColors.backgroundElement }}
                                      >
                                        <Ionicons name="document-text-sharp" size={16} color={themeColors.text} />
                                        <Text style={{ color: themeColors.text, fontSize: 12, fontWeight: '600' }}>PDF</Text>
                                      </TouchableOpacity>
                                    </View>
                                  )}
                                </View>
                              )}
                            </View>
                          ) : (
                            <View style={{ gap: Spacing.one }}>
                              <CustomInput
                                label="Motivo de falta de factura:"
                                placeholder="Escribe el motivo (ej. Proveedor informal)..."
                                value={localMotivo}
                                onChangeText={setLocalMotivo}
                                onBlur={() => handleUpdateAdminMotivoSinFactura(localMotivo)}
                                onEndEditing={() => handleUpdateAdminMotivoSinFactura(localMotivo)}
                                style={{ height: 40 }}
                                iconName="warning-outline"
                              />
                            </View>
                          )}
                        </View>
                      </>
                    );
                  })()}

                  {/* Acciones para gastos PENDIENTES */}
                  {selectedGasto.status === 'PENDING' && (
                    <View style={styles.reviewActions}>
                      {selectedGasto.empleado_id === adminUser?.id && adminUser?.rol !== 'DEV' ? (
                        <View style={[styles.alertBanner, { backgroundColor: themeColors.warning + '15', borderColor: themeColors.warning, marginBottom: 0, padding: Spacing.two, borderRadius: BorderRadius.medium, borderWidth: 1, flexDirection: 'row', gap: Spacing.one }]}>
                          <Ionicons name="warning-outline" size={22} color={themeColors.warning} style={{ marginTop: 2 }} />
                          <View style={{ flex: 1 }}>
                            <Text style={[styles.alertTitle, { color: themeColors.warning, fontSize: 14, fontWeight: '700', marginBottom: 2 }]}>Revisión Cruzada</Text>
                            <Text style={[styles.alertText, { color: themeColors.text, fontSize: 13 }]}>
                              No puedes revisar tus propios gastos. Este registro debe ser aprobado o rechazado por otro administrador.
                            </Text>
                          </View>
                        </View>
                      ) : !showFeedbackInput ? (
                        <>
                          <View style={styles.rowActions}>
                            <CustomButton
                              title="Aprobar"
                              onPress={handleApproveClick}
                              variant="success"
                              style={{ flex: 1 }}
                              loading={isProcessingAction}
                            />
                            <CustomButton
                              title="Rechazar"
                              onPress={() => handleUpdateStatus('REJECTED')}
                              variant="danger"
                              style={{ flex: 1 }}
                              loading={isProcessingAction}
                            />
                          </View>
                          <CustomButton
                            title="Devolver (Acción Requerida)"
                            onPress={() => setShowFeedbackInput(true)}
                            variant="secondary"
                            style={{ width: '100%', marginTop: Spacing.one }}
                            disabled={isProcessingAction}
                          />
                          <CustomButton
                            title="Editar Gasto"
                            onPress={() => {
                              setReviewModalVisible(false);
                              router.push(`/(admin)/editar-gasto?id=${selectedGasto.id}` as any);
                            }}
                            variant="primary"
                            style={{ width: '100%', marginTop: Spacing.one }}
                            disabled={isProcessingAction}
                          />
                          <CustomButton
                            title="Eliminar Gasto Permanente"
                            onPress={() => handleDeleteGasto(selectedGasto.id)}
                            variant="danger"
                            style={{ width: '100%', marginTop: Spacing.one }}
                            loading={isProcessingAction}
                            icon={<Ionicons name="trash-outline" size={20} color="#fff" style={{ marginRight: 8 }} />}
                          />
                        </>
                      ) : (
                        <View style={styles.feedbackForm}>
                          <CustomInput
                            label="Duda / Comentario para el Empleado"
                            placeholder="Escribe la información faltante requerida..."
                            value={rejectionFeedback}
                            onChangeText={setRejectionFeedback}
                            multiline
                            numberOfLines={3}
                            style={{ height: 75 }}
                          />
                          <View style={styles.rowActions}>
                            <CustomButton
                              title="Cancelar"
                              onPress={() => setShowFeedbackInput(false)}
                              variant="secondary"
                              style={{ flex: 1 }}
                            />
                            <CustomButton
                              title="Enviar Observación"
                              onPress={() => handleUpdateStatus('ACTION_REQUIRED')}
                              variant="warning"
                              style={{ flex: 1.5 }}
                              loading={isProcessingAction}
                            />
                          </View>
                        </View>
                      )}
                    </View>
                  )}

                  {/* Detalle informativo de estado si ya fue resuelto */}
                  {selectedGasto.status !== 'PENDING' && (
                    <View style={{ gap: Spacing.two, marginTop: Spacing.two }}>
                      <View style={[styles.resolvedBadge, { backgroundColor: themeColors.backgroundSelected, marginBottom: 0 }]}>
                        <Text style={[styles.resolvedText, { color: themeColors.text, fontWeight: '700' }]}>
                          Estado de Revisión: {selectedGasto.status === 'APPROVED' ? 'Aprobado' : selectedGasto.status === 'REJECTED' ? 'Rechazado' : 'Acción Requerida'}
                        </Text>
                        {selectedGasto.rejection_feedback && (
                          <Text style={{ color: themeColors.textSecondary, fontSize: 13, marginTop: 4 }}>
                            {`Feedback enviado: "${selectedGasto.rejection_feedback}"`}
                          </Text>
                        )}
                      </View>
                      <CustomButton
                        title="Revertir a Pendiente (Revisión)"
                        onPress={() => {
                          if (Platform.OS === 'web') {
                            const confirmed = window.confirm('¿Estás seguro de que deseas regresar este gasto a la bandeja de pendientes para revisarlo nuevamente?');
                            if (confirmed) {
                              handleUpdateStatus('PENDING');
                            }
                          } else {
                            Alert.alert(
                              'Revertir Gasto',
                              '¿Estás seguro de que deseas regresar este gasto a la bandeja de pendientes para revisarlo nuevamente?',
                              [
                                { text: 'Cancelar', style: 'cancel' },
                                {
                                  text: 'Confirmar Reversión',
                                  style: 'destructive',
                                  onPress: () => handleUpdateStatus('PENDING'),
                                },
                              ]
                            );
                          }
                        }}
                        variant="secondary"
                        style={{ width: '100%', marginTop: Spacing.one }}
                        loading={isProcessingAction}
                        icon={<Ionicons name="arrow-undo-outline" size={20} color={themeColors.text} style={{ marginRight: 8 }} />}
                      />
                      {selectedGasto.status === 'ACTION_REQUIRED' && (
                        <CustomButton
                          title="Editar Gasto"
                          onPress={() => {
                            setReviewModalVisible(false);
                            router.push(`/(admin)/editar-gasto?id=${selectedGasto.id}` as any);
                          }}
                          variant="primary"
                          style={{ width: '100%', marginTop: Spacing.one }}
                          loading={isProcessingAction}
                        />
                      )}
                      <CustomButton
                        title="Eliminar Gasto Permanente"
                        onPress={() => handleDeleteGasto(selectedGasto.id)}
                        variant="danger"
                        style={{ width: '100%', marginTop: Spacing.one }}
                        loading={isProcessingAction}
                        icon={<Ionicons name="trash-outline" size={20} color="#fff" style={{ marginRight: 8 }} />}
                      />
                    </View>
                  )}
                </View>
              </ScrollView>
            )}
          </View>
        </View>
      </Modal>

      {/* MODAL DE EDICIÓN / ASIGNACIÓN RÁPIDA DE PROVEEDOR */}
      <Modal
        animationType="fade"
        transparent={true}
        statusBarTranslucent={true}
        visible={quickEditProvModalVisible}
        onRequestClose={() => {
          if (!isSavingQuickProv) setQuickEditProvModalVisible(false);
        }}
      >
        <KeyboardAvoidingView
          behavior={Platform.OS === 'ios' ? 'padding' : undefined}
          style={{ flex: 1 }}
        >
          <View style={{ flex: 1, backgroundColor: 'rgba(0, 0, 0, 0.65)', justifyContent: 'center', alignItems: 'center', padding: Spacing.three }}>
            <View style={{
              backgroundColor: themeColors.background,
              width: '100%',
              maxWidth: 500,
              height: '82%',
              maxHeight: 650,
              borderRadius: BorderRadius.large,
              padding: Spacing.three,
              borderWidth: 1,
              borderColor: themeColors.border,
              shadowColor: '#000',
              shadowOffset: { width: 0, height: 10 },
              shadowOpacity: 0.3,
              shadowRadius: 20,
              elevation: 10,
              flexDirection: 'column',
            }}>
              {/* Header */}
              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingBottom: Spacing.two, borderBottomWidth: 1, borderBottomColor: themeColors.border }}>
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
                  <View style={{ width: 32, height: 32, borderRadius: 16, backgroundColor: themeColors.accent + '20', justifyContent: 'center', alignItems: 'center' }}>
                    <Ionicons name="business" size={18} color={themeColors.accent} />
                  </View>
                  <View>
                    <Text style={{ fontSize: 16, fontWeight: '800', color: themeColors.text }}>Asignar Proveedor</Text>
                    <Text style={{ fontSize: 11, color: themeColors.textSecondary }}>Gasto: {selectedGasto ? formatCurrency(selectedGasto.monto) : ''}</Text>
                  </View>
                </View>
                <TouchableOpacity
                  onPress={() => setQuickEditProvModalVisible(false)}
                  disabled={isSavingQuickProv}
                  style={{ padding: 4 }}
                >
                  <Ionicons name="close-circle" size={24} color={themeColors.textSecondary} />
                </TouchableOpacity>
              </View>

              {/* Sugerencia del empleado (si existe) */}
              {(() => {
                const parsed = parseJustificacion(selectedGasto?.justificacion);
                if (parsed.proveedorSugerido) {
                  return (
                    <View style={{
                      backgroundColor: themeColors.accent + '15',
                      borderColor: themeColors.accent + '40',
                      borderWidth: 1,
                      borderRadius: BorderRadius.medium,
                      padding: Spacing.two,
                      marginTop: Spacing.two,
                      flexDirection: 'row',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      gap: 8,
                    }}>
                      <View style={{ flex: 1 }}>
                        <Text style={{ fontSize: 11, fontWeight: '700', color: themeColors.accent, textTransform: 'uppercase' }}>
                          💡 Sugerido por empleado:
                        </Text>
                        <Text style={{ fontSize: 13, fontWeight: '800', color: themeColors.text, marginTop: 1 }}>
                          {parsed.proveedorSugerido}
                        </Text>
                      </View>
                      <TouchableOpacity
                        onPress={() => handleQuickCreateProveedorAndAssign(parsed.proveedorSugerido!)}
                        disabled={isSavingQuickProv}
                        style={{
                          backgroundColor: themeColors.accent,
                          paddingVertical: 6,
                          paddingHorizontal: 10,
                          borderRadius: BorderRadius.small,
                        }}
                      >
                        <Text style={{ color: '#fff', fontWeight: '800', fontSize: 12 }}>
                          ⚡ Usar este
                        </Text>
                      </TouchableOpacity>
                    </View>
                  );
                }
                return null;
              })()}

              {/* Buscador */}
              <View style={{ marginTop: Spacing.two, marginBottom: Spacing.two }}>
                <View style={{
                  flexDirection: 'row',
                  alignItems: 'center',
                  backgroundColor: themeColors.backgroundElement,
                  borderWidth: 1,
                  borderColor: themeColors.border,
                  borderRadius: BorderRadius.medium,
                  paddingHorizontal: Spacing.two,
                  height: 44,
                  gap: 8,
                }}>
                  <Ionicons name="search-outline" size={18} color={themeColors.textSecondary} />
                  <TextInput
                    style={{ flex: 1, color: themeColors.text, fontSize: 14 }}
                    placeholder="Buscar o escribir nombre de proveedor..."
                    placeholderTextColor={themeColors.textSecondary + '90'}
                    value={quickEditProvSearch}
                    onChangeText={setQuickEditProvSearch}
                    autoCapitalize="words"
                  />
                  {quickEditProvSearch.length > 0 && (
                    <TouchableOpacity onPress={() => setQuickEditProvSearch('')} style={{ padding: 4 }}>
                      <Ionicons name="close" size={18} color={themeColors.textSecondary} />
                    </TouchableOpacity>
                  )}
                </View>
              </View>

              {/* Botón de Crear Nuevo Proveedor si no existe */}
              {quickEditProvSearch.trim().length > 0 &&
                !proveedoresCatalog.some(p => p.nombre && p.nombre.toLowerCase() === quickEditProvSearch.trim().toLowerCase()) && (
                  <TouchableOpacity
                    onPress={() => {
                      setNewQuickProvName(quickEditProvSearch.trim());
                      setShowNewProvInQuickModal(true);
                    }}
                    style={{
                      flexDirection: 'row',
                      alignItems: 'center',
                      gap: 8,
                      backgroundColor: themeColors.success + '15',
                      borderWidth: 1,
                      borderColor: themeColors.success + '40',
                      borderRadius: BorderRadius.medium,
                      padding: Spacing.two,
                      marginBottom: Spacing.two,
                    }}
                  >
                    <Ionicons name="add-circle" size={22} color={themeColors.success} />
                    <View style={{ flex: 1 }}>
                      <Text style={{ color: themeColors.success, fontWeight: '800', fontSize: 13 }}>
                        + Registrar y asignar &quot;{quickEditProvSearch.trim()}&quot;
                      </Text>
                      <Text style={{ color: themeColors.textSecondary, fontSize: 11 }}>
                        Se agregará al catálogo maestro y se asignará al gasto
                      </Text>
                    </View>
                  </TouchableOpacity>
                )}

              {/* Mini formulario para agregar nuevo proveedor con RFC */}
              {showNewProvInQuickModal && (
                <View style={{
                  backgroundColor: themeColors.backgroundElement,
                  borderRadius: BorderRadius.medium,
                  padding: Spacing.two,
                  borderWidth: 1,
                  borderColor: themeColors.primary,
                  marginBottom: Spacing.two,
                  gap: Spacing.one,
                }}>
                  <Text style={{ fontSize: 12, fontWeight: '700', color: themeColors.primary }}>
                    Nuevo Proveedor
                  </Text>
                  <CustomInput
                    placeholder="Nombre comercial / Razón Social *"
                    value={newQuickProvName}
                    onChangeText={setNewQuickProvName}
                    style={{ height: 40 }}
                  />
                  <CustomInput
                    placeholder="RFC (Opcional)"
                    value={newQuickProvRfc}
                    onChangeText={t => setNewQuickProvRfc(t.toUpperCase())}
                    autoCapitalize="characters"
                    style={{ height: 40 }}
                  />
                  <View style={{ flexDirection: 'row', gap: 8, marginTop: 4 }}>
                    <CustomButton
                      title="Cancelar"
                      variant="secondary"
                      onPress={() => setShowNewProvInQuickModal(false)}
                      style={{ flex: 1, height: 36 }}
                    />
                    <CustomButton
                      title="Guardar y Asignar"
                      variant="primary"
                      loading={isSavingQuickProv}
                      onPress={() => handleQuickCreateProveedorAndAssign(newQuickProvName, newQuickProvRfc)}
                      style={{ flex: 1.5, height: 36 }}
                    />
                  </View>
                </View>
              )}

              {/* Lista de Proveedores */}
              <Text style={{ fontSize: 11, fontWeight: '700', color: themeColors.textSecondary, textTransform: 'uppercase', marginBottom: 6, letterSpacing: 0.5 }}>
                Proveedores Registrados ({proveedoresCatalog.filter(p => !quickEditProvSearch || (p.nombre && p.nombre.toLowerCase().includes(quickEditProvSearch.toLowerCase()))).length})
              </Text>

              <View style={{ flex: 1, minHeight: 100 }}>
                <FlatList
                  data={proveedoresCatalog.filter(p => {
                    if (!quickEditProvSearch.trim()) return true;
                    const query = quickEditProvSearch.toLowerCase();
                    const nameMatch = p.nombre && p.nombre.toLowerCase().includes(query);
                    const rfcMatch = p.rfc && p.rfc.toLowerCase().includes(query);
                    return nameMatch || rfcMatch;
                  })}
                  keyExtractor={(item) => item.id}
                  keyboardShouldPersistTaps="handled"
                  style={{ flex: 1 }}
                  contentContainerStyle={{ gap: 6, paddingBottom: Spacing.two }}
                  renderItem={({ item }) => {
                    const isCurrent = (selectedGasto?.proveedor_id === item.id) ||
                      (GastoHelper.getProveedor(selectedGasto)?.toLowerCase() === item.nombre?.toLowerCase());

                    return (
                      <TouchableOpacity
                        onPress={() => handleSelectQuickProveedor(item)}
                        disabled={isSavingQuickProv}
                        style={{
                          flexDirection: 'row',
                          justifyContent: 'space-between',
                          alignItems: 'center',
                          paddingVertical: 10,
                          paddingHorizontal: 12,
                          borderRadius: BorderRadius.medium,
                          backgroundColor: isCurrent ? themeColors.accent + '20' : themeColors.backgroundElement,
                          borderWidth: 1,
                          borderColor: isCurrent ? themeColors.accent : themeColors.border,
                        }}
                      >
                        <View style={{ flex: 1, marginRight: 8 }}>
                          <Text style={{
                            fontSize: 14,
                            fontWeight: isCurrent ? '800' : '600',
                            color: isCurrent ? themeColors.accent : themeColors.text,
                          }}>
                            {item.nombre}
                          </Text>
                          {item.rfc ? (
                            <Text style={{ fontSize: 11, color: themeColors.textSecondary, marginTop: 1 }}>
                              RFC: {item.rfc}
                            </Text>
                          ) : null}
                        </View>
                        {isCurrent ? (
                          <Ionicons name="checkmark-circle" size={20} color={themeColors.accent} />
                        ) : (
                          <Ionicons name="chevron-forward" size={16} color={themeColors.textSecondary} />
                        )}
                      </TouchableOpacity>
                    );
                  }}
                  ListEmptyComponent={
                    <View style={{ padding: Spacing.three, alignItems: 'center', justifyContent: 'center' }}>
                      <Ionicons name="alert-circle-outline" size={32} color={themeColors.textSecondary} />
                      <Text style={{ color: themeColors.textSecondary, fontSize: 13, marginTop: 6, textAlign: 'center' }}>
                        No se encontraron proveedores que coincidan con la búsqueda.
                      </Text>
                    </View>
                  }
                />
              </View>

              {/* Footer con opción de dejar sin proveedor */}
              <View style={{ paddingTop: Spacing.two, borderTopWidth: 1, borderTopColor: themeColors.border, flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
                {GastoHelper.getProveedor(selectedGasto) ? (
                  <TouchableOpacity
                    onPress={() => {
                      if (Platform.OS === 'web') {
                        if (window.confirm('¿Deseas desasignar el proveedor de este gasto?')) {
                          handleSelectQuickProveedor(null);
                        }
                      } else {
                        Alert.alert('Desasignar Proveedor', '¿Deseas quitar el proveedor de este gasto?', [
                          { text: 'Cancelar', style: 'cancel' },
                          { text: 'Quitar', style: 'destructive', onPress: () => handleSelectQuickProveedor(null) },
                        ]);
                      }
                    }}
                    disabled={isSavingQuickProv}
                    style={{ flexDirection: 'row', alignItems: 'center', gap: 4, paddingVertical: 8, paddingHorizontal: 10 }}
                  >
                    <Ionicons name="trash-outline" size={15} color={themeColors.danger} />
                    <Text style={{ color: themeColors.danger, fontSize: 12, fontWeight: '700' }}>
                      Quitar Proveedor
                    </Text>
                  </TouchableOpacity>
                ) : (
                  <View />
                )}

                <TouchableOpacity
                  onPress={() => setQuickEditProvModalVisible(false)}
                  disabled={isSavingQuickProv}
                  style={{
                    backgroundColor: themeColors.backgroundElement,
                    borderWidth: 1,
                    borderColor: themeColors.border,
                    paddingVertical: 8,
                    paddingHorizontal: 16,
                    borderRadius: BorderRadius.medium,
                  }}
                >
                  <Text style={{ color: themeColors.text, fontWeight: '700', fontSize: 13 }}>Cerrar</Text>
                </TouchableOpacity>
              </View>
            </View>
          </View>
        </KeyboardAvoidingView>
      </Modal>

      {/* MODAL DE FILTRO DE FECHAS Y CALENDARIO */}
      <Modal statusBarTranslucent={true}
        animationType="fade"
        transparent={true}
        visible={dateFilterModalVisible}
        onRequestClose={() => setDateFilterModalVisible(false)}
      >
        <View style={{ flex: 1, backgroundColor: 'rgba(0, 0, 0, 0.6)', justifyContent: 'center', alignItems: 'center', padding: Spacing.three }}>
          <View style={{ backgroundColor: themeColors.background, width: '100%', maxWidth: 440, borderRadius: BorderRadius.large, padding: Spacing.three, borderWidth: 1, borderColor: themeColors.border, shadowColor: '#000', shadowOffset: { width: 0, height: 10 }, shadowOpacity: 0.25, shadowRadius: 15, elevation: 10 }}>
            {/* Encabezado */}
            <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: Spacing.two, borderBottomWidth: 1, borderBottomColor: themeColors.border, paddingBottom: Spacing.two }}>
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
                <Ionicons name="calendar" size={22} color={themeColors.accent} />
                <Text style={{ fontSize: 16, fontWeight: '700', color: themeColors.text }}>Filtrar por Fecha</Text>
              </View>
              <TouchableOpacity onPress={() => setDateFilterModalVisible(false)} style={{ padding: 4 }}>
                <Ionicons name="close-circle" size={24} color={themeColors.textSecondary} />
              </TouchableOpacity>
            </View>

            <ScrollView contentContainerStyle={{ gap: Spacing.two }}>
              {/* Presets Rápidos */}
              <Text style={{ fontSize: 12, fontWeight: '700', color: themeColors.textSecondary, textTransform: 'uppercase', letterSpacing: 0.5 }}>Filtros Rápidos</Text>
              <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 8 }}>
                <TouchableOpacity
                  onPress={() => {
                    setStartDateFilter(null);
                    setEndDateFilter(null);
                    setTempStartDate('');
                    setTempEndDate('');
                    setDateFilterModalVisible(false);
                  }}
                  style={{ paddingHorizontal: 12, paddingVertical: 6, borderRadius: 16, backgroundColor: (!startDateFilter && !endDateFilter) ? themeColors.accent : themeColors.backgroundElement, borderWidth: 1, borderColor: themeColors.border }}
                >
                  <Text style={{ fontSize: 12, fontWeight: '600', color: (!startDateFilter && !endDateFilter) ? '#fff' : themeColors.text }}>Todas las Fechas</Text>
                </TouchableOpacity>

                <TouchableOpacity
                  onPress={() => {
                    const todayStr = new Date().toISOString().split('T')[0];
                    setStartDateFilter(todayStr);
                    setEndDateFilter(todayStr);
                    setTempStartDate(todayStr);
                    setTempEndDate(todayStr);
                    setDateFilterModalVisible(false);
                  }}
                  style={{ paddingHorizontal: 12, paddingVertical: 6, borderRadius: 16, backgroundColor: (startDateFilter === new Date().toISOString().split('T')[0] && endDateFilter === new Date().toISOString().split('T')[0]) ? themeColors.accent : themeColors.backgroundElement, borderWidth: 1, borderColor: themeColors.border }}
                >
                  <Text style={{ fontSize: 12, fontWeight: '600', color: (startDateFilter === new Date().toISOString().split('T')[0] && endDateFilter === new Date().toISOString().split('T')[0]) ? '#fff' : themeColors.text }}>Hoy</Text>
                </TouchableOpacity>

                <TouchableOpacity
                  onPress={() => {
                    const now = new Date();
                    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
                    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
                    setStartDateFilter(firstDay);
                    setEndDateFilter(lastDay);
                    setTempStartDate(firstDay);
                    setTempEndDate(lastDay);
                    setDateFilterModalVisible(false);
                  }}
                  style={{ paddingHorizontal: 12, paddingVertical: 6, borderRadius: 16, backgroundColor: themeColors.backgroundElement, borderWidth: 1, borderColor: themeColors.border }}
                >
                  <Text style={{ fontSize: 12, fontWeight: '600', color: themeColors.text }}>Este Mes</Text>
                </TouchableOpacity>
              </View>

              {/* Calendario / Selector Interactivo */}
              <View style={{ borderTopWidth: 1, borderTopColor: themeColors.border, paddingTop: Spacing.two, marginTop: Spacing.one }}>
                <Text style={{ fontSize: 13, fontWeight: '700', color: themeColors.text, marginBottom: 10 }}>📅 Seleccionar Fecha / Rango:</Text>

                {Platform.OS === 'web' ? (
                  <View style={{ gap: Spacing.two }}>
                    <View style={{ gap: 4 }}>
                      <Text style={{ fontSize: 12, fontWeight: '600', color: themeColors.textSecondary }}>Fecha Inicio (ó Día Único):</Text>
                      {/* @ts-ignore */}
                      <input
                        type="date"
                        value={tempStartDate}
                        onChange={(e: any) => setTempStartDate(e.target.value)}
                        style={{
                          width: '100%',
                          height: '42px',
                          padding: '8px 12px',
                          borderRadius: '8px',
                          border: `1px solid ${themeColors.border}`,
                          backgroundColor: themeColors.backgroundElement,
                          color: themeColors.text,
                          fontSize: '14px',
                          outline: 'none',
                          boxSizing: 'border-box',
                          cursor: 'pointer'
                        }}
                      />
                    </View>

                    <View style={{ gap: 4 }}>
                      <Text style={{ fontSize: 12, fontWeight: '600', color: themeColors.textSecondary }}>Fecha Fin (Opcional para Rango):</Text>
                      {/* @ts-ignore */}
                      <input
                        type="date"
                        value={tempEndDate}
                        onChange={(e: any) => setTempEndDate(e.target.value)}
                        style={{
                          width: '100%',
                          height: '42px',
                          padding: '8px 12px',
                          borderRadius: '8px',
                          border: `1px solid ${themeColors.border}`,
                          backgroundColor: themeColors.backgroundElement,
                          color: themeColors.text,
                          fontSize: '14px',
                          outline: 'none',
                          boxSizing: 'border-box',
                          cursor: 'pointer'
                        }}
                      />
                    </View>
                  </View>
                ) : (
                  <View style={{ gap: Spacing.two }}>
                    <CustomInput
                      label="Fecha Inicio (AAAA-MM-DD) *"
                      placeholder="Ej. 2026-07-20"
                      value={tempStartDate}
                      onChangeText={setTempStartDate}
                      iconName="calendar-outline"
                    />
                    <CustomInput
                      label="Fecha Fin (AAAA-MM-DD)"
                      placeholder="Ej. 2026-07-25"
                      value={tempEndDate}
                      onChangeText={setTempEndDate}
                      iconName="calendar-outline"
                    />
                  </View>
                )}
              </View>

              {/* Botones de Acción */}
              <View style={{ flexDirection: 'row', gap: Spacing.two, marginTop: Spacing.two }}>
                <View style={{ flex: 1 }}>
                  <CustomButton
                    title="Limpiar"
                    onPress={() => {
                      setTempStartDate('');
                      setTempEndDate('');
                      setStartDateFilter(null);
                      setEndDateFilter(null);
                      setDateFilterModalVisible(false);
                    }}
                    variant="secondary"
                  />
                </View>
                <View style={{ flex: 1 }}>
                  <CustomButton
                    title="Aplicar Fechas"
                    onPress={() => {
                      const s = tempStartDate.trim() || null;
                      const e = tempEndDate.trim() || s;
                      setStartDateFilter(s);
                      setEndDateFilter(e);
                      setDateFilterModalVisible(false);
                    }}
                    variant="primary"
                  />
                </View>
              </View>
            </ScrollView>
          </View>
        </View>
      </Modal>

      {/* Modal de Vinculación a Ventas al Aprobar */}
      <Modal statusBarTranslucent={true}
        visible={isLinkSaleModalVisible}
        animationType="slide"
        transparent={true}
        onRequestClose={() => setIsLinkSaleModalVisible(false)}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, { backgroundColor: themeColors.background, height: '80%', paddingBottom: Spacing.four }]}>
            {/* Header del Modal */}
            <View style={[styles.modalHeader, { borderBottomColor: themeColors.border, borderBottomWidth: 1, paddingBottom: Spacing.two }]}>
               <View style={{ flexDirection: 'row', alignItems: 'center', gap: Spacing.one }}>
                 {isQuickSaleFormVisible && (
                   <TouchableOpacity onPress={() => setIsQuickSaleFormVisible(false)} style={{ marginRight: 4 }}>
                     <Ionicons name="arrow-back" size={24} color={themeColors.text} />
                   </TouchableOpacity>
                 )}
                 <Text style={[styles.modalTitle, { color: themeColors.text }]}>
                   {isQuickSaleFormVisible ? 'Crear Venta Rápida' : '¿Vincular Gasto a Venta?'}
                 </Text>
               </View>
               <View style={{ flexDirection: 'row', alignItems: 'center', gap: Spacing.two }}>
                 {!isQuickSaleFormVisible && (
                   <TouchableOpacity onPress={handleOpenQuickSaleForm} style={{ padding: 4 }}>
                     <Ionicons name="add-circle" size={28} color={themeColors.success} />
                   </TouchableOpacity>
                 )}
                 <TouchableOpacity onPress={() => setIsLinkSaleModalVisible(false)} style={{ padding: 4 }}>
                   <Ionicons name="close" size={24} color={themeColors.text} />
                 </TouchableOpacity>
               </View>
            </View>

            {!isQuickSaleFormVisible ? (
              <>
                {/* Buscador de Ventas */}
                <View style={{ paddingTop: Spacing.two, marginBottom: Spacing.two }}>
                  <CustomInput
                    placeholder="Buscar por cliente, factura o tipo..."
                    value={linkSaleSearch}
                    onChangeText={setLinkSaleSearch}
                    iconName="search-outline"
                  />
                </View>

                {/* Lista de Ventas */}
                <View style={{ flex: 1, marginBottom: Spacing.two }}>
                  {isLoadingSalesForLinking ? (
                    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
                      <ActivityIndicator size="large" color={themeColors.accent} />
                      <Text style={{ color: themeColors.textSecondary, marginTop: Spacing.one }}>Cargando ventas...</Text>
                    </View>
                  ) : filteredSalesForLinking.length === 0 ? (
                    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', gap: Spacing.one }}>
                      <Ionicons name="alert-circle-outline" size={40} color={themeColors.textSecondary} />
                      <Text style={{ color: themeColors.textSecondary, textAlign: 'center', fontSize: 13 }}>
                        No se encontraron ventas para asociar.
                      </Text>
                    </View>
                  ) : (
                    <FlatList scrollEnabled={false}
                      data={filteredSalesForLinking}
                      initialNumToRender={5}
                      maxToRenderPerBatch={5}
                      windowSize={5}
                      removeClippedSubviews={true}
                      keyExtractor={(item) => item.id}
                      showsVerticalScrollIndicator={false}
                      contentContainerStyle={{ gap: Spacing.two }}
                      renderItem={({ item }) => (
                        <TouchableOpacity
                          onPress={() => {
                            setIsLinkSaleModalVisible(false);
                            executeApproveGasto(item.id);
                          }}
                          style={[
                            styles.linkSaleItem,
                            {
                              backgroundColor: themeColors.backgroundElement,
                              borderColor: themeColors.border,
                            },
                          ]}
                        >
                          <View style={{ flex: 1 }}>
                            <Text style={{ color: themeColors.text, fontWeight: '700', fontSize: 14 }}>
                              {item.cliente}
                            </Text>
                            {item.sucursal ? (
                              <Text style={{ color: themeColors.primary, fontSize: 12, marginTop: 2, fontWeight: '600' }}>
                                Sucursal: {item.sucursal}
                              </Text>
                            ) : null}
                            <Text style={{ color: themeColors.textSecondary, fontSize: 12, marginTop: 2 }}>
                              {item.fecha} {item.tipo_proyecto ? `| ${item.tipo_proyecto}` : ''}
                            </Text>
                            {item.factura_referencia ? (
                              <Text style={{ color: themeColors.textSecondary, fontSize: 11, marginTop: 1 }}>
                                Factura: {item.factura_referencia}
                              </Text>
                            ) : null}
                          </View>
                          <Text style={{ color: themeColors.accent, fontWeight: '800', fontSize: 14, alignSelf: 'center' }}>
                            {formatCurrency(item.precio_total_facturado)}
                          </Text>
                        </TouchableOpacity>
                      )}
                    />
                  )}
                </View>

                {/* Footer con opciones */}
                <View style={{ gap: Spacing.two, paddingTop: Spacing.two, borderTopWidth: 1, borderTopColor: themeColors.border }}>
                  <CustomButton
                    title="Aprobar sin vincular"
                    onPress={() => {
                      setIsLinkSaleModalVisible(false);
                      executeApproveGasto(null);
                    }}
                    variant="primary"
                    style={{ width: '100%' }}
                  />
                  <CustomButton
                    title="Cancelar"
                    onPress={() => setIsLinkSaleModalVisible(false)}
                    variant="secondary"
                    style={{ width: '100%' }}
                  />
                </View>
              </>
            ) : (
              // Formulario de Venta Rápida
              <View style={{ flex: 1 }}>
                <ScrollView contentContainerStyle={{ paddingBottom: Spacing.four }} keyboardShouldPersistTaps="handled" showsVerticalScrollIndicator={false}>
                  {/* Fecha */}
                  <CustomInput
                    label="Fecha (AAAA-MM-DD) *"
                    placeholder="2026-07-06"
                    value={quickSaleFecha}
                    onChangeText={setQuickSaleFecha}
                    iconName="calendar-outline"
                  />

                  {/* Input Cliente con Autocompletado */}
                  {/* Selector de Cliente y Sucursal (Estilo Formulario) */}
                  {(() => {
                    const currentClient = clientesCatalog.find(c => c.nombre === quickSaleCliente);
                    const sucs = currentClient ? sucursalesCatalog.filter(s => s.cliente_id === currentClient.id) : [];

                    return (
                      <View style={{ width: '100%' }}>
                        <View style={{ zIndex: 3000, marginBottom: Spacing.two }}>
                          <Text style={[styles.detailLabel, { color: themeColors.textSecondary, marginBottom: 4 }]}>
                            Cliente <Text style={{ color: themeColors.danger }}>*</Text>
                          </Text>
                          <TouchableOpacity
                            style={[styles.customDropdownTrigger, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border }]}
                            onPress={() => {
                              Keyboard.dismiss();
                              setShowQuickSaleCliDropdown(!showQuickSaleCliDropdown);
                            }}
                          >
                            <Text style={{ color: quickSaleCliente ? themeColors.text : themeColors.textSecondary }}>
                              {quickSaleCliente || 'Selecciona un cliente'}
                            </Text>
                            <Ionicons name={showQuickSaleCliDropdown ? 'chevron-up' : 'chevron-down'} size={18} color={themeColors.textSecondary} />
                          </TouchableOpacity>
                          
                          {showQuickSaleCliDropdown && (
                            <Pressable onPress={(e) => e.stopPropagation()} style={{ width: '100%', zIndex: 1000 }}>
                              <View style={[styles.customDropdownList, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border }]}>
                                <CustomInput
                                  placeholder="Buscar cliente..."
                                  value={quickSaleCliSearch}
                                  onChangeText={setQuickSaleCliSearch}
                                  iconName="search-outline"
                                  style={{ margin: Spacing.one, height: 40 }}
                                />
                                <ScrollView nestedScrollEnabled={true} style={{ maxHeight: 200, paddingHorizontal: Spacing.half }} keyboardShouldPersistTaps="handled">
                                  {filteredClientsForQuickSale.map((c, index, array) => (
                                    <TouchableOpacity
                                      key={c.id}
                                      onPress={() => {
                                        setQuickSaleCliente(c.nombre);
                                        setQuickSaleSucursal('');
                                        setShowQuickSaleCliDropdown(false);
                                      }}
                                      style={[
                                        styles.customDropdownItem,
                                        index === array.length - 1 && { borderBottomWidth: 0 },
                                        { flexDirection: 'row', alignItems: 'center', gap: Spacing.one, borderBottomColor: themeColors.border }
                                      ]}
                                    >
                                      <Ionicons name="person-circle-outline" size={24} color={themeColors.primary} />
                                      <Text style={{ color: themeColors.text, fontWeight: '500', fontSize: 14 }}>{c.nombre}</Text>
                                    </TouchableOpacity>
                                  ))}
                                  {filteredClientsForQuickSale.length === 0 && (
                                    <Text style={{ padding: Spacing.two, color: themeColors.textSecondary }}>No hay clientes que coincidan.</Text>
                                  )}
                                </ScrollView>
                              </View>
                            </Pressable>
                          )}
                        </View>

                        <View style={{ zIndex: 2000, marginBottom: Spacing.two }}>
                          <Text style={[styles.detailLabel, { color: themeColors.textSecondary, marginBottom: 4 }]}>
                            Sucursal del cliente <Text style={{ color: themeColors.danger }}>*</Text>
                          </Text>
                          <TouchableOpacity
                            style={[styles.customDropdownTrigger, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border, opacity: !quickSaleCliente ? 0.5 : 1 }]}
                            disabled={!quickSaleCliente}
                            onPress={() => {
                              Keyboard.dismiss();
                              setShowQuickSaleSucursalDropdown(!showQuickSaleSucursalDropdown);
                            }}
                          >
                            <Text style={{ color: quickSaleSucursal ? themeColors.text : themeColors.textSecondary }}>
                              {quickSaleSucursal || (quickSaleCliente ? 'Selecciona una sucursal' : 'Selecciona un cliente primero')}
                            </Text>
                            <Ionicons name={showQuickSaleSucursalDropdown ? 'chevron-up' : 'chevron-down'} size={18} color={themeColors.textSecondary} />
                          </TouchableOpacity>
                          
                          {showQuickSaleSucursalDropdown && (
                            <View style={{ width: '100%', zIndex: 1000 }}>
                              <View style={[styles.customDropdownList, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border }]}>
                                <CustomInput
                                  placeholder="Buscar sucursal..."
                                  value={quickSaleSucursalSearch}
                                  onChangeText={setQuickSaleSucursalSearch}
                                  iconName="search-outline"
                                  style={{ margin: Spacing.one, height: 40 }}
                                />
                                <ScrollView nestedScrollEnabled={true} style={{ maxHeight: 200, paddingHorizontal: Spacing.half }} keyboardShouldPersistTaps="handled">
                                  {(() => {
                                    const filteredSucs = sucs.filter(s => s.nombre.toLowerCase().includes(quickSaleSucursalSearch.toLowerCase()));
                                    if (filteredSucs.length === 0) {
                                      return <Text style={{ padding: Spacing.two, color: themeColors.textSecondary }}>No hay sucursales registradas.</Text>;
                                    }
                                    return filteredSucs.map((s, index, array) => (
                                      <TouchableOpacity
                                        key={s.id}
                                        onPress={() => {
                                          setQuickSaleSucursal(s.nombre);
                                          setShowQuickSaleSucursalDropdown(false);
                                        }}
                                        style={[
                                          styles.customDropdownItem,
                                          index === array.length - 1 && { borderBottomWidth: 0 },
                                          { flexDirection: 'row', alignItems: 'center', gap: Spacing.one, borderBottomColor: themeColors.border }
                                        ]}
                                      >
                                        <Ionicons name="business-outline" size={24} color={themeColors.primary} />
                                        <Text style={{ color: themeColors.text, fontWeight: '500', fontSize: 14 }}>{s.nombre}</Text>
                                      </TouchableOpacity>
                                    ))
                                  })()}
                                </ScrollView>
                              </View>
                            </View>
                          )}
                        </View>
                      </View>
                    );
                  })()}

                  {/* Factura Referencia */}
                  <CustomInput
                    label="Factura / Referencia (Opcional)"
                    placeholder="F-12345"
                    value={quickSaleFactura}
                    onChangeText={setQuickSaleFactura}
                    iconName="document-text-outline"
                  />

                  {/* Tipo de Proyecto Selector */}
                  <View style={{ zIndex: 8, position: 'relative', marginBottom: Spacing.two }}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary, marginBottom: 4 }]}>Tipo de Proyecto</Text>
                    <TouchableOpacity
                      onPress={() => setShowQuickSaleTipoDropdown(!showQuickSaleTipoDropdown)}
                      style={[styles.customDropdownTrigger, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border }]}
                    >
                      <Text style={{ color: quickSaleTipoProyecto ? themeColors.text : themeColors.textSecondary }}>
                        {quickSaleTipoProyecto || 'Selecciona un tipo...'}
                      </Text>
                      <Ionicons name="chevron-down" size={18} color={themeColors.textSecondary} />
                    </TouchableOpacity>
                    {showQuickSaleTipoDropdown && (
                      <View style={[styles.customDropdownList, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border }]}>
                        {TIPOS_PROYECTO.map((tipo) => (
                          <TouchableOpacity
                            key={tipo}
                            onPress={() => {
                              setQuickSaleTipoProyecto(tipo);
                              setShowQuickSaleTipoDropdown(false);
                            }}
                            style={[styles.customDropdownItem, { borderBottomColor: themeColors.border }]}
                          >
                            <Text style={{ color: themeColors.text }}>{tipo}</Text>
                          </TouchableOpacity>
                        ))}
                      </View>
                    )}
                  </View>

                  {/* Proveedor */}
                  <CustomInput
                    label="Proveedor (Opcional)"
                    placeholder="Ej. Centro, Norte o sucursal relacionada..."
                    value={quickSaleProveedor}
                    onChangeText={setQuickSaleProveedor}
                    iconName="location-outline"
                    style={{ marginTop: Spacing.two }}
                  />

                  {/* Notas */}
                  <CustomInput
                    label="Notas / Observaciones"
                    placeholder="Detalles de la venta..."
                    value={quickSaleNotas}
                    onChangeText={setQuickSaleNotas}
                    multiline
                    numberOfLines={2}
                    iconName="create-outline"
                  />

                  {/* Partidas de Venta */}
                  <View style={{ marginTop: Spacing.three }}>
                    <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: Spacing.one }}>
                      <Text style={{ color: themeColors.text, fontWeight: '700', fontSize: 16 }}>Partidas desglosadas</Text>
                      <TouchableOpacity onPress={addQuickSalePartida} style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
                        <Ionicons name="add-circle-outline" size={18} color={themeColors.accent} />
                        <Text style={{ color: themeColors.accent, fontWeight: '600', fontSize: 13 }}>Agregar Partida</Text>
                      </TouchableOpacity>
                    </View>

                    {quickSalePartidas.map((partida, index) => (
                      <View
                        key={partida.id}
                        style={[
                          styles.partidaCard,
                          {
                            backgroundColor: themeColors.backgroundElement + '50',
                            borderColor: themeColors.border,
                            padding: Spacing.two,
                            borderRadius: BorderRadius.medium,
                            borderWidth: 1,
                            marginBottom: Spacing.two,
                          },
                        ]}
                      >
                        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: Spacing.one }}>
                          <Text style={{ color: themeColors.textSecondary, fontWeight: '600', fontSize: 12 }}>Partida #{index + 1}</Text>
                          {quickSalePartidas.length > 1 && (
                            <TouchableOpacity onPress={() => removeQuickSalePartida(partida.id)}>
                              <Ionicons name="trash-outline" size={16} color={themeColors.danger} />
                            </TouchableOpacity>
                          )}
                        </View>

                        <CustomInput
                          placeholder="Descripción del producto o servicio..."
                          value={partida.descripcion}
                          onChangeText={(val) => updateQuickSalePartida(partida.id, 'descripcion', val)}
                        />

                        <View style={{ flexDirection: 'row', gap: Spacing.two, marginTop: Spacing.one }}>
                          <View style={{ flex: 1 }}>
                            <CustomInput
                              label="Cant."
                              placeholder="1"
                              keyboardType="numeric"
                              value={partida.cantidad}
                              onChangeText={(val) => updateQuickSalePartida(partida.id, 'cantidad', val)}
                            />
                          </View>
                          <View style={{ flex: 1 }}>
                            <CustomInput
                              label="Unidad"
                              placeholder="PZA"
                              value={partida.unidad}
                              onChangeText={(val) => updateQuickSalePartida(partida.id, 'unidad', val)}
                            />
                          </View>
                          <View style={{ flex: 1.5 }}>
                            <CustomInput
                              label="Costo Prov ($)"
                              placeholder="0.00"
                              keyboardType="numeric"
                              value={partida.costo_unitario_proveedor}
                              onChangeText={(val) => updateQuickSalePartida(partida.id, 'costo_unitario_proveedor', val)}
                            />
                          </View>
                          <View style={{ flex: 1.5 }}>
                            <CustomInput
                              label="Precio Venta ($)"
                              placeholder="0.00"
                              keyboardType="numeric"
                              value={partida.precio_unitario_venta}
                              onChangeText={(val) => updateQuickSalePartida(partida.id, 'precio_unitario_venta', val)}
                            />
                          </View>
                        </View>
                      </View>
                    ))}
                  </View>

                  {/* Resumen Financiero Rápido */}
                  <View
                    style={[
                      styles.financialSummary,
                      {
                        backgroundColor: themeColors.backgroundSelected,
                        borderRadius: BorderRadius.medium,
                        padding: Spacing.two,
                        marginTop: Spacing.two,
                      },
                    ]}
                  >
                    <Text style={{ color: themeColors.text, fontWeight: '700', fontSize: 14, marginBottom: Spacing.one }}>
                      Resumen Financiero de la Venta
                    </Text>
                    <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 4 }}>
                      <Text style={{ color: themeColors.textSecondary, fontSize: 13 }}>Costo Proveedor Total:</Text>
                      <Text style={{ color: themeColors.text, fontWeight: '600', fontSize: 13 }}>{formatCurrency(quickSaleTotals.costoTotal)}</Text>
                    </View>
                    <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 4 }}>
                      <Text style={{ color: themeColors.textSecondary, fontSize: 13 }}>Precio de Venta Total:</Text>
                      <Text style={{ color: themeColors.accent, fontWeight: '700', fontSize: 13 }}>{formatCurrency(quickSaleTotals.precioTotal)}</Text>
                    </View>
                    <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 4 }}>
                      <Text style={{ color: themeColors.textSecondary, fontSize: 13 }}>Utilidad Bruta:</Text>
                      <Text style={{ color: quickSaleTotals.utilidad >= 0 ? themeColors.success : themeColors.danger, fontWeight: '700', fontSize: 13 }}>
                        {formatCurrency(quickSaleTotals.utilidad)}
                      </Text>
                    </View>
                    <View style={{ flexDirection: 'row', justifyContent: 'space-between' }}>
                      <Text style={{ color: themeColors.textSecondary, fontSize: 13 }}>Margen de Utilidad:</Text>
                      <Text style={{ color: quickSaleTotals.utilidad >= 0 ? themeColors.success : themeColors.danger, fontWeight: '700', fontSize: 13 }}>
                        {Math.round(quickSaleTotals.margen * 10000) / 100}%
                      </Text>
                    </View>
                  </View>
                </ScrollView>

                {/* Footer de Venta Rápida */}
                <View style={{ gap: Spacing.one, paddingTop: Spacing.two, borderTopWidth: 1, borderTopColor: themeColors.border }}>
                  <CustomButton
                    title="Crear y Vincular Venta"
                    onPress={handleSaveQuickSale}
                    variant="success"
                    loading={isSavingQuickSale}
                    style={{ width: '100%' }}
                  />
                  <CustomButton
                    title="Volver al buscador"
                    onPress={() => setIsQuickSaleFormVisible(false)}
                    variant="secondary"
                    style={{ width: '100%' }}
                    disabled={isSavingQuickSale}
                  />
                </View>
              </View>
            )}
          </View>
        </View>
      </Modal>

      {/* Modal 1.1: Registro de Nuevo Usuario */}
      <Modal statusBarTranslucent={true}
        animationType="slide"
        transparent={true}
        visible={addUserModalVisible}
        onRequestClose={() => setAddUserModalVisible(false)}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, { backgroundColor: themeColors.background, height: '75%' }]}>
            <View style={styles.modalHeader}>
              <Text style={[styles.modalTitle, { color: themeColors.text }]}>Registrar Personal</Text>
              <TouchableOpacity onPress={() => setAddUserModalVisible(false)}>
                <Ionicons name="close" size={24} color={themeColors.text} />
              </TouchableOpacity>
            </View>

            <ScrollView contentContainerStyle={{ paddingBottom: Spacing.four }} keyboardShouldPersistTaps="handled">
              <CustomInput
                label="Nombre Completo *"
                placeholder="Nombre y Apellidos"
                value={newUserName}
                onChangeText={setNewUserName}
                iconName="person-outline"
              />

              <CustomInput
                label="Correo Electrónico *"
                placeholder={`correo@${company === 'daravisa' ? 'daravisa' : 'inttec'}.com`}
                keyboardType="email-address"
                autoCapitalize="none"
                value={newUserEmail}
                onChangeText={setNewUserEmail}
                iconName="mail-outline"
              />

              <CustomInput
                label="Contraseña *"
                placeholder="Ingresar contraseña inicial"
                secureTextEntry
                isPassword
                value={newUserPassword}
                onChangeText={setNewUserPassword}
                iconName="lock-closed-outline"
              />

              <CustomInput
                label="Teléfono"
                placeholder="10 dígitos"
                keyboardType="phone-pad"
                value={newUserPhone}
                onChangeText={setNewUserPhone}
                iconName="call-outline"
              />

              <View style={styles.selectorGroup}>
                <Text style={[styles.selectorLabel, { color: themeColors.text }]}>Rol Organizacional *</Text>
                <View style={styles.paymentSelector}>
                  {(['EMPLEADO', 'ADMIN', 'DEV'] as const).map((role) => {
                    const isActive = newUserRole === role;
                    return (
                      <TouchableOpacity
                        key={role}
                        onPress={() => setNewUserRole(role)}
                        style={[
                          styles.paymentOption,
                          {
                            backgroundColor: isActive ? themeColors.accent : themeColors.backgroundElement,
                            borderColor: isActive ? 'transparent' : themeColors.border,
                            flex: 1,
                            alignItems: 'center',
                          },
                        ]}
                      >
                        <Text style={[styles.paymentOptionText, { color: isActive ? '#ffffff' : themeColors.text }]}>
                          {role}
                        </Text>
                      </TouchableOpacity>
                    );
                  })}
                </View>
              </View>

              <CustomButton
                title="Registrar"
                onPress={handleAddUser}
                loading={isAddingUser}
                style={{ marginTop: Spacing.three }}
              />
            </ScrollView>
          </View>
        </View>
      </Modal>

      {/* Modal 1.2: Edición de Usuario Existente */}
      <Modal statusBarTranslucent={true}
        animationType="slide"
        transparent={true}
        visible={editUserModalVisible}
        onRequestClose={() => {
          setEditUserModalVisible(false);
          setEditingUser(null);
        }}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, { backgroundColor: themeColors.background, height: '75%' }]}>
            <View style={styles.modalHeader}>
              <Text style={[styles.modalTitle, { color: themeColors.text }]}>Editar Personal</Text>
              <TouchableOpacity
                onPress={() => {
                  setEditUserModalVisible(false);
                  setEditingUser(null);
                }}
              >
                <Ionicons name="close" size={24} color={themeColors.text} />
              </TouchableOpacity>
            </View>

            <ScrollView contentContainerStyle={{ paddingBottom: Spacing.four }} keyboardShouldPersistTaps="handled">
              <CustomInput
                label="Nombre Completo *"
                placeholder="Nombre y Apellidos"
                value={editUserName}
                onChangeText={setEditUserName}
                iconName="person-outline"
              />

              <CustomInput
                label="Correo Electrónico *"
                placeholder={`correo@${company === 'daravisa' ? 'daravisa' : 'inttec'}.com`}
                keyboardType="email-address"
                autoCapitalize="none"
                value={editUserEmail}
                onChangeText={setEditUserEmail}
                iconName="mail-outline"
              />

              <CustomInput
                label="Nueva Contraseña (Opcional)"
                placeholder="Dejar en blanco para conservar actual"
                secureTextEntry
                isPassword
                value={editUserPassword}
                onChangeText={setEditUserPassword}
                iconName="lock-closed-outline"
              />

              <CustomInput
                label="Teléfono"
                placeholder="10 dígitos"
                keyboardType="phone-pad"
                value={editUserPhone}
                onChangeText={setEditUserPhone}
                iconName="call-outline"
              />

              <View style={styles.selectorGroup}>
                <Text style={[styles.selectorLabel, { color: themeColors.text }]}>Rol Organizacional *</Text>
                <View style={styles.paymentSelector}>
                  {(['EMPLEADO', 'ADMIN', 'DEV'] as const).map((role) => {
                    const isActive = editUserRole === role;
                    return (
                      <TouchableOpacity
                        key={role}
                        onPress={() => setEditUserRole(role)}
                        style={[
                          styles.paymentOption,
                          {
                            backgroundColor: isActive ? themeColors.accent : themeColors.backgroundElement,
                            borderColor: isActive ? 'transparent' : themeColors.border,
                            flex: 1,
                            alignItems: 'center',
                          },
                        ]}
                      >
                        <Text style={[styles.paymentOptionText, { color: isActive ? '#ffffff' : themeColors.text }]}>
                          {role}
                        </Text>
                      </TouchableOpacity>
                    );
                  })}
                </View>
              </View>

              <CustomButton
                title="Guardar Cambios"
                onPress={handleUpdateUser}
                loading={isUpdatingUser}
                style={{ marginTop: Spacing.three }}
              />
            </ScrollView>
          </View>
        </View>
      </Modal>

      {/* Modal de Mi Perfil (Admin) */}
      <Modal statusBarTranslucent={true}
        animationType="slide"
        transparent={true}
        visible={profileModalVisible}
        onRequestClose={() => setProfileModalVisible(false)}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, { backgroundColor: themeColors.background }]}>
            <View style={styles.modalHeader}>
              <Text style={[styles.modalTitle, { color: themeColors.text }]}>Mi Perfil</Text>
              <TouchableOpacity
                onPress={() => {
                  setProfileModalVisible(false);
                  setProfilePassword('');
                }}
              >
                <Ionicons name="close" size={24} color={themeColors.text} />
              </TouchableOpacity>
            </View>

            <ScrollView contentContainerStyle={styles.modalScroll}>
              <View style={styles.modalDetails}>
                <CustomInput
                  label="Nombre Completo"
                  value={adminUser?.nombre || ''}
                  editable={false}
                  style={{ opacity: 0.7 }}
                />
                
                <CustomInput
                  label="Correo Electrónico"
                  value={adminUser?.email || ''}
                  editable={false}
                  autoCapitalize="none"
                  style={{ opacity: 0.7 }}
                />

                <CustomInput
                  label="Rol"
                  value={adminUser?.rol || ''}
                  editable={false}
                  style={{ opacity: 0.7 }}
                />

                <CustomInput
                  label="Teléfono"
                  placeholder="Ej. 5512345678"
                  value={profilePhone}
                  onChangeText={setProfilePhone}
                  keyboardType="phone-pad"
                />

                <CustomInput
                  label="Nueva Contraseña (Opcional)"
                  placeholder="Dejar en blanco para no cambiar"
                  value={profilePassword}
                  onChangeText={setProfilePassword}
                  isPassword
                  autoCapitalize="none"
                />

                <View style={{ marginTop: Spacing.two }}>
                  <CustomButton
                    title="Guardar Cambios"
                    onPress={handleSaveProfile}
                    loading={isSavingProfile}
                    variant="primary"
                  />
                </View>

                <TouchableOpacity
                  style={{
                    flexDirection: 'row',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: scheme === 'dark' ? '#0f2b48' : '#e0f2fe',
                    paddingVertical: 10,
                    paddingHorizontal: 14,
                    borderRadius: BorderRadius.medium,
                    borderWidth: 1,
                    borderColor: scheme === 'dark' ? '#0284c7' : '#bae6fd',
                    marginTop: Spacing.two,
                  }}
                  onPress={() => {
                    setProfileModalVisible(false);
                    router.push('/(admin)/documentos?tab=mis_documentos' as any);
                  }}
                >
                  <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
                    <Ionicons name="pencil" size={16} color="#0284c7" />
                    <Text style={{ color: '#0284c7', fontWeight: 'bold', fontSize: 13 }}>
                      Mis Documentos por Firmar
                    </Text>
                  </View>
                  <Ionicons name="chevron-forward" size={16} color="#0284c7" />
                </TouchableOpacity>
              </View>
            </ScrollView>
          </View>
        </View>
      </Modal>

      <ImageViewerModal
        visible={viewerVisible}
        imageUrl={activePreviewUrl}
        onClose={() => {
          setViewerVisible(false);
          setActivePreviewUrl(null);
        }}
      />

      {/* ========== MODAL: Historial de Asistencia ========== */}
      <Modal statusBarTranslucent={true}
        animationType="slide"
        transparent={true}
        visible={asistenciaModalVisible}
        onRequestClose={() => {
          setAsistenciaModalVisible(false);
          setAsistenciaEmpleado(null);
          setAsistencias([]);
        }}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, { backgroundColor: themeColors.background, height: '85%' }]}>
            <View style={styles.modalHeader}>
              <View style={{ flex: 1 }}>
                <Text style={[styles.modalTitle, { color: themeColors.text }]}>Historial de Asistencia</Text>
                {asistenciaEmpleado && (
                  <Text style={{ color: themeColors.textSecondary, fontSize: 13, marginTop: 2 }}>
                    {asistenciaEmpleado.nombre}
                  </Text>
                )}
              </View>
              <TouchableOpacity onPress={() => {
                setAsistenciaModalVisible(false);
                setAsistenciaEmpleado(null);
                setAsistencias([]);
              }}>
                <Ionicons name="close" size={24} color={themeColors.text} />
              </TouchableOpacity>
            </View>

            {isLoadingAsistencias ? (
              <View style={styles.loaderContainer}>
                <ActivityIndicator size="large" color={themeColors.accent} />
                <Text style={{ color: themeColors.textSecondary, marginTop: Spacing.one }}>Cargando historial...</Text>
              </View>
            ) : (
              <FlatList scrollEnabled={false}
                data={asistencias}
                initialNumToRender={8}
                maxToRenderPerBatch={8}
                windowSize={5}
                removeClippedSubviews={true}
                keyExtractor={(item) => item.id}
                contentContainerStyle={{ paddingBottom: Spacing.seven }}
                renderItem={({ item }) => (
                  <View style={[styles.asistenciaCard, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border }]}>
                    <Text style={[styles.asistenciaFecha, { color: themeColors.text }]}>
                      📅 {formatAsistenciaFecha(item.fecha)}
                    </Text>
                    <View style={styles.asistenciaRow}>
                      {/* Entrada */}
                      <View style={styles.asistenciaBlock}>
                        <Text style={[styles.asistenciaBlockLabel, { color: themeColors.success }]}>📥 Entrada</Text>
                        {item.foto_entrada_url ? (
                          <TouchableOpacity
                            style={styles.asistenciaThumb}
                            activeOpacity={0.8}
                            onPress={() => {
                              setAsistenciaPreviewUrl(item.foto_entrada_url!);
                              setSelectedAsistenciaInfo({
                                fecha: item.fecha,
                                hora: item.hora_entrada!,
                                direccion: item.direccion_entrada || 'Dirección no registrada',
                                lat: Number(item.latitud_entrada),
                                lng: Number(item.longitud_entrada),
                                empleadoNombre: asistenciaEmpleado?.nombre || 'Empleado',
                                tipo: 'Entrada',
                              });
                              setAsistenciaViewerVisible(true);
                            }}
                          >
                            <Image source={{ uri: item.foto_entrada_url }} style={styles.asistenciaThumbImg} resizeMode="cover" />
                          </TouchableOpacity>
                        ) : (
                          <View style={[styles.asistenciaNoImg, { backgroundColor: themeColors.backgroundSelected }]}>
                            <Ionicons name="image-outline" size={24} color={themeColors.textSecondary} />
                          </View>
                        )}
                        <Text style={[styles.asistenciaHora, { color: themeColors.text }]}>
                          {item.hora_entrada?.substring(0, 5) || '--:--'}
                        </Text>
                        {item.direccion_entrada ? (
                          <TouchableOpacity
                            onPress={() => handleOpenMap(Number(item.latitud_entrada), Number(item.longitud_entrada))}
                            activeOpacity={0.7}
                            style={{ width: '100%' }}
                          >
                            <Text style={[styles.asistenciaAddress, { color: themeColors.textSecondary }]} numberOfLines={3}>
                              🏠 {item.direccion_entrada}
                            </Text>
                          </TouchableOpacity>
                        ) : item.latitud_entrada != null && (
                          <TouchableOpacity
                            onPress={() => handleOpenMap(Number(item.latitud_entrada), Number(item.longitud_entrada))}
                            activeOpacity={0.7}
                          >
                            <Text style={[styles.asistenciaCoords, { color: themeColors.textSecondary }]}>
                              📍 {Number(item.latitud_entrada).toFixed(4)}, {Number(item.longitud_entrada).toFixed(4)}
                            </Text>
                          </TouchableOpacity>
                        )}
                      </View>

                      {/* Salida */}
                      <View style={styles.asistenciaBlock}>
                        <Text style={[styles.asistenciaBlockLabel, { color: item.hora_salida ? themeColors.accent : themeColors.warning }]}>
                          📤 Salida
                        </Text>
                        {item.foto_salida_url ? (
                          <TouchableOpacity
                            style={styles.asistenciaThumb}
                            activeOpacity={0.8}
                            onPress={() => {
                              setAsistenciaPreviewUrl(item.foto_salida_url!);
                              setSelectedAsistenciaInfo({
                                fecha: item.fecha,
                                hora: item.hora_salida!,
                                direccion: item.direccion_salida || 'Dirección no registrada',
                                lat: Number(item.latitud_salida),
                                lng: Number(item.longitud_salida),
                                empleadoNombre: asistenciaEmpleado?.nombre || 'Empleado',
                                tipo: 'Salida',
                              });
                              setAsistenciaViewerVisible(true);
                            }}
                          >
                            <Image source={{ uri: item.foto_salida_url }} style={styles.asistenciaThumbImg} resizeMode="cover" />
                          </TouchableOpacity>
                        ) : (
                          <View style={[styles.asistenciaNoImg, { backgroundColor: themeColors.backgroundSelected }]}>
                            <Ionicons name={item.hora_salida ? 'image-outline' : 'hourglass-outline'} size={24} color={themeColors.textSecondary} />
                            {!item.hora_salida && (
                              <Text style={{ fontSize: 9, color: themeColors.warning, fontWeight: '700', marginTop: 2 }}>Pendiente</Text>
                            )}
                          </View>
                        )}
                        <Text style={[styles.asistenciaHora, { color: item.hora_salida ? themeColors.text : themeColors.warning }]}>
                          {item.hora_salida?.substring(0, 5) || 'Pendiente'}
                        </Text>
                        {item.direccion_salida ? (
                          <TouchableOpacity
                            onPress={() => handleOpenMap(Number(item.latitud_salida), Number(item.longitud_salida))}
                            activeOpacity={0.7}
                            style={{ width: '100%' }}
                          >
                            <Text style={[styles.asistenciaAddress, { color: themeColors.textSecondary }]} numberOfLines={3}>
                              🏠 {item.direccion_salida}
                            </Text>
                          </TouchableOpacity>
                        ) : item.latitud_salida != null && (
                          <TouchableOpacity
                            onPress={() => handleOpenMap(Number(item.latitud_salida), Number(item.longitud_salida))}
                            activeOpacity={0.7}
                          >
                            <Text style={[styles.asistenciaCoords, { color: themeColors.textSecondary }]}>
                              📍 {Number(item.latitud_salida).toFixed(4)}, {Number(item.longitud_salida).toFixed(4)}
                            </Text>
                          </TouchableOpacity>
                        )}
                      </View>
                    </View>
                  </View>
                )}
                ListEmptyComponent={
                  <View style={styles.emptyContainer}>
                    <Ionicons name="calendar-outline" size={48} color={themeColors.textSecondary} />
                    <Text style={[styles.emptyText, { color: themeColors.textSecondary }]}>
                      No hay registros de asistencia para este empleado.
                    </Text>
                  </View>
                }
              />
            )}
          </View>
        </View>
      </Modal>

      {/* Image Viewer for Attendance Photos */}
      <ImageViewerModal
        visible={asistenciaViewerVisible}
        imageUrl={asistenciaPreviewUrl}
        asistenciaInfo={selectedAsistenciaInfo}
        onClose={() => {
          setAsistenciaViewerVisible(false);
          setAsistenciaPreviewUrl(null);
          setSelectedAsistenciaInfo(null);
        }}
      />
      
    </View>
    </SafeAreaView>
  );
}

