  },
  asistenciaThumb: {
    width: '100%',
    aspectRatio: 1,
    borderRadius: BorderRadius.medium,
    overflow: 'hidden',
  },
  asistenciaThumbImg: {
    width: '100%',
    height: '100%',
  },
  asistenciaNoImg: {
