                      </Text>
                    </View>
                  </View>
                </View>

                {/* Bloque Facturación Electrónica (CFDI 4.0 con Finkok) */}
                <View style={[styles.modalCard, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border }]}>
