  },
  dropdownMenu: {
    position: 'absolute',
    top: 56,
    right: 16,
    width: 220,
    borderRadius: BorderRadius.medium,
    borderWidth: 1,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.15,
    shadowRadius: 12,
    elevation: 8,
    zIndex: 10,
    overflow: 'hidden',
  },
  dropdownItem: {
