                    onPress={() => {
                      setFacturado(false);
                      setFacturaStatus('PENDIENTE');
                      setFacturaUri(null);
                      setFacturaBase64(null);
                      setFacturaExt(null);
                    }}
                    style={[
                      styles.paymentOption,
                      {
                        backgroundColor: (facturado === false && facturaStatus === 'PENDIENTE') ? themeColors.warning : themeColors.backgroundElement,
