    flex: 1,
  },
  pdfFileName: {
    fontSize: 13,
    fontWeight: '600',
    flex: 1,
  },
  removeInvoiceBtn: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: Spacing.two,
    paddingVertical: Spacing.one,
    borderRadius: BorderRadius.small,
    gap: Spacing.half,
  },
});

import React, { useEffect, useState, useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  Modal,
  ScrollView,
  TouchableOpacity,
  ActivityIndicator,
  Alert,
  Platform,
  Linking,
} from 'react-native';
import { useColorScheme } from '@/hooks/use-color-scheme';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { useRouter } from 'expo-router';
import { Image } from 'expo-image';
import { Colors, Spacing, BorderRadius } from '@/constants/theme';
import { supabase, Gasto, GastoHelper, GastoService, AuthService, Usuario, Asistencia, AsistenciaService, inttecClient, daravisaClient, Vehiculo, RegistroGasolina, VehiculoService } from '@/services/supabase';
import { SyncService, OfflineGastoItem } from '@/services/sync';
import { getApiHeaders, getApiUrl } from '@/services/apiHelper';
import ExpenseCard from '@/components/ExpenseCard';
import CustomButton from '@/components/CustomButton';
import CustomInput from '@/components/CustomInput';
import { Ionicons } from '@expo/vector-icons';
import { SafeAreaView } from 'react-native-safe-area-context';
import ImageViewerModal from '@/components/ImageViewerModal';
import PendingTasksPopover from '@/components/PendingTasksPopover';
import { CameraView, useCameraPermissions } from 'expo-camera';
import * as Location from 'expo-location';

import { useAuth } from '@/context/AuthContext';



export default function EmpleadoGastos() {
  const router = useRouter();
  const scheme = useColorScheme();
  const themeColors = Colors[scheme === 'dark' ? 'dark' : 'light'];
  const { setUser: setAuthUser, company, changeCompany, env, changeEnv } = useAuth();

  const [user, setUser] = useState<Usuario | null>(null);
  const [gastos, setGastos] = useState<Gasto[]>([]);
  const [offlineGastos, setOfflineGastos] = useState<OfflineGastoItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'pendientes' | 'historial'>('pendientes');
  const [isSyncing, setIsSyncing] = useState(false);
  const [showTasksPopover, setShowTasksPopover] = useState(false);

  // Modal de Detalles
  const [selectedGasto, setSelectedGasto] = useState<(Gasto & { isOffline?: boolean }) | null>(null);
  const [modalVisible, setModalVisible] = useState(false);
  const [viewerVisible, setViewerVisible] = useState(false);
  const [activePreviewUrl, setActivePreviewUrl] = useState<string | null>(null);
  
  // Feedback para Action Required
  const [repondFeedback, setRespondFeedback] = useState('');
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [isSubmittingResponse, setIsSubmittingResponse] = useState(false);

  // Modal de Perfil
  const [profileModalVisible, setProfileModalVisible] = useState(false);
  const [profilePhone, setProfilePhone] = useState('');
  const [profilePassword, setProfilePassword] = useState('');
  const [isSavingProfile, setIsSavingProfile] = useState(false);

  // Vehículos y Gasolina
  const [employeeVehiculosModalVisible, setEmployeeVehiculosModalVisible] = useState(false);
  const [vehiculos, setVehiculos] = useState<Vehiculo[]>([]);
  const [misRegistrosGasolina, setMisRegistrosGasolina] = useState<RegistroGasolina[]>([]);

  // --- Auto-Checador ---
  const [checadorInstructionVisible, setChecadorInstructionVisible] = useState(false);
  const [checadorCameraVisible, setChecadorCameraVisible] = useState(false);
  const [checadorResultVisible, setChecadorResultVisible] = useState(false);
  const [registroHoy, setRegistroHoy] = useState<Asistencia | null>(null);
  const [isLoadingChecador, setIsLoadingChecador] = useState(false);
  const [isCapturing, setIsCapturing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [prevCurrentLocation, setPrevCurrentLocation] = useState(currentLocation);
  const [checadorMapUrl, setChecadorMapUrl] = useState<string | null>(() => {
    if (!currentLocation) return null;
    const apiKey = process.env.EXPO_PUBLIC_GOOGLE_MAPS_API_KEY || "AIzaSyDgvQcdXQYx8uSGNJJ4wENAGkIVbDIaUXc";
    return `https://maps.googleapis.com/maps/api/staticmap?center=${currentLocation.lat},${currentLocation.lng}&zoom=16&size=200x200&markers=color:red%7C${currentLocation.lat},${currentLocation.lng}&key=${apiKey}`;
  });

  if (currentLocation !== prevCurrentLocation) {
    setPrevCurrentLocation(currentLocation);
    if (currentLocation) {
      const apiKey = process.env.EXPO_PUBLIC_GOOGLE_MAPS_API_KEY || "AIzaSyDgvQcdXQYx8uSGNJJ4wENAGkIVbDIaUXc";
      setChecadorMapUrl(`https://maps.googleapis.com/maps/api/staticmap?center=${currentLocation.lat},${currentLocation.lng}&zoom=16&size=200x200&markers=color:red%7C${currentLocation.lat},${currentLocation.lng}&key=${apiKey}`);
    } else {
      setChecadorMapUrl(null);
    }
  }

  const [currentAddress, setCurrentAddress] = useState<string>('Obteniendo dirección...');
  const [currentDateTime, setCurrentDateTime] = useState(new Date());
  const [checadorResultMsg, setChecadorResultMsg] = useState('');
  const [checadorResultType, setChecadorResultType] = useState<'entrada' | 'salida'>('entrada');
  const [capturedPhotoUri, setCapturedPhotoUri] = useState<string | null>(null);
  const [selectedAsistenciaInfo, setSelectedAsistenciaInfo] = useState<{
    fecha: string;
    hora: string;
    direccion: string;
    lat: number;
    lng: number;
    empleadoNombre: string;
    tipo: 'Entrada' | 'Salida';
  } | null>(null);
  const cameraRef = useRef<CameraView>(null);
  const [cameraPermission, requestCameraPermission] = useCameraPermissions();
  const dateIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // --- Checador: Lógica ---
  const handleOpenChecador = async () => {
    if (!user) {
      console.error('[Checador] Error: user es nulo o indefinido en handleOpenChecador');
      if (Platform.OS === 'web') {
        window.alert('Error: No se ha iniciado sesión correctamente o el usuario no está cargado.');
      }
      return;
    }
    setIsLoadingChecador(true);
    try {
      const registro = await AsistenciaService.getRegistroHoy(user.id);
      setRegistroHoy(registro);
      if (registro && registro.hora_entrada && registro.hora_salida) {
        if (Platform.OS === 'web') {
          window.alert(`Turno Completo ✅\n\nYa registraste tu entrada (${registro.hora_entrada?.substring(0,5)}) y salida (${registro.hora_salida?.substring(0,5)}) el día de hoy.`);
        } else {
          Alert.alert(
            'Turno Completo ✅',
            `Ya registraste tu entrada (${registro.hora_entrada?.substring(0,5)}) y salida (${registro.hora_salida?.substring(0,5)}) el día de hoy.`,
          );
        }
        return;
      }
      setChecadorInstructionVisible(true);
    } catch (err: any) {
      console.error('[Checador] Error en handleOpenChecador:', err.message || err);
      if (Platform.OS === 'web') {
        window.alert(`Error: ${err.message || 'No se pudo verificar tu asistencia.'}`);
      } else {
        Alert.alert('Error', err.message || 'No se pudo verificar tu asistencia.');
      }
    } finally {
      setIsLoadingChecador(false);
    }
  };
  const handleStartCamera = async () => {
    setChecadorInstructionVisible(false);

    if (!cameraPermission?.granted) {
      const { granted } = await requestCameraPermission();
      if (!granted) {
        Alert.alert('Permisos', 'Se necesita acceso a la cámara para el checador.');
        return;
      }
    }

    const { status } = await Location.requestForegroundPermissionsAsync();
    if (status !== 'granted') {
      Alert.alert('Permisos', 'Se necesita acceso a la ubicación para registrar la asistencia.');
      return;
    }

    try {
      setCurrentAddress('Obteniendo dirección...');
      const loc = await Location.getCurrentPositionAsync({
        accuracy: Location.Accuracy.High,
      });
      const lat = loc.coords.latitude;
      const lng = loc.coords.longitude;
      setCurrentLocation({ lat, lng });

      try {
        const apiKey = process.env.EXPO_PUBLIC_GOOGLE_MAPS_API_KEY || "";
        const response = await fetch(`https://maps.googleapis.com/maps/api/geocode/json?latlng=${lat},${lng}&key=${apiKey}`);
        const data = await response.json();

        if (data.status === 'OK' && data.results && data.results.length > 0) {
          const formatted = data.results[0].formatted_address;
          setCurrentAddress(formatted || 'Dirección no identificada');
        } else {
          throw new Error(data.error_message || `Google Geocoding API status: ${data.status}`);
        }
      } catch {
        try {
          const reverse = await Location.reverseGeocodeAsync({ latitude: lat, longitude: lng });
          if (reverse && reverse.length > 0) {
            const addr = reverse[0];
            const parts = [];
            if (addr.street || addr.streetNumber) parts.push(`${addr.street || ''} ${addr.streetNumber || ''}`.trim());
            if (addr.district) parts.push(addr.district);
            if (addr.postalCode || addr.city || addr.region) {
              let line = '';
              if (addr.postalCode) line += `${addr.postalCode} `;
              if (addr.city) line += addr.city;
              if (addr.region) line += (addr.city ? ', ' : '') + addr.region;
              parts.push(line.trim());
            }
            setCurrentAddress(parts.join(', ') || 'Dirección no identificada');
          } else {
            setCurrentAddress('Dirección no disponible');
          }
        } catch {
          setCurrentAddress(`Coordenadas: ${lat.toFixed(5)}, ${lng.toFixed(5)}`);
        }
      }
    } catch (err: any) {
      console.error('[Checador] Error crítico al obtener ubicación:', err.message || err);
      setCurrentLocation(null);
      setCurrentAddress('Ubicación no disponible');
    }

    setCurrentDateTime(new Date());
    dateIntervalRef.current = setInterval(() => {
      setCurrentDateTime(new Date());
    }, 1000);

    setChecadorCameraVisible(true);
  };

  const handleCaptureSelfie = async () => {
    if (!cameraRef.current || isCapturing || !user) return;
    setIsCapturing(true);

    try {
      const photo = await cameraRef.current.takePictureAsync({
        quality: 0.7,
        base64: true,
        shutterSound: true,
      });

      let base64Data = photo?.base64;
      if (!base64Data && photo?.uri && photo.uri.startsWith('data:image')) {
        base64Data = photo.uri;
      }

      if (!base64Data) {
        throw new Error('No se pudo capturar la foto.');
      }

      if (dateIntervalRef.current) clearInterval(dateIntervalRef.current);
      setChecadorCameraVisible(false);

      const tipoRegistro = registroHoy?.hora_entrada ? 'salida' : 'entrada';
      const fotoUrl = await AsistenciaService.subirFotoAsistencia(user.id, base64Data, tipoRegistro);

      const lat = currentLocation?.lat || 0;
      const lng = currentLocation?.lng || 0;
      const addressToSave = currentAddress || 'Ubicación registrada';

      if (tipoRegistro === 'entrada') {
        await AsistenciaService.registrarEntrada(user.id, fotoUrl, lat, lng, addressToSave);
        setChecadorResultMsg('Entrada registrada correctamente');
      } else {
        await AsistenciaService.registrarSalida(registroHoy!.id, fotoUrl, lat, lng, addressToSave);
        setChecadorResultMsg('Salida registrada correctamente');
      }

      setCapturedPhotoUri(photo.uri);
      setChecadorResultType(tipoRegistro);
      setChecadorResultVisible(true);
    } catch (err: any) {
      Alert.alert('Error al registrar', err.message || 'No se pudo procesar la asistencia.');
    } finally {
      setIsCapturing(false);
    }
  };

  const handleCloseCamera = () => {
    if (dateIntervalRef.current) clearInterval(dateIntervalRef.current);
    setChecadorCameraVisible(false);
  };

  const handleCloseResult = () => {
    setChecadorResultVisible(false);
    setCapturedPhotoUri(null);
    setChecadorResultMsg('');
  };

  const formatChecadorTime = (date: Date) => {
    return date.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });
  };

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const formatChecadorDate = (date: Date) => {
    return date.toLocaleDateString('es-MX', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
  };

  const handleOpenProfile = () => {
    if (user) {
      setProfilePhone(user.telefono || '');
      setProfilePassword('');
      setProfileModalVisible(true);
    }
  };

  const handleSaveProfile = async () => {
    if (!user) return;
    setIsSavingProfile(true);

    try {
      const updates: any = {
        telefono: profilePhone.trim(),
      };

      if (profilePassword.trim()) {
        updates.password = profilePassword.trim();
      }

      const { error: errorInttec } = await inttecClient
        .from('usuarios')
        .update(updates)
        .eq('id', user.id);
      if (errorInttec) throw errorInttec;

      const { error: errorDaravisa } = await daravisaClient
        .from('usuarios')
        .update(updates)
        .eq('id', user.id);
      if (errorDaravisa) {
        console.error('Error actualizando perfil en Daravisa:', errorDaravisa);
      }

      // Actualizar el estado local y AsyncStorage
      const updatedUser: Usuario = {
        ...user,
        telefono: updates.telefono,
      };

      setUser(updatedUser);
      await AsyncStorage.setItem(`logged_user_${company}`, JSON.stringify(updatedUser));

      Alert.alert('Éxito', 'Perfil actualizado correctamente.');
      setProfileModalVisible(false);
      setProfilePassword('');
    } catch (err: any) {
      Alert.alert('Error', err.message || 'No se pudo actualizar el perfil.');
    } finally {
      setIsSavingProfile(false);
    }
  };

  useEffect(() => {
    // Cargar usuario
    const loadUserAndData = async () => {
      const currentUser = await AuthService.getCurrentUser();
      if (!currentUser) {
        router.replace('/');
        return;
      }
      setUser(currentUser);
      await refreshData(currentUser.id);
    };

    loadUserAndData();

    // Registrar Listener de Sincronización Automática Offline
    const unsubscribe = SyncService.initNetworkSyncListener((count) => {
      Alert.alert('Sincronización Exitosa', `Se han sincronizado ${count} gastos guardados offline.`);
      if (user) refreshData(user.id);
    });

    return () => unsubscribe();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [company, env]);

  useEffect(() => {
    if (!user) return;

    const interval = setInterval(() => {
      refreshData(user.id, true);
    }, 30000);

    return () => clearInterval(interval);
  }, [user]);

  async function refreshData(userId: string, silent = false) {
    if (!silent) {
      setIsLoading(true);
      setGastos([]);
      setOfflineGastos([]);
      setVehiculos([]);
      setMisRegistrosGasolina([]);
    }
    try {
      // 1. Obtener de Backend
      const headers = await getApiHeaders();
      const res = await fetch(`${getApiUrl()}/api/reportes/empleado`, { headers });
      if (!res.ok) throw new Error('Error al obtener gastos');
      const data = await res.json();
      setGastos(data.gastos || []);

      // 2. Obtener cola local offline
      const localQueue = await SyncService.getOfflineQueue();
      setOfflineGastos(localQueue.filter((item) => item.empleado_id === userId));

      // 3. Obtener vehículos activos
      const activeVehicles = await VehiculoService.getVehiculos(true);
      setVehiculos(activeVehicles || []);

      // 4. Obtener mis registros de gasolina
      const allGasLogs = await VehiculoService.getRegistrosGasolina();
      const myGasLogs = allGasLogs.filter(reg => reg.empleado_id === userId);
      setMisRegistrosGasolina(myGasLogs);
    } catch (err: any) {
      console.error('Error al cargar datos:', err);
    } finally {
      if (!silent) setIsLoading(false);
    }
  }

  const handleSyncManual = async () => {
    if (!user) return;
    setIsSyncing(true);
    try {
      const syncedCount = await SyncService.syncPendingGastos();
      if (syncedCount > 0) {
        Alert.alert('Sincronización', `${syncedCount} gastos subidos con éxito.`);
        await refreshData(user.id);
      } else {
        Alert.alert('Sincronización', 'No hay gastos pendientes o no hay conexión a internet.');
      }
    } catch (err: any) {
      Alert.alert('Error de Sincronización', err.message || 'Error desconocido.');
    } finally {
      setIsSyncing(false);
    }
  };

  const handleLogout = async () => {
    const performLogout = async () => {
      await AuthService.logout();
      setAuthUser(null);
    };

    if (Platform.OS === 'web') {
      const confirm = window.confirm('¿Estás seguro de que deseas cerrar sesión?');
      if (confirm) {
        await performLogout();
      }
      return;
    }

    Alert.alert('Cerrar Sesión', '¿Estás seguro de que deseas salir?', [
      { text: 'Cancelar', style: 'cancel' },
      {
        text: 'Cerrar Sesión',
        style: 'destructive',
        onPress: performLogout,
      },
    ]);
  };

  const handleToggleCompany = async (nextCompany: 'inttec' | 'daravisa') => {
    await changeCompany(nextCompany);
  };

  // Reenviar gasto observado (ACTION_REQUIRED)
  const _handleResubmitGasto = async () => {
    if (!selectedGasto || !repondFeedback.trim()) return;
    setIsSubmittingResponse(true);

    const nuevaJustificacion = `${selectedGasto.justificacion || ''} | Resp Empleado: ${repondFeedback.trim()}`;

    try {
      const headers = await getApiHeaders();
      const res = await fetch(`${getApiUrl()}/api/reportes/gastos/${selectedGasto.id}`, {
        method: 'PUT',
        headers,
        body: JSON.stringify({
          updatePayload: {
            status: 'PENDING',
            rejection_feedback: null,
            justificacion: nuevaJustificacion,
          }
        })
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || 'Error al reenviar gasto');
      }

      Alert.alert('Éxito', 'Gasto reenviado correctamente para revisión.');
      setModalVisible(false);
      setSelectedGasto(null);
      setRespondFeedback('');
      if (user) refreshData(user.id);
    } catch (err: any) {
      Alert.alert('Error', err.message || 'No se pudo reenviar la respuesta');
    } finally {
      setIsSubmittingResponse(false);
    }
  };

  // Filtrar Gastos por Pestaña
  // Pendientes: PENDING, ACTION_REQUIRED y Offline SYNC_PENDING
  const pendingList: (Gasto & { isOffline?: boolean })[] = [
    ...offlineGastos.map((g) => ({ ...g, isOffline: true, status: 'PENDING' as const })),
    ...gastos.filter((g) => g.status === 'PENDING' || g.status === 'ACTION_REQUIRED'),
  ];

  // Historial: APPROVED, REJECTED
  const historyList = gastos.filter((g) => g.status === 'APPROVED' || g.status === 'REJECTED');

  // Cálculos de Resumen
  const saldoPendiente = pendingList.reduce((sum, g) => sum + Number(g.monto), 0);
  const totalAprobado = historyList.filter((g) => g.status === 'APPROVED').reduce((sum, g) => sum + Number(g.monto), 0);

  const formatCurrency = (monto: number) => {
    return new Intl.NumberFormat('es-MX', {
      style: 'currency',
      currency: 'MXN',
    }).format(monto);
  };

  const formatFriendlyDate = (dateStr?: string | null) => {
    if (!dateStr) return 'N/A';
    const parts = dateStr.split('-');
    if (parts.length === 3) {
      return `${parts[2]}/${parts[1]}/${parts[0]}`;
    }
    return dateStr;
  };

  const parseJustificacion = (just: string | null | undefined) => {
    if (!just) return { alerta: null, justificacion: '' };
    const match = just.match(/^\[ALERTA IA:\s*([\s\S]*?)\]\s*\n\s*([\s\S]*)$/);
    if (match) {
      return {
        alerta: match[1],
        justificacion: match[2],
      };
    }
    return { alerta: null, justificacion: just };
  };

  return (
    <SafeAreaView style={[styles.container, { backgroundColor: themeColors.background }]} edges={['top', 'left', 'right']}>
      {/* Header Card Premium */}
      <View style={[
        styles.headerCard, 
        { 
          backgroundColor: themeColors.backgroundElement, 
          borderColor: themeColors.border,
          shadowColor: themeColors.text
        }
      ]}>
        <View style={{ flexDirection: 'row', alignItems: 'center', flex: 1, gap: Spacing.two }}>
          <TouchableOpacity 
            onPress={handleOpenProfile} 
            style={[styles.headerAvatar, { backgroundColor: themeColors.primary + '15' }]}
            activeOpacity={0.7}
          >
            <Text style={[styles.headerAvatarText, { color: themeColors.primary }]}>
              {user?.nombre ? user.nombre.charAt(0).toUpperCase() : 'E'}
            </Text>
          </TouchableOpacity>
          <View style={{ flex: 1 }}>
            <Text style={[styles.headerSubtitle, { color: themeColors.textSecondary }]}>¡Hola de nuevo!</Text>
            <Text style={[styles.headerTitle, { color: themeColors.text }]} numberOfLines={1}>
              {user?.nombre || 'Empleado'}
            </Text>
          </View>
        </View>

        <View style={styles.headerActions}>
          <TouchableOpacity
            onPress={() => setShowTasksPopover(true)}
            style={[styles.headerIconBtn, { backgroundColor: scheme === 'dark' ? 'rgba(255,255,255,0.1)' : 'rgba(0,119,182,0.1)' }]}
          >
            <Ionicons name="notifications-outline" size={20} color={themeColors.text} />
          </TouchableOpacity>

          {user?.rol === 'DEV' && (
            <View style={{ flexDirection: 'row', gap: 8, marginRight: 8 }}>
              <TouchableOpacity
                onPress={() => changeEnv(env === 'cloud' ? 'test' : 'cloud')}
                style={[styles.headerIconBtn, { backgroundColor: env === 'cloud' ? themeColors.primary + '15' : Colors.light.danger + '15' }]}
              >
                <Ionicons name={env === 'cloud' ? "cloud-outline" : "server-outline"} size={20} color={env === 'cloud' ? themeColors.primary : Colors.light.danger} />
              </TouchableOpacity>
              <TouchableOpacity
                onPress={() => router.replace('/(admin)/dashboard')}
                style={[styles.headerIconBtn, { backgroundColor: themeColors.primary + '15' }]}
              >
                <Ionicons name="swap-horizontal-outline" size={20} color={themeColors.primary} />
              </TouchableOpacity>
            </View>
          )}

          {offlineGastos.length > 0 && (
            <TouchableOpacity
              onPress={handleSyncManual}
              disabled={isSyncing}
              style={[styles.headerIconBtn, { backgroundColor: themeColors.warning + '15' }]}
            >
              {isSyncing ? (
                <ActivityIndicator size="small" color={themeColors.warning} />
              ) : (
                <Ionicons name="cloud-upload" size={20} color={themeColors.warning} />
              )}
            </TouchableOpacity>
          )}
        </View>
      </View>

      {/* Switch de Empresa - Fila Dedicada */}
      <View style={{
        flexDirection: 'row',
        justifyContent: 'center',
        alignItems: 'center',
        paddingHorizontal: Spacing.four,
        marginBottom: Spacing.two,
      }}>
        <View style={{
          flexDirection: 'row',
          backgroundColor: scheme === 'dark' ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.05)',
          borderRadius: 20,
          padding: 2,
          alignItems: 'center',
          width: 220,
        }}>
          <TouchableOpacity
            onPress={() => company !== 'inttec' && handleToggleCompany('inttec')}
            style={{
              flex: 1,
              paddingVertical: 6,
              borderRadius: 18,
              backgroundColor: company === 'inttec' ? themeColors.accent : 'transparent',
              alignItems: 'center'
            }}
          >
            <Text style={{
              fontSize: 11,
              fontWeight: '700',
              color: company === 'inttec' ? '#ffffff' : themeColors.textSecondary,
            }}>
              INTTEC
            </Text>
          </TouchableOpacity>
          <TouchableOpacity
            onPress={() => company !== 'daravisa' && handleToggleCompany('daravisa')}
            style={{
              flex: 1,
              paddingVertical: 6,
              borderRadius: 18,
              backgroundColor: company === 'daravisa' ? themeColors.accent : 'transparent',
              alignItems: 'center'
            }}
          >
            <Text style={{
              fontSize: 11,
              fontWeight: '700',
              color: company === 'daravisa' ? '#ffffff' : themeColors.textSecondary,
            }}>
              DARAVISA
            </Text>
          </TouchableOpacity>
        </View>
      </View>

      <PendingTasksPopover 
        visible={showTasksPopover} 
        onClose={() => setShowTasksPopover(false)} 
      />

      {/* Resumen Cards */}
      <View style={styles.summaryContainer}>
        <View style={[styles.summaryCard, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border }]}>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, marginBottom: 4 }}>
            <View style={{ width: 24, height: 24, borderRadius: 12, backgroundColor: themeColors.warning + '18', alignItems: 'center', justifyContent: 'center' }}>
              <Ionicons name="time" size={14} color={themeColors.warning} />
            </View>
            <Text style={[styles.summaryLabel, { color: themeColors.textSecondary }]} numberOfLines={1}>
              PENDIENTE / OFFLINE
            </Text>
          </View>
          <Text
            style={[styles.summaryValue, { color: themeColors.text }]}
            numberOfLines={1}
            adjustsFontSizeToFit={true}
            minimumFontScale={0.75}
          >
            {formatCurrency(saldoPendiente)}
          </Text>
        </View>

        <View style={[styles.summaryCard, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border }]}>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, marginBottom: 4 }}>
            <View style={{ width: 24, height: 24, borderRadius: 12, backgroundColor: themeColors.success + '18', alignItems: 'center', justifyContent: 'center' }}>
              <Ionicons name="checkmark-circle" size={14} color={themeColors.success} />
            </View>
            <Text style={[styles.summaryLabel, { color: themeColors.textSecondary }]} numberOfLines={1}>
              TOTAL APROBADO
            </Text>
          </View>
          <Text
            style={[styles.summaryValue, { color: themeColors.success }]}
            numberOfLines={1}
            adjustsFontSizeToFit={true}
            minimumFontScale={0.75}
          >
            {formatCurrency(totalAprobado)}
          </Text>
        </View>
      </View>

      {/* Tabs */}
      <View style={styles.tabsContainer}>
        <TouchableOpacity
          onPress={() => setActiveTab('pendientes')}
          style={[
            styles.tab,
            activeTab === 'pendientes' && { borderBottomColor: themeColors.accent, borderBottomWidth: 3 },
          ]}
        >
          <Text
            style={[
              styles.tabText,
              { color: activeTab === 'pendientes' ? themeColors.text : themeColors.textSecondary },
              activeTab === 'pendientes' && styles.tabTextActive,
            ]}
          >
            Pendientes ({pendingList.length})
          </Text>
        </TouchableOpacity>
        <TouchableOpacity
          onPress={() => setActiveTab('historial')}
          style={[
            styles.tab,
            activeTab === 'historial' && { borderBottomColor: themeColors.accent, borderBottomWidth: 3 },
          ]}
        >
          <Text
            style={[
              styles.tabText,
              { color: activeTab === 'historial' ? themeColors.text : themeColors.textSecondary },
              activeTab === 'historial' && styles.tabTextActive,
            ]}
          >
            Historial ({historyList.length})
          </Text>
        </TouchableOpacity>
      </View>

      {/* List */}
      {isLoading ? (
        <View style={styles.loaderContainer}>
          <ActivityIndicator size="large" color={themeColors.accent} />
          <Text style={{ color: themeColors.textSecondary, marginTop: Spacing.one }}>Cargando gastos...</Text>
        </View>
      ) : (
        <FlatList
          initialNumToRender={8}
          maxToRenderPerBatch={8}
          windowSize={5}
          removeClippedSubviews={true}
          data={activeTab === 'pendientes' ? pendingList : historyList}
          keyExtractor={(item) => item.id}
          contentContainerStyle={styles.listContent}
          renderItem={({ item }) => (
            <ExpenseCard
              gasto={item}
              onPress={() => {
                setSelectedGasto(item);
                setModalVisible(true);
              }}
            />
          )}
          ListEmptyComponent={
            <View style={styles.emptyContainer}>
              <Ionicons name="file-tray-outline" size={48} color={themeColors.textSecondary} />
              <Text style={[styles.emptyText, { color: themeColors.textSecondary }]}>
                No hay gastos registrados en esta categoría.
              </Text>
            </View>
          }
          refreshing={isLoading}
          onRefresh={() => user && refreshData(user.id)}
        />
      )}

      {/* Floating Action Buttons (Right Side) */}
      <View style={styles.fabContainer}>
        {/* Registrar Gasto */}
        <TouchableOpacity
          activeOpacity={0.8}
          onPress={() => router.push('/(empleado)/formulario')}
          style={[styles.fab, { backgroundColor: themeColors.accent }]}
        >
          <Ionicons name="receipt" size={24} color="#ffffff" />
        </TouchableOpacity>
      </View>

      {/* ========== MODAL: Instrucciones del Checador ========== */}
      <Modal statusBarTranslucent={true}
        animationType="slide"
        transparent={true}
        visible={checadorInstructionVisible}
        onRequestClose={() => setChecadorInstructionVisible(false)}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, { backgroundColor: themeColors.background, height: '55%' }]}>
            <View style={styles.modalHeader}>
              <Text style={[styles.modalTitle, { color: themeColors.text }]}>Auto-Checador</Text>
              <TouchableOpacity onPress={() => setChecadorInstructionVisible(false)}>
                <Ionicons name="close" size={24} color={themeColors.text} />
              </TouchableOpacity>
            </View>

            <ScrollView contentContainerStyle={[styles.modalScroll, { alignItems: 'center', paddingTop: Spacing.three }]}>
              <View style={[styles.checadorIconCircle, { backgroundColor: themeColors.success + '15' }]}>
                <Ionicons name="camera" size={48} color={themeColors.success} />
              </View>

              <Text style={[styles.checadorTitle, { color: themeColors.text }]}>
                {registroHoy?.hora_entrada ? 'Registrar Salida' : 'Registrar Entrada'}
              </Text>

              <Text style={[styles.checadorDesc, { color: themeColors.textSecondary }]}>
                Se tomará una selfie con la cámara frontal para registrar tu asistencia. También se capturará tu ubicación como verificación.
              </Text>

              {registroHoy?.hora_entrada && (
                <View style={[styles.checadorStatusCard, { backgroundColor: themeColors.success + '10', borderColor: themeColors.success }]}>
                  <Ionicons name="checkmark-circle" size={20} color={themeColors.success} />
                  <Text style={[styles.checadorStatusText, { color: themeColors.success }]}>
                    Entrada registrada a las {registroHoy.hora_entrada?.substring(0, 5)}
                  </Text>
                </View>
              )}

              <CustomButton
                title={registroHoy?.hora_entrada ? 'Registrar Salida' : 'Registrar Entrada'}
                onPress={handleStartCamera}
                variant="success"
                style={{ width: '100%', marginTop: Spacing.three }}
                icon={<Ionicons name="camera-outline" size={20} color="#fff" style={{ marginRight: 8 }} />}
              />
            </ScrollView>
          </View>
        </View>
      </Modal>

      {/* ========== MODAL: Cámara con Marca de Agua ========== */}
      <Modal statusBarTranslucent={true}
        animationType="fade"
        transparent={false}
        visible={checadorCameraVisible}
        onRequestClose={handleCloseCamera}
      >
        <View style={styles.cameraContainer}>
          <CameraView
            ref={cameraRef}
            style={styles.cameraPreview}
            facing="front"
            mode="picture"
          />
          {/* Overlay: Marca de Agua */}
          <SafeAreaView style={styles.cameraOverlay}>
            {/* Top bar */}
            <View style={styles.watermarkTop}>
              <TouchableOpacity onPress={handleCloseCamera} style={styles.cameraCloseBtn}>
                <Ionicons name="close" size={28} color="#fff" />
              </TouchableOpacity>
              <View style={styles.watermarkBadge}>
                <Text style={styles.watermarkBadgeText}>
                  {registroHoy?.hora_entrada ? '📤 SALIDA' : '📥 ENTRADA'}
                </Text>
              </View>
            </View>

            {/* Bottom watermark info */}
            <View style={styles.watermarkBottom}>
              {/* Botón de captura */}
              <TouchableOpacity
                style={styles.captureBtn}
                onPress={handleCaptureSelfie}
                disabled={isCapturing}
                activeOpacity={0.7}
              >
                {isCapturing ? (
                  <ActivityIndicator size="large" color="#fff" />
                ) : (
                  <View style={styles.captureBtnInner} />
                )}
              </TouchableOpacity>

              {/* Contenedor de la marca de agua estilo foto Timemark */}
              <View style={styles.watermarkOverlayCard}>
                {/* Lado Izquierdo: Hora, Fecha y Dirección */}
                <View style={styles.watermarkLeftCol}>
                  {/* Fila superior: Hora | Fecha */}
                  <View style={styles.watermarkTimeDateRow}>
                    <Text style={styles.watermarkTimeText}>
                      {formatChecadorTime(currentDateTime).substring(0, 5)}
                    </Text>
                    <View style={styles.watermarkVerticalLine} />
                    <View style={styles.watermarkDateCol}>
                      <Text style={styles.watermarkDateText}>
                        {currentDateTime.toLocaleDateString('es-MX', { day: 'numeric', month: 'short', year: 'numeric' })}
                      </Text>
                      <Text style={styles.watermarkDayText}>
                        {currentDateTime.toLocaleDateString('es-MX', { weekday: 'long' }).toUpperCase()}
                      </Text>
                    </View>
                  </View>
                  {/* Dirección */}
                  <Text style={styles.watermarkAddressText} numberOfLines={3}>
                    {currentAddress}
                  </Text>
                  {/* Nombre del Empleado */}
                  <Text style={styles.watermarkEmployeeText}>
                    👤 {user?.nombre || 'Empleado'}
                  </Text>
                </View>

                {/* Lado Derecho: Mapa */}
                {currentLocation && checadorMapUrl ? (
                  <View style={styles.watermarkMapContainer}>
                    <Image
                      source={{
                        uri: checadorMapUrl,
                      }}
                      onError={() => {
                        if (currentLocation && (!checadorMapUrl || !checadorMapUrl.includes('openstreetmap.de'))) {
                          setChecadorMapUrl(`https://staticmap.openstreetmap.de/staticmap.php?center=${currentLocation.lat},${currentLocation.lng}&zoom=16&size=200x200&maptype=mapnik&markers=${currentLocation.lat},${currentLocation.lng},red-pushpin`);
                        }
                      }}
                      style={styles.watermarkMapView}
                      resizeMode="cover"
                    />
                  </View>
                ) : currentLocation ? (
                  <View style={[styles.watermarkMapContainer, { justifyContent: 'center', alignItems: 'center', backgroundColor: '#333' }]}>
                    <ActivityIndicator size="small" color="#fff" />
                  </View>
                ) : (
                  <View style={styles.watermarkMapPlaceholder}>
                    <Ionicons name="map" size={20} color="#888" />
                    <Text style={{ fontSize: 7, color: '#888', marginTop: 2, fontWeight: '700' }}>Sin Mapa</Text>
                  </View>
                )}
              </View>
            </View>
          </SafeAreaView>
        </View>
      </Modal>

      {/* ========== MODAL: Resultado del Checador ========== */}
      <Modal statusBarTranslucent={true}
        animationType="slide"
        transparent={true}
        visible={checadorResultVisible}
        onRequestClose={handleCloseResult}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, { backgroundColor: themeColors.background, height: '60%' }]}>
            <View style={styles.modalHeader}>
              <Text style={[styles.modalTitle, { color: themeColors.text }]}>Asistencia Registrada</Text>
              <TouchableOpacity onPress={handleCloseResult}>
                <Ionicons name="close" size={24} color={themeColors.text} />
              </TouchableOpacity>
            </View>

            <ScrollView contentContainerStyle={[styles.modalScroll, { alignItems: 'center' }]}>
              <View style={[styles.checadorIconCircle, { backgroundColor: themeColors.success + '15' }]}>
                <Ionicons name="checkmark-circle" size={56} color={themeColors.success} />
              </View>

              <Text style={[styles.checadorTitle, { color: themeColors.success }]}>
                {checadorResultType === 'entrada' ? '📥 Entrada Registrada' : '📤 Salida Registrada'}
              </Text>
              <Text style={[styles.checadorDesc, { color: themeColors.textSecondary }]}>
                {checadorResultMsg}
              </Text>

              {capturedPhotoUri && (
                <TouchableOpacity
                  activeOpacity={0.8}
                  onPress={() => {
                    setActivePreviewUrl(capturedPhotoUri);
                    setSelectedAsistenciaInfo({
                      fecha: new Date().toISOString().split('T')[0],
                      hora: formatChecadorTime(new Date()),
                      direccion: currentAddress,
                      lat: currentLocation?.lat || 0,
                      lng: currentLocation?.lng || 0,
                      empleadoNombre: user?.nombre || 'Empleado',
                      tipo: checadorResultType === 'entrada' ? 'Entrada' : 'Salida',
                    });
                    setViewerVisible(true);
                  }}
                  style={styles.resultPhotoContainer}
                >
                  <Image source={{ uri: capturedPhotoUri }} style={styles.resultPhoto} resizeMode="cover" />
                </TouchableOpacity>
              )}

              <View style={styles.resultInfoRow}>
                <Ionicons name="time-outline" size={18} color={themeColors.textSecondary} />
                <Text style={[styles.resultInfoText, { color: themeColors.text }]}>
                  {formatChecadorTime(new Date())}
                </Text>
              </View>
              {currentAddress && (
                <View style={[styles.resultInfoRow, { paddingHorizontal: Spacing.three }]}>
                  <Ionicons name="location-outline" size={18} color={themeColors.textSecondary} style={{ alignSelf: 'flex-start', marginTop: 2 }} />
                  <Text style={[styles.resultInfoText, { color: themeColors.text, flex: 1, flexWrap: 'wrap' }]}>
                    {currentAddress}
                  </Text>
                </View>
              )}

              <CustomButton
                title="Cerrar"
                onPress={handleCloseResult}
                variant="primary"
                style={{ width: '100%', marginTop: Spacing.four }}
              />
            </ScrollView>
          </View>
        </View>
      </Modal>

      {/* Modal de Detalle */}
      <Modal statusBarTranslucent={true}
        animationType="slide"
        transparent={true}
        visible={modalVisible}
        onRequestClose={() => setModalVisible(false)}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, { backgroundColor: themeColors.background }]}>
            <View style={styles.modalHeader}>
              <Text style={[styles.modalTitle, { color: themeColors.text }]}>Detalle del Gasto</Text>
              <TouchableOpacity
                onPress={() => {
                  setModalVisible(false);
                  setSelectedGasto(null);
                  setRespondFeedback('');
                }}
              >
                <Ionicons name="close" size={24} color={themeColors.text} />
              </TouchableOpacity>
            </View>

            {selectedGasto && (
              <ScrollView contentContainerStyle={styles.modalScroll}>
                {/* Evidencia Imagen */}
                {selectedGasto.foto_url || (selectedGasto.isOffline && (selectedGasto as any).base64Foto) ? (
                  <TouchableOpacity
                    activeOpacity={0.9}
                    onPress={() => {
                      setActivePreviewUrl(selectedGasto.foto_url || `data:image/jpeg;base64,${(selectedGasto as any).base64Foto}`);
                      setViewerVisible(true);
                    }}
                    style={styles.modalImageContainer}
                  >
                    <Image
                      source={{
                        uri: selectedGasto.foto_url || `data:image/jpeg;base64,${(selectedGasto as any).base64Foto}`,
                      }}
                      style={styles.modalImage}
                      resizeMode="contain"
                    />
                  </TouchableOpacity>
                ) : (
                  <View style={[styles.modalNoImage, { backgroundColor: themeColors.backgroundElement }]}>
                    <Ionicons name="image-outline" size={48} color={themeColors.textSecondary} />
                    <Text style={{ color: themeColors.textSecondary }}>Sin fotografía de ticket</Text>
                  </View>
                )}

                <View style={styles.modalDetails}>
                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Monto</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text, fontSize: 20, fontWeight: '800' }]}>
                      {formatCurrency(selectedGasto.monto)}
                    </Text>
                  </View>

                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Proveedor</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text }]}>
                      {GastoHelper.getProveedor(selectedGasto) || 'N/A'}
                    </Text>
                  </View>

                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Fecha de Gasto</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text }]}>
                      {formatFriendlyDate(selectedGasto.fecha_comprobante || selectedGasto.created_at?.split('T')[0])}
                    </Text>
                  </View>

                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Categoría / Subcategoría</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text }]}>
                      {GastoHelper.getCategoria(selectedGasto) || 'Sin Categoría'} {GastoHelper.getSubcategoria(selectedGasto) ? ` > ${GastoHelper.getSubcategoria(selectedGasto)}` : ''}
                    </Text>
                  </View>

                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Método de Pago</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text, textTransform: 'capitalize' }]}>
                      {selectedGasto.metodo_pago} {selectedGasto.tipo_tarjeta ? `(${selectedGasto.tipo_tarjeta})` : ''}
                    </Text>
                  </View>

                  {/* Parsear justificación para ver si hay alerta de IA */}
                  {(() => {
                    const parsed = parseJustificacion(selectedGasto.justificacion);
                    return (
                      <>
                        {parsed.alerta && (
                          <View style={[styles.alertBanner, { backgroundColor: themeColors.danger + '15', borderColor: themeColors.danger, marginBottom: Spacing.two }]}>
                            <Ionicons name="warning-outline" size={22} color={themeColors.danger} style={{ marginTop: 2 }} />
                            <View style={{ flex: 1 }}>
                              <Text style={[styles.alertTitle, { color: themeColors.danger }]}>Alerta de Políticas de Gasto</Text>
                              <Text style={[styles.alertText, { color: themeColors.text }]}>{parsed.alerta}</Text>
                            </View>
                          </View>
                        )}
                        <View style={styles.detailItem}>
                          <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Comentarios</Text>
                          <Text style={[styles.detailValue, { color: themeColors.text }]}>
                            {parsed.justificacion || 'No especificada'}
                          </Text>
                        </View>
                      </>
                    );
                  })()}

                  {(selectedGasto.tipo_servicio_proyecto || selectedGasto.detalle_servicio_proyecto) && (
                    <View style={styles.detailItem}>
                      <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Servicio / Proyecto</Text>
                      <Text style={[styles.detailValue, { color: themeColors.text }]}>
                        {selectedGasto.tipo_servicio_proyecto ? `Tipo: ${selectedGasto.tipo_servicio_proyecto}` : ''}
                        {selectedGasto.detalle_servicio_proyecto ? `\nDetalle: ${selectedGasto.detalle_servicio_proyecto}` : ''}
                      </Text>
                    </View>
                  )}

                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Sucursal / Cliente</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text }]}>
                      {GastoHelper.getSucursal(selectedGasto) ? `Sucursal: ${GastoHelper.getSucursal(selectedGasto)}` : ''}
                      {GastoHelper.getCliente(selectedGasto) ? `${GastoHelper.getSucursal(selectedGasto) ? ' | ' : ''}Cliente: ${GastoHelper.getCliente(selectedGasto)}` : ''}
                      {!GastoHelper.getSucursal(selectedGasto) && !GastoHelper.getCliente(selectedGasto) ? 'N/A' : ''}
                    </Text>
                  </View>

                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Facturación</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text }]}>
                      {selectedGasto.facturado ? 'Sí, Facturado' : 'No Facturado'}
                    </Text>
                  </View>

                  {selectedGasto.facturado ? (
                    <View style={styles.detailItem}>
                      <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Archivo de Factura</Text>
                      {selectedGasto.factura_url || (selectedGasto.isOffline && (selectedGasto as any).base64Factura) ? (
                        <TouchableOpacity
                          style={[styles.invoiceLinkBtn, { backgroundColor: themeColors.accent + '15' }]}
                          onPress={() => {
                            const url = selectedGasto.factura_url;
                            if (url && url.toLowerCase().includes('.pdf')) {
                              Linking.openURL(url).catch(() => {
                                Alert.alert('Error', 'No se pudo abrir el archivo PDF.');
                              });
                            } else {
                              const imgUrl = url || `data:image/jpeg;base64,${(selectedGasto as any).base64Factura}`;
                              setActivePreviewUrl(imgUrl);
                              setViewerVisible(true);
                            }
                          }}
                        >
                          <Ionicons name="image" size={18} color={themeColors.accent} />
                          <Text style={[styles.invoiceLinkText, { color: themeColors.accent }]}>
                            Ver Factura
                          </Text>
                        </TouchableOpacity>
                      ) : (
                        <Text style={[styles.detailValue, { color: themeColors.textSecondary }]}>Sin archivo adjunto</Text>
                      )}
                    </View>
                  ) : (
                    <View style={styles.detailItem}>
                      <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Motivo de No Factura</Text>
                      <Text style={[styles.detailValue, { color: themeColors.text, fontStyle: 'italic' }]}>
                        {selectedGasto.motivo_sin_factura || 'No especificado'}
                      </Text>
                    </View>
                  )}

                  {/* Sección Action Required */}
                  {selectedGasto.status === 'ACTION_REQUIRED' && (
                    <View style={[styles.actionRequiredBox, { borderColor: themeColors.actionRequired }]}>
                      <View style={styles.actionRequiredHeader}>
                        <Ionicons name="alert-circle" size={20} color={themeColors.actionRequired} />
                        <Text style={[styles.actionRequiredTitle, { color: themeColors.actionRequired }]}>
                          ACCIÓN REQUERIDA (Observación del Admin)
                        </Text>
                      </View>
                      <Text style={[styles.observationText, { color: themeColors.text }]}>
                        {`"${selectedGasto.rejection_feedback}"`}
                      </Text>

                      <View style={styles.responseForm}>
                        <CustomButton
                          title="Editar Gasto"
                          onPress={() => {
                            setModalVisible(false);
                            router.push(`/(empleado)/editar-gasto?id=${selectedGasto.id}` as any);
                          }}
                          variant="primary"
                        />
                      </View>
                    </View>
                  )}
                </View>
              </ScrollView>
            )}
          </View>
        </View>
      </Modal>

      {/* Modal de Vehículos y Gasolina (Empleado) */}
      <Modal statusBarTranslucent={true}
        animationType="slide"
        transparent={true}
        visible={employeeVehiculosModalVisible}
        onRequestClose={() => setEmployeeVehiculosModalVisible(false)}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, { backgroundColor: themeColors.background, height: '85%', paddingBottom: Spacing.four }]}>
            <View style={styles.modalHeader}>
              <Text style={[styles.modalTitle, { color: themeColors.text }]}>Vehículos y Gasolina</Text>
              <TouchableOpacity onPress={() => setEmployeeVehiculosModalVisible(false)}>
                <Ionicons name="close" size={24} color={themeColors.text} />
              </TouchableOpacity>
            </View>

            <ScrollView contentContainerStyle={{ paddingBottom: Spacing.four }} style={{ flex: 1 }}>
              
              {/* Sección: Parque Vehicular */}
              <View style={{
                marginHorizontal: Spacing.two,
                marginTop: Spacing.two,
                padding: Spacing.three,
                backgroundColor: themeColors.backgroundElement,
                borderRadius: BorderRadius.medium,
                borderWidth: 1,
                borderColor: themeColors.border,
              }}>
                <Text style={{ fontSize: 15, fontWeight: '700', color: themeColors.text, marginBottom: Spacing.two }}>
                  Vehículos de la Empresa
                </Text>

                {vehiculos.length === 0 ? (
                  <Text style={{ color: themeColors.textSecondary, textAlign: 'center', marginVertical: Spacing.two }}>
                    No hay vehículos registrados para esta empresa.
                  </Text>
                ) : (
                  <View style={{ gap: Spacing.one }}>
                    {vehiculos.map((veh) => (
                      <View
                        key={veh.id}
                        style={{
                          flexDirection: 'row',
                          alignItems: 'center',
                          padding: Spacing.two,
                          backgroundColor: themeColors.background,
                          borderRadius: BorderRadius.small,
                          borderWidth: 1,
                          borderColor: themeColors.border,
                          gap: 10,
                        }}
                      >
                        <Ionicons name="car" size={22} color={themeColors.primary} />
                        <View style={{ flex: 1 }}>
                          <Text style={{ fontWeight: 'bold', color: themeColors.text, fontSize: 13 }}>
                            {veh.marca} {veh.modelo} ({veh.anio})
                          </Text>
                          <Text style={{ fontSize: 11, color: themeColors.textSecondary }}>
                            Placas: <Text style={{ fontWeight: 'bold' }}>{veh.placas}</Text>
                            {veh.numero_economico ? ` • Eco: ${veh.numero_economico}` : ''}
                          </Text>
                        </View>
                      </View>
                    ))}
                  </View>
                )}
              </View>

              {/* Sección: Mis Cargas de Gasolina */}
              <View style={{
                marginHorizontal: Spacing.two,
                marginTop: Spacing.three,
                padding: Spacing.three,
                backgroundColor: themeColors.backgroundElement,
                borderRadius: BorderRadius.medium,
                borderWidth: 1,
                borderColor: themeColors.border,
              }}>
                <Text style={{ fontSize: 15, fontWeight: '700', color: themeColors.text, marginBottom: Spacing.two }}>
                  Mis Consumos de Gasolina
                </Text>

                {misRegistrosGasolina.length === 0 ? (
                  <Text style={{ color: themeColors.textSecondary, textAlign: 'center', marginVertical: Spacing.two }}>
                    No has registrado cargas de combustible.
                  </Text>
                ) : (
                  <View style={{ gap: Spacing.two }}>
                    {misRegistrosGasolina.map((reg) => {
                      const dateParts = reg.fecha.split('-');
                      const formattedDate = dateParts.length === 3 ? `${dateParts[2]}/${dateParts[1]}/${dateParts[0]}` : reg.fecha;
                      return (
                        <View
                          key={reg.id}
                          style={{
                            padding: Spacing.two,
                            backgroundColor: themeColors.background,
                            borderRadius: BorderRadius.small,
                            borderWidth: 1,
                            borderColor: themeColors.border,
                          }}
                        >
                          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', borderBottomWidth: 1, borderBottomColor: themeColors.border, paddingBottom: 6, marginBottom: 6 }}>
                            <Text style={{ fontSize: 11, fontWeight: 'bold', color: themeColors.textSecondary }}>
                              {formattedDate}
                            </Text>
                            <Text style={{ fontSize: 13, fontWeight: 'bold', color: themeColors.success }}>
                              ${Number(reg.costo_total).toLocaleString('es-MX', { minimumFractionDigits: 2 })} MXN
                            </Text>
                          </View>
                          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
                            <View style={{ flex: 1 }}>
                              <Text style={{ fontSize: 11, color: themeColors.textSecondary }}>
                                Vehículo: <Text style={{ color: themeColors.text, fontWeight: '500' }}>{reg.vehiculo_marca} {reg.vehiculo_modelo}</Text>
                              </Text>
                              <Text style={{ fontSize: 11, color: themeColors.textSecondary, marginTop: 2 }}>
                                Carga: <Text style={{ color: themeColors.text }}>{reg.litros} Lts</Text> • Odómetro: <Text style={{ color: themeColors.text }}>{reg.kilometraje_actual} km</Text>
                              </Text>
                            </View>
                            {reg.ticket_foto_url ? (
                              <TouchableOpacity
                                onPress={() => {
                                  setActivePreviewUrl(reg.ticket_foto_url || null);
                                  setViewerVisible(true);
                                }}
