import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TextInput,
  TouchableOpacity,
  ScrollView,
  Platform,
  ActivityIndicator,
  Alert,
  Switch
} from 'react-native';
import { useRouter } from 'expo-router';
import { Ionicons } from '@expo/vector-icons';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useColorScheme } from '@/hooks/use-color-scheme';
import { Colors, Spacing, BorderRadius } from '@/constants/theme';
import { useAuth } from '@/context/AuthContext';
import SelectDropdown from '@/components/SelectDropdown';
import VentaSelectModal from '@/components/VentaSelectModal';
import DateTimePicker from '@react-native-community/datetimepicker';
import { supabase } from '@/services/supabase';
import { TareasService } from '@/services/tareasService';

export default function NuevaTareaScreen() {
  const router = useRouter();
  const scheme = useColorScheme();
  const themeColors = Colors[scheme === 'dark' ? 'dark' : 'light'];
  const { user } = useAuth();

  const [loading, setLoading] = useState(false);
  const [fetchingData, setFetchingData] = useState(false);
  
  // Data lists
  const [usuarios, setUsuarios] = useState<any[]>([]);
  const [clientes, setClientes] = useState<any[]>([]);
  const [ventas, setVentas] = useState<any[]>([]);

  // Form state
  const [titulo, setTitulo] = useState('');
  const [descripcion, setDescripcion] = useState('');
  
  const [fechaCompromiso, setFechaCompromiso] = useState(new Date(Date.now() + 86400000));
  const [showDatePicker, setShowDatePicker] = useState(false);

  const [responsableId, setResponsableId] = useState<string>('');
  const [corresponsables, setCorresponsables] = useState<string[]>([]);
  
  const [vinculoTipo, setVinculoTipo] = useState<'Interno' | 'Cliente'>('Interno');
  const [relacionarVenta, setRelacionarVenta] = useState(false);
  
  const [clienteId, setClienteId] = useState<string>('');
  const [referenciaVentaId, setReferenciaVentaId] = useState<string>('');

  useEffect(() => {
    fetchFormularyData();
  }, [user]);

  const fetchFormularyData = async () => {
    setFetchingData(true);
    try {
      const data = await TareasService.getFormLookups();
      
      let users = data.usuarios || [];
      if (user?.rol === 'EMPLEADO') {
         users = users.filter((u: any) => u.rol === 'EMPLEADO');
      }
      setUsuarios(users);
      setClientes(data.clientes || []);
      setVentas(data.ventas || []);
      
      if (user?.id) {
        setResponsableId(user.id);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setFetchingData(false);
    }
  };

  // Handlers for Corresponsables
  const addCorresponsable = () => {
    setCorresponsables([...corresponsables, '']);
  };
  
  const updateCorresponsable = (index: number, value: string) => {
    const newArr = [...corresponsables];
    newArr[index] = value;
    setCorresponsables(newArr);
  };

  const removeCorresponsable = (index: number) => {
    const newArr = [...corresponsables];
    newArr.splice(index, 1);
    setCorresponsables(newArr);
  };

  // Handlers for Vínculos
  const handleToggleVenta = (val: boolean) => {
    setRelacionarVenta(val);
    setClienteId('');
    setReferenciaVentaId('');
  };

  const handleSave = async () => {
    if (!titulo.trim() || !descripcion.trim() || !responsableId || !fechaCompromiso) {
      if (Platform.OS === 'web') window.alert('Por favor completa todos los campos requeridos.');
      else Alert.alert('Error', 'Por favor completa todos los campos requeridos.');
      return;
    }

    if (vinculoTipo === 'Cliente' && !clienteId) {
      if (Platform.OS === 'web') window.alert('Debes seleccionar un cliente.');
      else Alert.alert('Error', 'Debes seleccionar un cliente.');
      return;
    }

    if (vinculoTipo === 'Cliente' && relacionarVenta && !referenciaVentaId) {
      if (Platform.OS === 'web') window.alert('Debes seleccionar una referencia de venta.');
      else Alert.alert('Error', 'Debes seleccionar una referencia de venta.');
      return;
    }

    setLoading(true);
    try {
      const nuevaTarea = {
        titulo,
        descripcion,
        fecha_compromiso: fechaCompromiso.toISOString(),
        creado_por: user?.id,
        responsable_id: responsableId,
        vinculo_tipo: vinculoTipo === 'Interno' ? 'Interna' : (vinculoTipo === 'Cliente' && relacionarVenta ? 'Venta' : 'Cliente'),
        vinculo_id: vinculoTipo === 'Cliente' ? (relacionarVenta ? referenciaVentaId : clienteId) : null
      };

      await TareasService.createTarea({
        ...nuevaTarea,
        corresponsables: corresponsables.filter(c => c)
      });

      if (Platform.OS === 'web') window.alert('Tarea creada exitosamente');
      else Alert.alert('Éxito', 'Tarea creada exitosamente');
      
      router.back();
    } catch (error) {
      console.error(error);
      if (Platform.OS === 'web') window.alert('Hubo un error al guardar la tarea.');
      else Alert.alert('Error', 'Hubo un error al guardar la tarea.');
    } finally {
      setLoading(false);
    }
  };

  const selectedClienteNombre = clientes.find(c => c.id === clienteId)?.nombre;
  const ventasDisponibles = ventas.filter(v => v.cliente === selectedClienteNombre);

  return (
    <SafeAreaView style={[styles.container, { backgroundColor: themeColors.background }]} edges={['bottom', 'left', 'right']}>
      {/* HEADER */}
      <View style={[styles.header, { borderBottomColor: themeColors.border }]}>
        <View style={styles.backBtn} />
        <Text style={[styles.headerTitle, { color: themeColors.text }]}>Nueva Tarea</Text>
        <TouchableOpacity 
          onPress={handleSave} 
          disabled={loading || fetchingData}
          style={[styles.saveBtn, { opacity: loading || fetchingData ? 0.5 : 1 }]}
        >
          {loading ? (
            <ActivityIndicator size="small" color={themeColors.primary} />
          ) : (
            <Text style={[styles.saveBtnText, { color: themeColors.primary }]}>Guardar</Text>
          )}
        </TouchableOpacity>
      </View>

      <ScrollView style={{ flex: 1 }} contentContainerStyle={styles.scrollContent}>
        
        {/* TÍTULO Y DESCRIPCIÓN */}
        <View style={styles.inputGroup}>
          <Text style={[styles.label, { color: themeColors.text }]}>Título de la Tarea *</Text>
          <TextInput
            style={[styles.input, { backgroundColor: themeColors.backgroundElement, color: themeColors.text, borderColor: themeColors.border }]}
            placeholder="Ej. Revisar expediente de cliente..."
            placeholderTextColor={themeColors.textSecondary}
            value={titulo}
            onChangeText={setTitulo}
          />
        </View>

        <View style={styles.inputGroup}>
          <Text style={[styles.label, { color: themeColors.text }]}>Descripción Detallada *</Text>
          <TextInput
            style={[styles.textArea, { backgroundColor: themeColors.backgroundElement, color: themeColors.text, borderColor: themeColors.border }]}
            placeholder="Describe qué se necesita hacer..."
            placeholderTextColor={themeColors.textSecondary}
            multiline
            numberOfLines={4}
            textAlignVertical="top"
            value={descripcion}
            onChangeText={setDescripcion}
          />
        </View>

        {/* FECHA COMPROMISO */}
        <View style={styles.inputGroup}>
          <Text style={[styles.label, { color: themeColors.text }]}>Fecha de Compromiso *</Text>
          {Platform.OS === 'web' ? (
            // @ts-ignore
            <input 
              type="date"
              value={fechaCompromiso.toISOString().split('T')[0]}
              onClick={(e: any) => {
                try {
                  e.target.showPicker();
                } catch (err) {}
              }}
              onChange={(e: any) => {
                if(e.target.value) setFechaCompromiso(new Date(e.target.value + 'T12:00:00Z'));
              }}
              style={{
                height: 48,
                borderRadius: 8,
                border: `1px solid ${themeColors.border}`,
                backgroundColor: themeColors.backgroundElement,
                color: themeColors.text,
                padding: '0 12px',
                fontSize: 15,
                outline: 'none',
                width: '100%',
                boxSizing: 'border-box',
                cursor: 'pointer'
              }}
            />
          ) : (
            <>
              <TouchableOpacity
                style={[styles.dateBtn, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border }]}
                onPress={() => setShowDatePicker(true)}
              >
                <Text style={{ color: themeColors.text, fontSize: 15 }}>
                  {fechaCompromiso.toLocaleDateString()}
                </Text>
                <Ionicons name="calendar-outline" size={20} color={themeColors.textSecondary} />
              </TouchableOpacity>
              {showDatePicker && (
                <DateTimePicker
                  value={fechaCompromiso}
                  mode="date"
                  display="default"
                  onValueChange={(event, selectedDate) => {
                    setShowDatePicker(Platform.OS === 'ios');
                    if (selectedDate) setFechaCompromiso(selectedDate);
                  }}
                  onDismiss={() => setShowDatePicker(false)}
                />
              )}
            </>
          )}
        </View>

        {/* RESPONSABLE Y CORRESPONSABLES */}
        {fetchingData ? (
          <ActivityIndicator size="large" color={themeColors.accent} style={{ marginVertical: 20 }} />
        ) : (
          <>
            <SelectDropdown
              label="Responsable Principal *"
              data={usuarios}
              value={responsableId}
              onSelect={setResponsableId}
              searchable
              placeholder="Buscar responsable..."
            />

            {responsableId ? (
              <View style={styles.corresponsablesSection}>
                <Text style={[styles.label, { color: themeColors.text }]}>Corresponsables (Opcional)</Text>
                {corresponsables.map((corrId, index) => (
                  <View key={`corr-${index}`} style={styles.corresponsableRow}>
                    <View style={{ flex: 1 }}>
                      <SelectDropdown
                        label=""
                        data={usuarios.filter(u => u.id !== responsableId)} // Exclude main responsible
                        value={corrId}
                        onSelect={(val) => updateCorresponsable(index, val)}
                        searchable
                        placeholder="Seleccionar corresponsable..."
                      />
                    </View>
                    <TouchableOpacity 
                      style={[styles.removeBtn, { backgroundColor: themeColors.danger + '20' }]}
                      onPress={() => removeCorresponsable(index)}
                    >
                      <Ionicons name="trash-outline" size={20} color={themeColors.danger} />
                    </TouchableOpacity>
                  </View>
                ))}
                <TouchableOpacity 
                  style={styles.addCorrBtn} 
                  onPress={addCorresponsable}
                >
                  <Ionicons name="add-circle-outline" size={20} color={themeColors.primary} />
                  <Text style={[styles.addCorrText, { color: themeColors.primary }]}>Agregar corresponsable</Text>
                </TouchableOpacity>
              </View>
            ) : null}
          </>
        )}

        {/* TIPO DE VÍNCULO */}
        <View style={styles.inputGroup}>
          <Text style={[styles.label, { color: themeColors.text }]}>Tipo de Vínculo</Text>
          <View style={styles.pillsContainer}>
            {['Interno', 'Cliente'].map((tipo) => (
              <TouchableOpacity
                key={tipo}
                style={[
                  styles.pill,
                  { 
                    backgroundColor: vinculoTipo === tipo ? themeColors.accent : 'transparent',
                    borderColor: vinculoTipo === tipo ? themeColors.accent : themeColors.border
                  }
                ]}
                onPress={() => {
                  setVinculoTipo(tipo as any);
                  if (tipo === 'Interno') {
                    setRelacionarVenta(false);
                    setClienteId('');
                    setReferenciaVentaId('');
                  }
                }}
              >
                <Text style={{ color: vinculoTipo === tipo ? '#fff' : themeColors.text }}>
                  {tipo}
                </Text>
              </TouchableOpacity>
            ))}
          </View>
        </View>

        {/* LÓGICA DE CLIENTE Y VENTA */}
        {vinculoTipo === 'Cliente' && (
          <View style={[styles.clienteSection, { backgroundColor: themeColors.backgroundElement, borderColor: themeColors.border }]}>
            
            <View style={styles.toggleRow}>
              <Text style={[styles.label, { color: themeColors.text, marginBottom: 0 }]}>Relacionar a una venta</Text>
              <Switch
                value={relacionarVenta}
                onValueChange={handleToggleVenta}
                trackColor={{ false: themeColors.border, true: themeColors.accent + '80' }}
                thumbColor={relacionarVenta ? themeColors.accent : '#f4f3f4'}
              />
            </View>

            <SelectDropdown
              label="Cliente *"
              data={clientes}
              value={clienteId}
              onSelect={(val) => {
                setClienteId(val);
                setReferenciaVentaId(''); // Reset reference when client changes
              }}
              searchable
              placeholder="Buscar cliente..."
            />

            {relacionarVenta && (
              <VentaSelectModal
                label="Referencia de Venta *"
                data={ventasDisponibles}
                value={referenciaVentaId}
                onSelect={setReferenciaVentaId}
                disabled={!clienteId}
                placeholder={!clienteId ? "Primero selecciona un cliente" : "Buscar referencia..."}
              />
            )}
          </View>
        )}

      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: Spacing.four,
    paddingVertical: Spacing.three,
    borderBottomWidth: 1,
  },
  backBtn: {
    padding: 4,
  },
  headerTitle: {
    fontSize: 18,
    fontWeight: '700',
  },
  saveBtn: {
    paddingHorizontal: 12,
    paddingVertical: 6,
  },
  saveBtnText: {
    fontWeight: '600',
    fontSize: 16,
  },
  scrollContent: {
    padding: Spacing.four,
    paddingBottom: 60,
  },
  inputGroup: {
    marginBottom: Spacing.five,
  },
  label: {
    fontSize: 14,
    fontWeight: '600',
    marginBottom: Spacing.two,
  },
  input: {
    height: 48,
    borderWidth: 1,
    borderRadius: BorderRadius.medium,
    paddingHorizontal: Spacing.three,
    fontSize: 15,
  },
  textArea: {
    minHeight: 100,
    borderWidth: 1,
    borderRadius: BorderRadius.medium,
    paddingHorizontal: Spacing.three,
    paddingVertical: Spacing.three,
    fontSize: 15,
  },
  dateBtn: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    height: 48,
    borderWidth: 1,
    borderRadius: BorderRadius.medium,
    paddingHorizontal: Spacing.three,
  },
  corresponsablesSection: {
    marginBottom: Spacing.five,
  },
  corresponsableRow: {
    flexDirection: 'row',
    alignItems: 'flex-start', // Top align because SelectDropdown has a label wrapper usually, but we pass empty string
    gap: Spacing.three,
  },
  removeBtn: {
    height: 48, // Match dropdown height
    width: 48,
    borderRadius: BorderRadius.medium,
    justifyContent: 'center',
    alignItems: 'center',
  },
  addCorrBtn: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: Spacing.two,
    paddingVertical: Spacing.two,
  },
  addCorrText: {
    fontSize: 15,
    fontWeight: '600',
  },
  pillsContainer: {
    flexDirection: 'row',
    gap: Spacing.two,
    flexWrap: 'wrap',
  },
  pill: {
    paddingHorizontal: 16,
    paddingVertical: 8,
    borderRadius: 20,
    borderWidth: 1,
  },
  clienteSection: {
    padding: Spacing.four,
    borderWidth: 1,
    borderRadius: BorderRadius.large,
    marginTop: Spacing.two,
    marginBottom: Spacing.five,
  },
  toggleRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: Spacing.four,
  }
});

import React, { useState, useEffect, useMemo } from 'react';
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  TouchableOpacity,
  ActivityIndicator,
  Alert,
  Modal,
  ScrollView,
  Image,
  Platform,
} from 'react-native';
import { useColorScheme } from '@/hooks/use-color-scheme';
import { useRouter } from 'expo-router';
import { Colors, Spacing, BorderRadius } from '@/constants/theme';
import { supabase, AuthService, Usuario, Evidencia } from '@/services/supabase';
import { useAuth } from '@/context/AuthContext';
import { EvidenceReportGenerator } from '@/utils/evidenceReportGenerator';
import { EvidenceDraftService, EvidenceDraft } from '@/services/evidenceDraftService';
import CustomInput from '@/components/CustomInput';
import CustomButton from '@/components/CustomButton';
import { Ionicons } from '@expo/vector-icons';
import { SafeAreaView } from 'react-native-safe-area-context';
import ImageViewerModal from '@/components/ImageViewerModal';

export default function MiTrabajoScreen() {
  const router = useRouter();
  const { company } = useAuth();
  const scheme = useColorScheme();
  const themeColors = Colors[scheme === 'dark' ? 'dark' : 'light'];

  const [currentUser, setCurrentUser] = useState<Usuario | null>(null);
  const [evidencias, setEvidencias] = useState<Evidencia[]>([]);
  const [drafts, setDrafts] = useState<EvidenceDraft[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Modal de Detalles
  const [selectedEvidencia, setSelectedEvidencia] = useState<Evidencia | null>(null);
  const [modalVisible, setModalVisible] = useState(false);
  const [isModalReady, setIsModalReady] = useState(false);
  const [isExporting, setIsExporting] = useState(false);

  // Modal de imagen a pantalla completa
  const [selectedPhoto, setSelectedPhoto] = useState<string | null>(null);
  const [viewerVisible, setViewerVisible] = useState(false);

  const handleOpenPhoto = (uri: string | null | undefined) => {
    if (uri) {
      setSelectedPhoto(uri);
      setViewerVisible(true);
    }
  };

  const loadEvidencias = async (userId: string, isRefresh = false) => {
    if (isRefresh) {
      setIsRefreshing(true);
    } else {
      setIsLoading(true);
    }

    try {
      const { data, error } = await supabase
        .from('evidencias')
        .select('*')
        .eq('empleado_id', userId)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setEvidencias(data || []);

      // Cargar borradores locales
      const localDrafts = await EvidenceDraftService.getDrafts(userId, company || 'inttec');
      setDrafts(localDrafts);
    } catch (error: any) {
      console.error('Error al cargar evidencias:', error.message);
      Alert.alert('Error', 'No se pudieron cargar las evidencias de trabajo.');
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  };

  const handleDeleteDraft = async (draftId: string) => {
    if (!currentUser) return;
    const confirmDel = async () => {
      await EvidenceDraftService.deleteDraft(currentUser.id, company || 'inttec', draftId);
      const updated = await EvidenceDraftService.getDrafts(currentUser.id, company || 'inttec');
      setDrafts(updated);
    };

    if (Platform.OS === 'web') {
      if (window.confirm('¿Deseas eliminar este borrador?')) {
        await confirmDel();
      }
    } else {
      Alert.alert('Eliminar Borrador', '¿Deseas eliminar este borrador?', [
        { text: 'Cancelar', style: 'cancel' },
        { text: 'Eliminar', style: 'destructive', onPress: confirmDel },
      ]);
    }
  };

  useEffect(() => {
    const init = async () => {
      const user = await AuthService.getCurrentUser();
      if (!user) {
        router.replace('/');
        return;
      }
      setCurrentUser(user);
      await loadEvidencias(user.id);
    };
    init();
  }, [router]);

  const parseTrabajosList = (descStr: string) => {
    if (!descStr) return [];
    if (descStr.trim().startsWith('[')) {
      try {
        const parsed = JSON.parse(descStr);
        if (Array.isArray(parsed)) return parsed;
      } catch {
        // ignore
      }
    }
    return [{ descripcion: descStr }];
  };

  const getCleanDescription = (descStr: string) => {
    const list = parseTrabajosList(descStr);
    if (list.length > 1) {
      return list.map((t: any, i: number) => `#${i + 1}: ${t.descripcion}`).join(' • ');
    }
    return list[0]?.descripcion || descStr;
  };

  const filteredEvidencias = useMemo(() => {
    if (!searchQuery.trim()) {
      return evidencias;
    }
    const q = searchQuery.toLowerCase();
    return evidencias.filter(
      (e) =>
        e.cliente.toLowerCase().includes(q) ||
        e.descripcion_trabajo.toLowerCase().includes(q) ||
        (e.materiales_usados && e.materiales_usados.toLowerCase().includes(q))
    );
  }, [searchQuery, evidencias]);

  const handleRefresh = () => {
    if (currentUser) {
      loadEvidencias(currentUser.id, true);
    }
  };

  const handleExportPDF = async (ev: Evidencia) => {
    setIsExporting(true);
    try {
      await EvidenceReportGenerator.exportToPDF(
        ev,
        ev.empleado_nombre || currentUser?.nombre || 'Técnico Autorizado',
        ev.fotos_adicionales_urls || []
      );
    } catch (err: any) {
      Alert.alert('Error', err.message || 'No se pudo exportar el PDF.');
    } finally {
      setIsExporting(false);
    }
  };

  const formatFriendlyDate = (dateStr?: string | null) => {
    if (!dateStr) return 'N/A';
    try {
      const date = new Date(dateStr);
      // Validar si es una fecha correcta
      if (isNaN(date.getTime())) {
        return dateStr.split('T')[0];
      }
      return date.toLocaleDateString('es-MX', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      });
    } catch {
      return dateStr;
    }
  };

  return (
    <SafeAreaView style={[styles.container, { backgroundColor: themeColors.background }]} edges={['top', 'left', 'right']}>
      {/* Header */}
      <View style={styles.header}>
        <TouchableOpacity
          onPress={() => router.replace('/(empleado)/gastos')}
          style={styles.backBtn}
        >
          <Ionicons name="arrow-back" size={24} color={themeColors.text} />
        </TouchableOpacity>
        <Text style={[styles.headerTitle, { color: themeColors.text }]}>Mi Trabajo</Text>
        <TouchableOpacity
          onPress={() => router.push('/(empleado)/evidencia' as any)}
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            gap: 4,
            backgroundColor: themeColors.primary,
            paddingVertical: 6,
            paddingHorizontal: 10,
            borderRadius: BorderRadius.medium,
          }}
        >
          <Ionicons name="add" size={18} color="#fff" />
          <Text style={{ color: '#fff', fontSize: 12, fontWeight: '700' }}>Nueva</Text>
        </TouchableOpacity>
      </View>

      {/* Search Bar */}
      <View style={styles.searchContainer}>
        <CustomInput
          placeholder="Buscar por cliente, trabajo o material..."
          value={searchQuery}
          onChangeText={setSearchQuery}
          iconName="search-outline"
        />
      </View>

      {/* List */}
      {isLoading ? (
        <View style={styles.loaderContainer}>
          <ActivityIndicator size="large" color={themeColors.accent} />
          <Text style={{ color: themeColors.textSecondary, marginTop: Spacing.one }}>
            Cargando historial de reportes...
          </Text>
        </View>
      ) : (
        <FlatList
          data={filteredEvidencias}
          keyExtractor={(item) => item.id}
          contentContainerStyle={styles.listContent}
          refreshing={isRefreshing}
          onRefresh={handleRefresh}
          ListHeaderComponent={
            drafts.length > 0 ? (
              <View style={{ marginBottom: Spacing.three }}>
                <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, marginBottom: Spacing.one }}>
                  <Ionicons name="document-text" size={16} color={themeColors.warning} />
                  <Text style={{ fontSize: 14, fontWeight: '800', color: themeColors.warning, textTransform: 'uppercase', letterSpacing: 0.5 }}>
                    Borradores Pendientes ({drafts.length})
                  </Text>
                </View>

                {drafts.map((d) => {
                  const totalFotos = (d.trabajos || []).reduce((acc, t) => {
                    let c = 0;
                    if (t.antesImg) c++;
                    if (t.despuesImg) c++;
                    c += (t.fotosAdicionales?.length || 0);
                    return acc + c;
                  }, 0);

                  return (
                    <View
                      key={d.id}
                      style={{
                        backgroundColor: themeColors.warning + '12',
                        borderColor: themeColors.warning,
                        borderWidth: 1,
                        borderRadius: BorderRadius.medium,
                        padding: Spacing.two,
                        marginBottom: Spacing.two,
                      }}
                    >
                      <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                        <View style={{ flex: 1, marginRight: 8 }}>
                          <Text style={{ fontSize: 15, fontWeight: '800', color: themeColors.text }}>
                            {d.clienteNombre || 'Sin cliente asignado'}
                          </Text>
                          {d.sucursalNombre ? (
                            <Text style={{ fontSize: 12, color: themeColors.textSecondary, marginTop: 1 }}>
                              Sucursal: {d.sucursalNombre}
                            </Text>
                          ) : null}
                          <View style={{ flexDirection: 'row', gap: 10, marginTop: 4 }}>
                            <Text style={{ fontSize: 11, color: themeColors.textSecondary }}>
                              🛠️ {d.trabajos?.length || 0} {(d.trabajos?.length || 0) === 1 ? 'trabajo' : 'trabajos'}
                            </Text>
                            <Text style={{ fontSize: 11, color: themeColors.textSecondary }}>
                              📷 {totalFotos} fotos
                            </Text>
                            <Text style={{ fontSize: 11, color: themeColors.textSecondary }}>
                              🕒 {formatFriendlyDate(d.updatedAt)}
                            </Text>
                          </View>
                        </View>

                        <TouchableOpacity
                          onPress={() => handleDeleteDraft(d.id)}
                          style={{ padding: 4 }}
                        >
                          <Ionicons name="trash-outline" size={18} color={themeColors.danger} />
                        </TouchableOpacity>
                      </View>

                      <View style={{ flexDirection: 'row', justifyContent: 'flex-end', marginTop: Spacing.one }}>
                        <TouchableOpacity
                          onPress={() => router.push(`/(empleado)/evidencia?draftId=${d.id}` as any)}
                          style={{
                            backgroundColor: themeColors.warning,
                            paddingVertical: 6,
                            paddingHorizontal: 12,
                            borderRadius: BorderRadius.small,
                            flexDirection: 'row',
                            alignItems: 'center',
                            gap: 4,
                          }}
                        >
                          <Ionicons name="create-outline" size={15} color="#fff" />
                          <Text style={{ color: '#fff', fontSize: 12, fontWeight: '700' }}>Continuar Borrador</Text>
                        </TouchableOpacity>
                      </View>
                    </View>
                  );
                })}

                <View style={{ borderBottomWidth: 1, borderBottomColor: themeColors.border, marginVertical: Spacing.two }} />
                <Text style={{ fontSize: 13, fontWeight: '800', color: themeColors.textSecondary, textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: Spacing.one }}>
                  Reportes Publicados ({filteredEvidencias.length})
                </Text>
              </View>
            ) : null
          }
          renderItem={({ item }) => (
            <TouchableOpacity
              activeOpacity={0.7}
              style={[
                styles.card,
                {
                  backgroundColor: themeColors.backgroundElement,
                  borderColor: themeColors.border,
                },
              ]}
              onPress={() => {
                setSelectedEvidencia(item);
                setModalVisible(true);
                setTimeout(() => {
                  setIsModalReady(true);
                }, 200);
              }}
            >
              <View style={styles.cardHeader}>
                <Text style={[styles.cardClient, { color: themeColors.text }]} numberOfLines={1}>
                  {item.cliente}
                </Text>
                <Text style={[styles.cardDate, { color: themeColors.textSecondary }]}>
                  {formatFriendlyDate(item.created_at).split(',')[0]}
                </Text>
              </View>

              <Text style={[styles.cardDesc, { color: themeColors.textSecondary }]} numberOfLines={2}>
                {getCleanDescription(item.descripcion_trabajo)}
              </Text>

              <View style={styles.cardFooter}>
                <View style={styles.indicatorGroup}>
                  {item.foto_antes_url && (
                    <View style={[styles.indicator, { backgroundColor: themeColors.danger + '20' }]}>
                      <Text style={[styles.indicatorText, { color: themeColors.danger }]}>Antes</Text>
                    </View>
                  )}
                  {item.foto_despues_url && (
                    <View style={[styles.indicator, { backgroundColor: themeColors.success + '20' }]}>
                      <Text style={[styles.indicatorText, { color: themeColors.success }]}>Después</Text>
                    </View>
                  )}
                  {item.resumen_ia && (
                    <View style={[styles.indicator, { backgroundColor: themeColors.accent + '20' }]}>
                      <Ionicons name="sparkles" size={10} color={themeColors.accent} />
                      <Text style={[styles.indicatorText, { color: themeColors.accent, marginLeft: 2 }]}>IA</Text>
                    </View>
                  )}
                </View>
                <Ionicons name="chevron-forward" size={16} color={themeColors.textSecondary} />
              </View>
            </TouchableOpacity>
          )}
          ListEmptyComponent={
            <View style={styles.emptyContainer}>
              <Ionicons name="briefcase-outline" size={64} color={themeColors.textSecondary} />
              <Text style={[styles.emptyText, { color: themeColors.textSecondary }]}>
                {searchQuery.trim()
                  ? 'No se encontraron reportes que coincidan con la búsqueda.'
                  : 'Aún no has registrado ningún reporte de evidencia de trabajo.'}
              </Text>
            </View>
          }
        />
      )}

      {/* Modal de Detalle */}
      <Modal statusBarTranslucent={true}
        animationType="slide"
        transparent={true}
        visible={modalVisible}
        onRequestClose={() => {
          setModalVisible(false);
          setIsModalReady(false);
        }}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, { backgroundColor: themeColors.background }]}>
            <View style={styles.modalHeader}>
              <Text style={[styles.modalTitle, { color: themeColors.text }]}>Detalle del Reporte</Text>
              <TouchableOpacity
                onPress={() => {
                  setModalVisible(false);
                  setIsModalReady(false);
                  setSelectedEvidencia(null);
                }}
              >
                <Ionicons name="close" size={24} color={themeColors.text} />
              </TouchableOpacity>
            </View>

            {selectedEvidencia && isModalReady ? (
              <ScrollView contentContainerStyle={styles.modalScroll}>
                {/* Fotos de Evidencia */}
                <View style={styles.evidencePhotosContainer}>
                  {selectedEvidencia.foto_antes_url ? (
                    <TouchableOpacity
                      activeOpacity={0.9}
                      onPress={() => handleOpenPhoto(selectedEvidencia.foto_antes_url)}
                      style={styles.photoWrapper}
                    >
                      <Text style={[styles.photoTypeLabel, { color: themeColors.danger }]}>Antes</Text>
                      <Image
                        source={{ uri: selectedEvidencia.foto_antes_url }}
                        style={styles.modalImage}
                        resizeMode="cover"
                      />
                    </TouchableOpacity>
                  ) : (
                    <View style={[styles.modalNoImage, { backgroundColor: themeColors.backgroundElement }]}>
                      <Ionicons name="camera-outline" size={32} color={themeColors.textSecondary} />
                      <Text style={{ color: themeColors.textSecondary, fontSize: 11 }}>Sin foto del Antes</Text>
                    </View>
                  )}

                  {selectedEvidencia.foto_despues_url ? (
                    <TouchableOpacity
                      activeOpacity={0.9}
                      onPress={() => handleOpenPhoto(selectedEvidencia.foto_despues_url)}
                      style={styles.photoWrapper}
                    >
                      <Text style={[styles.photoTypeLabel, { color: themeColors.success }]}>Después</Text>
                      <Image
                        source={{ uri: selectedEvidencia.foto_despues_url }}
                        style={styles.modalImage}
                        resizeMode="cover"
                      />
                    </TouchableOpacity>
                  ) : (
                    <View style={[styles.modalNoImage, { backgroundColor: themeColors.backgroundElement }]}>
                      <Ionicons name="camera-outline" size={32} color={themeColors.textSecondary} />
                      <Text style={{ color: themeColors.textSecondary, fontSize: 11 }}>Sin foto del Después</Text>
                    </View>
                  )}
                </View>

                {/* Campos de Información */}
                <View style={styles.modalDetails}>
                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Cliente / Ubicación</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text }]}>
                      {selectedEvidencia.cliente}
                    </Text>
                  </View>

                  <View style={styles.detailItem}>
                    <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Fecha de Registro</Text>
                    <Text style={[styles.detailValue, { color: themeColors.text }]}>
                      {formatFriendlyDate(selectedEvidencia.created_at)}
                    </Text>
                  </View>

                  {(() => {
                    let listTrabajos: any[] = [];
                    let isJson = false;
                    try {
                      if (selectedEvidencia.descripcion_trabajo && selectedEvidencia.descripcion_trabajo.trim().startsWith('[')) {
                        listTrabajos = JSON.parse(selectedEvidencia.descripcion_trabajo);
                        isJson = true;
                      }
                    } catch {}

                    if (isJson && listTrabajos.length > 0) {
                      return (
                        <View style={{ marginTop: Spacing.two, marginBottom: Spacing.two }}>
                          <Text style={[styles.detailLabel, { color: themeColors.textSecondary, marginBottom: Spacing.one }]}>
                            Trabajos Realizados ({listTrabajos.length})
                          </Text>
                          {listTrabajos.map((t: any, index: number) => (
                            <View key={index} style={{
                              marginBottom: Spacing.two,
                              padding: Spacing.two,
                              borderWidth: 1,
                              borderColor: themeColors.border,
                              borderRadius: BorderRadius.medium,
                              backgroundColor: themeColors.backgroundElement
                            }}>
                              <Text style={{ fontWeight: '700', fontSize: 13, color: themeColors.accent, marginBottom: 4 }}>
                                Trabajo #{index + 1}
                              </Text>
                              <Text style={{ fontSize: 13, color: themeColors.text, marginBottom: 2 }}>
                                <Text style={{ fontWeight: '600' }}>Situación: </Text>{t.descripcion}
                              </Text>
                              {t.materiales && (
                                <Text style={{ fontSize: 12, color: themeColors.textSecondary, marginBottom: 2 }}>
                                  <Text style={{ fontWeight: '600' }}>Materiales: </Text>{t.materiales}
                                </Text>
                              )}
                              {(t.solucion || t.observaciones) && (
                                <Text style={{ fontSize: 12, color: themeColors.textSecondary, marginBottom: 4 }}>
                                  <Text style={{ fontWeight: '600' }}>Solución: </Text>{t.solucion || t.observaciones}
                                </Text>
                              )}

                              {/* Fotos antes / despues / adicionales de este trabajo si vienen en el json */}
                              {(t.antesImg || t.despuesImg || (t.fotosAdicionales && t.fotosAdicionales.length > 0)) && (
                                <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginTop: 6 }}>
                                  {t.antesImg && (
                                    <TouchableOpacity activeOpacity={0.9} onPress={() => handleOpenPhoto(t.antesImg)} style={{ marginRight: 8, alignItems: 'center' }}>
                                      <Image source={{ uri: t.antesImg }} style={{ width: 60, height: 60, borderRadius: 6 }} resizeMode="cover" />
                                      <Text style={{ fontSize: 9, color: themeColors.danger, fontWeight: '700', marginTop: 2 }}>Antes</Text>
                                    </TouchableOpacity>
                                  )}
                                  {t.despuesImg && (
                                    <TouchableOpacity activeOpacity={0.9} onPress={() => handleOpenPhoto(t.despuesImg)} style={{ marginRight: 8, alignItems: 'center' }}>
                                      <Image source={{ uri: t.despuesImg }} style={{ width: 60, height: 60, borderRadius: 6 }} resizeMode="cover" />
                                      <Text style={{ fontSize: 9, color: themeColors.success, fontWeight: '700', marginTop: 2 }}>Después</Text>
                                    </TouchableOpacity>
                                  )}
                                  {Array.isArray(t.fotosAdicionales) && t.fotosAdicionales.map((fUri: string, fIdx: number) => (
                                    <TouchableOpacity key={fIdx} activeOpacity={0.9} onPress={() => handleOpenPhoto(fUri)} style={{ marginRight: 8, alignItems: 'center' }}>
                                      <Image source={{ uri: fUri }} style={{ width: 60, height: 60, borderRadius: 6 }} resizeMode="cover" />
                                      <Text style={{ fontSize: 9, color: themeColors.accent, fontWeight: '700', marginTop: 2 }}>#{fIdx + 1}</Text>
                                    </TouchableOpacity>
                                  ))}
                                </ScrollView>
                              )}
                            </View>
                          ))}
                        </View>
                      );
                    }

                    return (
                      <>
                        <View style={styles.detailItem}>
                          <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Situación encontrada</Text>
                          <Text style={[styles.detailValue, { color: themeColors.text }]}>
                            {selectedEvidencia.descripcion_trabajo}
                          </Text>
                        </View>

                        {selectedEvidencia.materiales_usados && (
                          <View style={styles.detailItem}>
                            <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Materiales Utilizados</Text>
                            <Text style={[styles.detailValue, { color: themeColors.text }]}>
                              {selectedEvidencia.materiales_usados}
                            </Text>
                          </View>
                        )}

                        {selectedEvidencia.observaciones && (
                          <View style={styles.detailItem}>
                            <Text style={[styles.detailLabel, { color: themeColors.textSecondary }]}>Observaciones</Text>
                            <Text style={[styles.detailValue, { color: themeColors.text }]}>
                              {selectedEvidencia.observaciones}
                            </Text>
                          </View>
                        )}
                      </>
                    );
                  })()}

                  {selectedEvidencia.fotos_adicionales_urls && selectedEvidencia.fotos_adicionales_urls.length > 0 && (
                    <View style={styles.detailItem}>
                      <Text style={[styles.detailLabel, { color: themeColors.textSecondary, marginBottom: Spacing.two }]}>
                        Fotos Adicionales
                      </Text>
                      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.adicionalPhotosScroll}>
                        {selectedEvidencia.fotos_adicionales_urls.map((url, index) => (
                          <TouchableOpacity
                            key={index}
                            activeOpacity={0.9}
                            onPress={() => handleOpenPhoto(url)}
                            style={styles.adicionalPhotoCard}
                          >
                            <Image source={{ uri: url }} style={styles.adicionalModalImage} resizeMode="cover" />
                          </TouchableOpacity>
                        ))}
                      </ScrollView>
                    </View>
                  )}

                  {/* Resumen IA */}
                  {selectedEvidencia.resumen_ia && (
                    <View style={styles.aiReportSection}>
                      <View style={styles.aiHeader}>
                        <Ionicons name="sparkles" size={18} color={themeColors.accent} />
                        <Text style={[styles.aiTitle, { color: themeColors.accent }]}>
                          Análisis Técnico IA (Gemini)
                        </Text>
                      </View>
                      <View
                        style={[
                          styles.aiReportBox,
                          {
                            backgroundColor: themeColors.backgroundElement,
                            borderColor: themeColors.border,
                          },
                        ]}
                      >
                        <Text style={[styles.aiText, { color: themeColors.text }]}>
                          {selectedEvidencia.resumen_ia}
                        </Text>
                      </View>
                    </View>
                  )}
                </View>

                {/* Acciones */}
                <View style={styles.modalActionContainer}>
                  <CustomButton
                    title="COMPARTIR REPORTE (PDF)"
                    onPress={() => handleExportPDF(selectedEvidencia)}
                    loading={isExporting}
                    variant="primary"
                    icon={<Ionicons name="document-text-outline" size={20} color="#ffffff" style={{ marginRight: 8 }} />}
                  />
                </View>
              </ScrollView>
            ) : (
              <View style={styles.loaderContainer}>
                <ActivityIndicator size="large" color={themeColors.accent} />
              </View>
            )}
          </View>
        </View>
      </Modal>

      {/* Botón Flotante para Registrar Evidencia */}
      <TouchableOpacity
        activeOpacity={0.8}
        onPress={() => router.push('/(empleado)/evidencia')}
        style={[styles.fab, { backgroundColor: themeColors.success }]}
      >
        <Ionicons name="camera" size={24} color="#ffffff" />
      </TouchableOpacity>

      <ImageViewerModal
        visible={viewerVisible}
        imageUrl={selectedPhoto}
        onClose={() => setViewerVisible(false)}
      />
    </SafeAreaView>
  );
}

