                      </View>
                      {item.descripcion && (
                        <Text style={[styles.itemDesc, { color: themeColors.textSecondary, marginTop: 4 }]}>
                          {item.descripcion}
                        </Text>
                      )}
                    </TouchableOpacity>
                  );
                }
              }}
            />
          </View>
        </View>
      </Modal>
    </View>
  );
}

