import React, { useRef, useEffect, useState, useImperativeHandle, forwardRef } from 'react';
import { Animated, PanResponder, View, Platform, StyleSheet, Dimensions } from 'react-native';

export interface ZoomableViewRef {
  zoomIn: (step?: number) => void;
  zoomOut: (step?: number) => void;
  reset: () => void;
  rotate: (degrees?: number) => void;
  getScale: () => number;
  getRotation: () => number;
}

interface Props {
  children: React.ReactNode;
  onScaleChange?: (scale: number) => void;
  onRotationChange?: (rotation: number) => void;
  minScale?: number;
  maxScale?: number;
  initialRotation?: number;
}

const ZoomableView = forwardRef<ZoomableViewRef, Props>(({
  children,
  onScaleChange,
  onRotationChange,
  minScale = 1,
  maxScale = 8,
  initialRotation = 0,
}, ref) => {
  const scale = useRef(new Animated.Value(1)).current;
  const translateX = useRef(new Animated.Value(0)).current;
  const translateY = useRef(new Animated.Value(0)).current;
  const rotateAnim = useRef(new Animated.Value(initialRotation)).current;

  const currentScale = useRef(1);
  const currentTranslateX = useRef(0);
  const currentTranslateY = useRef(0);
  const currentRotation = useRef(initialRotation);

  const containerRef = useRef<View>(null);
  const [isDraggingWeb, setIsDraggingWeb] = useState(false);

  // Sync state values with Animated listeners
  useEffect(() => {
    const scaleSub = scale.addListener(({ value }) => {
      currentScale.current = value;
      onScaleChange?.(value);
    });
    const txSub = translateX.addListener(({ value }) => {
      currentTranslateX.current = value;
    });
    const tySub = translateY.addListener(({ value }) => {
      currentTranslateY.current = value;
    });
    const rotSub = rotateAnim.addListener(({ value }) => {
      currentRotation.current = value;
      onRotationChange?.(value);
    });

    return () => {
      scale.removeListener(scaleSub);
      translateX.removeListener(txSub);
      translateY.removeListener(tySub);
      rotateAnim.removeListener(rotSub);
    };
  }, [scale, translateX, translateY, rotateAnim, onScaleChange, onRotationChange]);

  // Imperative ref methods
  useImperativeHandle(ref, () => ({
    zoomIn: (step = 0.5) => {
      const nextScale = Math.min(currentScale.current + step, maxScale);
      animateTo(nextScale, currentTranslateX.current, currentTranslateY.current);
    },
    zoomOut: (step = 0.5) => {
      const nextScale = Math.max(currentScale.current - step, minScale);
      if (nextScale <= minScale) {
        animateTo(minScale, 0, 0);
      } else {
        animateTo(nextScale, currentTranslateX.current, currentTranslateY.current);
      }
    },
    reset: () => {
      animateTo(1, 0, 0);
      animateRotationTo(0);
    },
    rotate: (degrees = 90) => {
      const nextRotation = (currentRotation.current + degrees) % 360;
      animateRotationTo(nextRotation);
    },
    getScale: () => currentScale.current,
    getRotation: () => currentRotation.current,
  }));

  const animateTo = (targetScale: number, targetTx: number, targetTy: number) => {
    Animated.parallel([
      Animated.spring(scale, {
        toValue: targetScale,
        friction: 8,
        tension: 50,
        useNativeDriver: false,
      }),
      Animated.spring(translateX, {
        toValue: targetTx,
        friction: 8,
        tension: 50,
        useNativeDriver: false,
      }),
      Animated.spring(translateY, {
        toValue: targetTy,
        friction: 8,
        tension: 50,
        useNativeDriver: false,
      }),
    ]).start();
  };

  const animateRotationTo = (targetRot: number) => {
    Animated.spring(rotateAnim, {
      toValue: targetRot,
      friction: 8,
      tension: 50,
      useNativeDriver: false,
    }).start();
  };

  // ==========================================
  // WEB MOUSE & TRACKPAD EVENT HANDLERS
  // ==========================================
  const dragStartRef = useRef<{ startX: number; startY: number; initTx: number; initTy: number } | null>(null);
  const lastClickTime = useRef(0);

  const handleMouseDownWeb = (e: any) => {
    if (Platform.OS !== 'web') return;
    if (e.button !== 0) return; // Only left click

    // Double click detection to toggle zoom
    const now = Date.now();
    if (now - lastClickTime.current < 300) {
      // Double click!
      if (currentScale.current > 1.2) {
        animateTo(1, 0, 0);
      } else {
        // Zoom in centered on click position
        const rect = e.currentTarget?.getBoundingClientRect?.() || { left: 0, top: 0, width: Dimensions.get('window').width, height: Dimensions.get('window').height };
        const cursorX = e.clientX - (rect.left + rect.width / 2);
        const cursorY = e.clientY - (rect.top + rect.height / 2);
        const targetScale = 2.5;
        const targetTx = -cursorX * 1.5;
        const targetTy = -cursorY * 1.5;
        animateTo(targetScale, targetTx, targetTy);
      }
      lastClickTime.current = 0;
      return;
    }
    lastClickTime.current = now;

    dragStartRef.current = {
      startX: e.clientX,
      startY: e.clientY,
      initTx: currentTranslateX.current,
      initTy: currentTranslateY.current,
    };
    setIsDraggingWeb(true);

    const onMouseMove = (moveEvent: MouseEvent) => {
      if (!dragStartRef.current) return;
      const dx = moveEvent.clientX - dragStartRef.current.startX;
      const dy = moveEvent.clientY - dragStartRef.current.startY;
      translateX.setValue(dragStartRef.current.initTx + dx);
      translateY.setValue(dragStartRef.current.initTy + dy);
    };

    const onMouseUp = () => {
      dragStartRef.current = null;
      setIsDraggingWeb(false);
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
    };

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
  };

  const handleWheelWeb = (e: any) => {
    if (Platform.OS !== 'web') return;
    try {
      e.preventDefault();
      e.stopPropagation();
    } catch {}

    const rect = e.currentTarget?.getBoundingClientRect?.() || { left: 0, top: 0, width: Dimensions.get('window').width, height: Dimensions.get('window').height };
    const cursorX = e.clientX - (rect.left + rect.width / 2);
    const cursorY = e.clientY - (rect.top + rect.height / 2);

    // Trackpad 2-finger pan (when ctrlKey is false and already zoomed in)
    if (!e.ctrlKey && currentScale.current > 1.05 && Math.abs(e.deltaX) > 0 && Math.abs(e.deltaY) < 40) {
      translateX.setValue(currentTranslateX.current - e.deltaX);
      translateY.setValue(currentTranslateY.current - e.deltaY);
      return;
    }

    // Zooming with Wheel or Trackpad Pinch
    const zoomSensitivity = e.ctrlKey ? 0.01 : 0.0025;
    const delta = -e.deltaY * zoomSensitivity;
    let nextScale = currentScale.current * (1 + delta);
    nextScale = Math.min(Math.max(minScale, nextScale), maxScale);

    if (nextScale <= minScale) {
      animateTo(minScale, 0, 0);
      return;
    }

    // Zoom centered at cursor
    const scaleRatio = nextScale / currentScale.current;
    const nextTx = cursorX - (cursorX - currentTranslateX.current) * scaleRatio;
    const nextTy = cursorY - (cursorY - currentTranslateY.current) * scaleRatio;

    scale.setValue(nextScale);
    translateX.setValue(nextTx);
    translateY.setValue(nextTy);
  };

  // ==========================================
  // MOBILE TOUCH & PANRESPONDER HANDLERS
  // ==========================================
  const initialDistance = useRef<number | null>(null);
  const initialScaleOnPinch = useRef<number>(1);
  const lastTouchTime = useRef(0);

  const calcDistance = (touches: any[]) => {
    const dx = touches[0].pageX - touches[1].pageX;
    const dy = touches[0].pageY - touches[1].pageY;
    return Math.sqrt(dx * dx + dy * dy);
  };

  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: (evt) => {
        translateX.setOffset(currentTranslateX.current);
        translateY.setOffset(currentTranslateY.current);
        translateX.setValue(0);
        translateY.setValue(0);
        initialDistance.current = null;

        // Double tap on mobile
        const now = Date.now();
        if (evt.nativeEvent.touches.length === 1) {
          if (now - lastTouchTime.current < 300) {
            if (currentScale.current > 1.2) {
              animateTo(1, 0, 0);
            } else {
              animateTo(2.5, 0, 0);
            }
            lastTouchTime.current = 0;
            return;
          }
          lastTouchTime.current = now;
        }
      },
      onPanResponderMove: (evt, gestureState) => {
        const touches = evt.nativeEvent.touches;
        if (touches && touches.length === 2) {
          // Pinch Zoom
          const distance = calcDistance(touches);
          if (initialDistance.current === null) {
            initialDistance.current = distance;
            initialScaleOnPinch.current = currentScale.current;
          } else {
            const scaleFactor = distance / initialDistance.current;
            let newScale = initialScaleOnPinch.current * scaleFactor;
            newScale = Math.min(Math.max(minScale, newScale), maxScale);
            scale.setValue(newScale);
          }
        } else if (touches && touches.length === 1) {
          // 1 Finger Drag / Pan (allowed when zoomed in or dragging)
          if (currentScale.current > 1.05) {
            translateX.setValue(gestureState.dx);
            translateY.setValue(gestureState.dy);
          }
        }
      },
      onPanResponderRelease: () => {
        translateX.flattenOffset();
        translateY.flattenOffset();

        if (currentScale.current <= 1.05) {
          animateTo(1, 0, 0);
        }
      },
      onPanResponderTerminate: () => {
        translateX.flattenOffset();
        translateY.flattenOffset();
      },
    })
  ).current;

  // Rotation string for transform
  const rotateInterpolated = rotateAnim.interpolate({
    inputRange: [0, 360],
    outputRange: ['0deg', '360deg'],
  });

  const webCursor = isDraggingWeb
    ? 'grabbing'
    : currentScale.current > 1.05
    ? 'grab'
    : 'zoom-in';

  return (
    <View
      ref={containerRef}
      style={[
        styles.container,
        Platform.OS === 'web' && ({
          cursor: webCursor,
          userSelect: 'none',
          touchAction: 'none',
        } as any),
      ]}
      {...(Platform.OS !== 'web' ? panResponder.panHandlers : {})}
      // @ts-ignore
      onMouseDown={Platform.OS === 'web' ? handleMouseDownWeb : undefined}
      // @ts-ignore
      onWheel={Platform.OS === 'web' ? handleWheelWeb : undefined}
    >
      <Animated.View
        style={[
          styles.content,
          Platform.OS === 'web' && ({
            pointerEvents: 'none', // Allows drag events to stay on container smoothly
          } as any),
          {
            transform: [
              { translateX },
              { translateY },
              { scale },
              { rotate: rotateInterpolated },
            ],
          },
        ]}
      >
        {children}
      </Animated.View>
    </View>
  );
});

export default ZoomableView;

const styles = StyleSheet.create({
  container: {
    flex: 1,
    width: '100%',
    height: '100%',
    overflow: 'hidden',
    justifyContent: 'center',
    alignItems: 'center',
  },
  content: {
    width: '100%',
    height: '100%',
    justifyContent: 'center',
    alignItems: 'center',
  },
});

import React, { createContext, useContext, useEffect, useState } from 'react';
import { AuthService, Usuario, CompanyService, EnvService } from '@/services/supabase';
import { CatalogService } from '@/services/catalogService';
import { useRouter, useSegments } from 'expo-router';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { PushNotificationService } from '@/services/pushNotifications';
import { Platform } from 'react-native';

interface AuthContextType {
  user: Usuario | null;
  isLoading: boolean;
  company: 'inttec' | 'daravisa';
  env: 'cloud' | 'test';
  refreshSession: () => Promise<void>;
  setUser: React.Dispatch<React.SetStateAction<Usuario | null>>;
  changeCompany: (newCompany: 'inttec' | 'daravisa') => Promise<void>;
  changeEnv: (newEnv: 'cloud' | 'test') => Promise<void>;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  isLoading: true,
  company: 'inttec',
  env: 'cloud',
  refreshSession: async () => {},
  setUser: () => {},
  changeCompany: async () => {},
  changeEnv: async () => {},
});

export const useAuth = () => useContext(AuthContext);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<Usuario | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [company, setCompanyState] = useState<'inttec' | 'daravisa'>('inttec');
  const [env, setEnvState] = useState<'cloud' | 'test'>('cloud');
  const segments = useSegments();
  const router = useRouter();

  const refreshSession = async () => {
    try {
      setIsLoading(true);
      const currentUser = await AuthService.getCurrentUser();
      setUser(currentUser);
    } catch (error) {
      console.error('Error fetching user context:', error);
      setUser(null);
    } finally {
      setIsLoading(false);
    }
  };

  const changeCompany = async (newCompany: 'inttec' | 'daravisa') => {
    setIsLoading(true);
    try {
      const currentEmail = user?.email;
      const currentRole = user?.rol;

      // Copiar el token JWT al nuevo entorno ANTES de cambiar la empresa
      // para que getApiHeaders() pueda enviarlo en las llamadas de catálogo.
      const currentToken = await AsyncStorage.getItem(`jwt_token_${company}`);
      if (currentToken) {
        await AsyncStorage.setItem(`jwt_token_${newCompany}`, currentToken);
      }

      await CompanyService.setActiveCompany(newCompany);
      setCompanyState(newCompany);
      
      let currentUser = await AuthService.getCurrentUser();

      // Siempre actualizamos el usuario desde el backend al cambiar de empresa
      // para garantizar que el rol y otros datos estén sincronizados.
      if (currentEmail) {
        const allUsers = await CatalogService.getUsuarios();
        const dbUser = allUsers.find((u: Usuario) => u.email?.trim().toLowerCase() === currentEmail.trim().toLowerCase());

        if (dbUser) {
          // Si el rol en la sesión activa es diferente al del usuario (por falta de sincronización previa),
          // mantenemos el rol activo y lo sincronizamos en la base de datos de la nueva empresa
          if (currentRole && dbUser.rol !== currentRole) {
            try {
              await CatalogService.actualizarUsuario(dbUser.id, { rol: currentRole });
              dbUser.rol = currentRole;
            } catch (syncErr) {
              console.warn('Could not sync user role across company:', syncErr);
            }
          }

          await AsyncStorage.setItem(`logged_user_${newCompany}`, JSON.stringify(dbUser));
          
          currentUser = dbUser as Usuario;
        } else {
          await AsyncStorage.removeItem(`logged_user_${newCompany}`);
          await AsyncStorage.removeItem(`jwt_token_${newCompany}`);
          currentUser = null;
        }
      }

      setUser(currentUser);
    } catch (error) {
      console.error('Error changing company:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const changeEnv = async (newEnv: 'cloud' | 'test') => {
    setIsLoading(true);
    try {
      await EnvService.setActiveEnv(newEnv);
      setEnvState(newEnv);
      
      const currentEmail = user?.email;
      let currentUser = null;

      if (currentEmail) {
        const allUsers = await CatalogService.getUsuarios();
        const dbUser = allUsers.find((u: Usuario) => u.email?.trim().toLowerCase() === currentEmail.trim().toLowerCase());

        if (dbUser) {
          await AsyncStorage.setItem(`logged_user_${company}`, JSON.stringify(dbUser));
          currentUser = dbUser as Usuario;
        } else {
          await AsyncStorage.removeItem(`logged_user_${company}`);
        }
      }
      
      setUser(currentUser);

      // Force a reload of the app to clear all hooks/states
      if (Platform.OS === 'web') {
        window.location.reload();
      } else {
        try {
          const Updates = require('expo-updates');
          await Updates.reloadAsync();
        } catch (e) {
          console.warn('Updates.reloadAsync not available');
        }
      }
    } catch (error) {
      console.error('Error changing env:', error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    let active = true;
    const initSession = async () => {
      try {
        const savedCompany = await CompanyService.loadSavedCompany();
        if (active) setCompanyState(savedCompany);
        const savedEnv = await EnvService.loadSavedEnv();
        if (active) setEnvState(savedEnv);
        
        const currentUser = await AuthService.getCurrentUser();
        if (active) setUser(currentUser);
      } catch (error) {
        console.error('Error fetching user context:', error);
        if (active) setUser(null);
      } finally {
        if (active) setIsLoading(false);
      }
    };
    initSession();
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    if (user) {
      PushNotificationService.registerForPushNotificationsAsync().then(token => {
        if (token) {
          // Update user row in DB with this token
          CatalogService.actualizarUsuario(user.id, { expo_push_token: token } as any).catch(err => {
            console.error('Error saving push token:', err);
          });
        }
      });
    }
  }, [user]);

  useEffect(() => {
    if (isLoading) return;

    const rootSegment = segments[0] as string | undefined;
    const inAuthGroup = rootSegment === '(admin)' || rootSegment === '(empleado)';

    if (!user && inAuthGroup) {
      // Redirect to login if not authenticated and trying to access protected groups
      router.replace('/');
    } else if (user) {
      // If user is authenticated and is not in a protected group (e.g. login screen)
      if (!inAuthGroup) {
        if (user.rol === 'ADMIN' || user.rol === 'DEV') {
          router.replace('/(admin)/dashboard');
        } else {
          router.replace('/(empleado)/gastos');
        }
      } else if (rootSegment === '(admin)' && user.rol !== 'ADMIN' && user.rol !== 'DEV') {
         // Redirect to their actual role if they try to access wrong group
         router.replace('/(empleado)/gastos');
      } else if (rootSegment === '(empleado)' && user.rol === 'ADMIN') {
         router.replace('/(admin)/dashboard');
      }
    }
  }, [user, isLoading, segments, router]);

  return (
    <AuthContext.Provider value={{ user, isLoading, company, env, refreshSession, setUser, changeCompany, changeEnv }}>
      {children}
    </AuthContext.Provider>
  );
}

import { logger } from '@/utils/logger';
import {
  CatalogoItem,
