  // Filas de impuestos trasladados y retenidos
  const trasladosHtml = data.impuestosTrasladados.map((t) => `
    <tr>
      <td class="t-label">Impuestos trasladados &nbsp; ${t.impuesto} &nbsp; ${t.tasa}</td>
