  // QR Code URL (Usa API estándar para renderizar el QR oficial del SAT)
  const qrImgSrc = `https://api.qrserver.com/v1/create-qr-code/?size=140x140&margin=0&data=${encodeURIComponent(data.qrUrl)}`;

